    def readAbstractCanCommunicationControllerCanControllerAttributes(self, element: ET.Element, controller: AbstractCanCommunicationController):
        for child_element in self.findall(element, "CAN-CONTROLLER-ATTRIBUTES/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "CAN-CONTROLLER-CONFIGURATION-REQUIREMENTS":
                requirements = CanControllerConfigurationRequirements()
                self.readCanControllerConfigurationRequirements(child_element, requirements)
                controller.setCanControllerAttributes(requirements)
            elif tag_name == "CAN-CONTROLLER-CONFIGURATION":
                configuration = CanControllerConfiguration()
                self.readCanControllerConfiguration(child_element, configuration)
                controller.setCanControllerAttributes(configuration)
            else:
                self.notImplemented("Unsupported CanControllerAttributes <%s>" % tag_name)

    def readAbstractCanCommunicationController(self, element: ET.Element, controller: AbstractCanCommunicationController):
        self.readCommunicationController(element, controller)
        self.readAbstractCanCommunicationControllerCanControllerAttributes(element, controller)

    def readCanCommunicationController(self, element: ET.Element, controller: CanCommunicationController):
        self.logger.debug("Read CanCommunicationController %s" % controller.getShortName())
        self.readIdentifiable(element, controller)
        child_element = self.find(element, "CAN-COMMUNICATION-CONTROLLER-VARIANTS/CAN-COMMUNICATION-CONTROLLER-CONDITIONAL")
        if child_element is not None:
            self.readAbstractCanCommunicationController(child_element, controller)

    def readCouplingPortSchedulerCouplingPortStructuralElement(self, element: ET.Element, item: CouplingPortStructuralElement):
        self.readIdentifiable(element, item)

    def readCouplingPortFifo(self, element: ET.Element, fifo: CouplingPortFifo):
        self.readCouplingPortSchedulerCouplingPortStructuralElement(element, fifo)
        for item in self.findall(element, "ASSIGNED-TRAFFIC-CLASSS/ASSIGNED-TRAFFIC-CLASS"):
            value = PositiveInteger()
            value.setValue(item.text)
            fifo.addAssignedTrafficClass(value)
        fifo.setMinimumFifoLength(self.getChildElementOptionalPositiveInteger(element, "MINIMUM-FIFO-LENGTH"))
        self.readCouplingPortFifoShaper(element, fifo)

    def readCouplingPortFifoShaper(self, element: ET.Element, fifo: CouplingPortFifo):
        shaper_element = self.find(element, "SHAPER")
        if shaper_element is not None:
            for child in shaper_element:
                tag = self.getTagName(child)
                shaper: Optional[CouplingPortAbstractShaper] = None
                if tag == "COUPLING-PORT-ASYNCHRONOUS-TRAFFIC-SHAPER":
                    ats = CouplingPortAsynchronousTrafficShaper(fifo, self.getShortName(child))
                    self.readIdentifiable(child, ats)
                    self.readCouplingPortAsynchronousTrafficShaper(child, ats)
                    shaper = ats
                elif tag == "COUPLING-PORT-CREDIT-BASED-SHAPER":
                    cbs = CouplingPortCreditBasedShaper(fifo, self.getShortName(child))
                    self.readIdentifiable(child, cbs)
                    self.readCouplingPortCreditBasedShaper(child, cbs)
                    shaper = cbs
                else:
                    self.notImplemented("Unsupported CouplingPort shaper <%s>" % tag)
                    continue
                fifo.setShaper(shaper)

    def readCouplingPortAsynchronousTrafficShaper(self, element: ET.Element, shaper: CouplingPortAsynchronousTrafficShaper):
        shaper.setCommittedBurstSize(self.getChildElementOptionalPositiveInteger(element, "COMMITTED-BURST-SIZE"))
        shaper.setCommittedInformationRate(self.getChildElementOptionalPositiveInteger(element, "COMMITTED-INFORMATION-RATE"))
        refs = self.getChildElementRefTypeList(element, "TRAFFIC-SHAPER-GROUP-REF")
        if len(refs) > 0:
            shaper.setTrafficShaperGroupRef(refs[0])

    def readCouplingPortCreditBasedShaper(self, element: ET.Element, shaper: CouplingPortCreditBasedShaper):
        shaper.setIdleSlope(self.getChildElementOptionalPositiveInteger(element, "IDLE-SLOPE"))
        shaper.setLowerBoundary(self.getChildElementOptionalPositiveInteger(element, "LOWER-BOUNDARY"))
        shaper.setUpperBoundary(self.getChildElementOptionalPositiveInteger(element, "UPPER-BOUNDARY"))

    def readCouplingPortScheduler(self, element: ET.Element, scheduler: CouplingPortScheduler):
        self.readCouplingPortSchedulerCouplingPortStructuralElement(element, scheduler)
        scheduler.setPortScheduler(cast(Optional[EthernetCouplingPortSchedulerEnum], self.getChildElementOptionalLiteral(element, "PORT-SCHEDULER")))
        for ref in self.getChildElementRefTypeList(element, "PREDECESSOR-REFS/PREDECESSOR-REF"):
            scheduler.addPredecessorRef(ref)

    def readCouplingPortDetailsCouplingPortStructuralElements(self, item: ET.Element, details: CouplingPortDetails):
        for child_element in self.findall(item, "COUPLING-PORT-STRUCTURAL-ELEMENTS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "COUPLING-PORT-FIFO":
                structure_item = details.createCouplingPortFifo(self.getShortName(child_element))
                self.readCouplingPortFifo(child_element, structure_item)
            elif tag_name == "COUPLING-PORT-SCHEDULER":
                scheduler_item = details.createCouplingPortScheduler(self.getShortName(child_element))
                self.readCouplingPortScheduler(child_element, scheduler_item)
            else:
                self.notImplemented("Unsupported CouplingPortStructuralElement <%s>" % tag_name)

    def readEthernetPriorityRegeneration(self, element: ET.Element, regeneration: EthernetPriorityRegeneration):
        self.readReferrable(element, regeneration)
        regeneration.setIngressPriority(self.getChildElementOptionalPositiveInteger(element, "INGRESS-PRIORITY"))
        regeneration.setRegeneratedPriority(self.getChildElementOptionalPositiveInteger(element, "REGENERATED-PRIORITY"))

    def readCouplingPortDetailsEthernetPriorityRegenerations(self, element: ET.Element, details: CouplingPortDetails):
        for child_element in self.findall(element, "ETHERNET-PRIORITY-REGENERATIONS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "ETHERNET-PRIORITY-REGENERATION":
                item = details.createEthernetPriorityRegeneration(self.getShortName(child_element))
                self.readEthernetPriorityRegeneration(child_element, item)
            else:
                self.notImplemented("Unsupported EthernetPriorityRegeneration <%s>" % tag_name)

    def readCouplingPortTrafficClassAssignment(self, element: ET.Element, assignment: CouplingPortTrafficClassAssignment):
        self.readReferrable(element, assignment)
        for child_element in self.findall(element, "PRIORITY"):
            priority = PositiveInteger()
            self.readARType(child_element, priority)
            priority.setValue(child_element.text)
            assignment.addPriority(priority)
        assignment.setTrafficClass(self.getChildElementOptionalPositiveInteger(element, "TRAFFIC-CLASS"))

    def readCouplingPortDetailsEthernetTrafficClassAssignments(self, element: ET.Element, details: CouplingPortDetails):
        for child_element in self.findall(element, "ETHERNET-TRAFFIC-CLASS-ASSIGNMENTS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "COUPLING-PORT-TRAFFIC-CLASS-ASSIGNMENT":
                assignment = CouplingPortTrafficClassAssignment(details, self.getShortName(child_element))
                self.readCouplingPortTrafficClassAssignment(child_element, assignment)
                details.addEthernetTrafficClassAssignment(assignment)
            else:
                self.notImplemented("Unsupported CouplingPortTrafficClassAssignment <%s>" % tag_name)

    def readCouplingPortDetailsRatePolicys(self, element: ET.Element, details: CouplingPortDetails):
        for child_element in self.findall(element, "RATE-POLICYS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "COUPLING-PORT-RATE-POLICY":
                rate_policy = CouplingPortRatePolicy()
                self.readCouplingPortRatePolicy(child_element, rate_policy)
                details.addRatePolicy(rate_policy)
            else:
                self.notImplemented("Unsupported CouplingPortRatePolicy <%s>" % tag_name)

    def readCouplingPortRatePolicy(self, element: ET.Element, policy: CouplingPortRatePolicy):
        policy.setDataLength(self.getChildElementOptionalPositiveInteger(element, "DATA-LENGTH"))
        literal = self.getChildElementOptionalLiteral(element, "POLICY-ACTION")
        if literal is not None:
            e = CouplingPortRatePolicyActionEnum()
            e.setValue(literal.getValue())
            policy.setPolicyAction(e)
        policy.setPriority(self.getChildElementOptionalPositiveInteger(element, "PRIORITY"))
        policy.setTimeInterval(self.getChildElementOptionalTimeValue(element, "TIME-INTERVAL"))
        for ref in self.getChildElementRefTypeList(element, "V-LAN-REFS/V-LAN-REF"):
            policy.addVlanRef(ref)

