    def readMacSecGlobalKayProps(self, element: ET.Element, props: MacSecGlobalKayProps):
        self.logger.debug("Read MacSecGlobalKayProps <%s>" % props.getShortName())
        self.readIdentifiable(element, props)
        wrapper = self.find(element, "BYPASS-ETHER-TYPES")
        if wrapper is not None:
            for child_element in self.findall(wrapper, "BYPASS-ETHER-TYPE"):
                if child_element.text is not None:
                    value = PositiveInteger()
                    value.setValue(child_element.text)
                    props.addBypassEtherType(value)
        wrapper = self.find(element, "BYPASS-VLANS")
        if wrapper is not None:
            for child_element in self.findall(wrapper, "BYPASS-VLAN"):
                if child_element.text is not None:
                    value = PositiveInteger()
                    value.setValue(child_element.text)
                    props.addBypassVlan(value)

    def readMacSecCipherSuiteConfig(self, element: ET.Element, config: MacSecCipherSuiteConfig):
        self.logger.debug("Read MacSecCipherSuiteConfig")
        config.setCipherSuite(self.getChildElementOptionalString(element, "CIPHER-SUITE"))
        config.setCipherSuitePriority(self.getChildElementOptionalPositiveInteger(element, "CIPHER-SUITE-PRIORITY"))

    def readMacSecCryptoAlgoConfig(self, element: ET.Element, config: MacSecCryptoAlgoConfig):
        self.logger.debug("Read MacSecCryptoAlgoConfig")
        capability = self.getChildElementOptionalLiteral(element, "CAPABILITY")
        if capability is not None:
            e: ARLiteral = MacSecCapabilityEnum()
            e.setValue(capability.getValue())
            config.setCapability(cast(Optional[MacSecCapabilityEnum], e))
        wrapper = self.find(element, "CIPHER-SUITE-CONFIGS")
        if wrapper is not None:
            for child_element in self.findall(wrapper, "MAC-SEC-CIPHER-SUITE-CONFIG"):
                cipher_config = config.createCipherSuiteConfig()
                self.readMacSecCipherSuiteConfig(child_element, cipher_config)
        confidentiality_offset = self.getChildElementOptionalLiteral(element, "CONFIDENTIALITY-OFFSET")
        if confidentiality_offset is not None:
            e = MacSecConfidentialityOffsetEnum()
            e.setValue(confidentiality_offset.getValue())
            config.setConfidentialityOffset(cast(Optional[MacSecConfidentialityOffsetEnum], e))
        config.setReplayProtection(self.getChildElementOptionalBooleanValue(element, "REPLAY-PROTECTION"))
        config.setReplayProtectionWindow(self.getChildElementOptionalPositiveInteger(element, "REPLAY-PROTECTION-WINDOW"))

    def readMacSecKayParticipant(self, element: ET.Element, participant: MacSecKayParticipant):
        self.logger.debug("Read MacSecKayParticipant <%s>" % participant.getShortName())
        self.readIdentifiable(element, participant)
        participant.setCknRef(self.getChildElementOptionalRefType(element, "CKN-REF"))
        algo_element = self.find(element, "CRYPTO-ALGO-CONFIG")
        if algo_element is not None:
            config = MacSecCryptoAlgoConfig()
            self.readMacSecCryptoAlgoConfig(algo_element, config)
            participant.setCryptoAlgoConfig(config)
        participant.setSakRef(self.getChildElementOptionalRefType(element, "SAK-REF"))

    def getMacSecLocalKayProps(self, element: ET.Element) -> Optional[MacSecLocalKayProps]:
        props = None
        if element is not None:
            props = MacSecLocalKayProps()
            destination_mac = self.getChildElementOptionalLiteral(element, "DESTINATION-MAC-ADDRESS")
            if destination_mac is not None:
                mac_address = MacAddressString()
                mac_address.setValue(destination_mac.getValue())
                props.setDestinationMacAddress(mac_address)
            props.setGlobalKayPropsRef(self.getChildElementOptionalRefType(element, "GLOBAL-KAY-PROPS-REF"))
            props.setKeyServerPriority(self.getChildElementOptionalPositiveInteger(element, "KEY-SERVER-PRIORITY"))
            for ref in self.getChildElementRefTypeList(element, "MKA-PARTICIPANT-REFS/MKA-PARTICIPANT-REF"):
                props.addMkaParticipantRef(ref)
            role = self.getChildElementOptionalLiteral(element, "ROLE")
            if role is not None:
                e = MacSecRoleEnum()
                e.setValue(role.getValue())
                props.setRole(e)
            source_mac = self.getChildElementOptionalLiteral(element, "SOURCE-MAC-ADDRESS")
            if source_mac is not None:
                mac_address = MacAddressString()
                mac_address.setValue(source_mac.getValue())
                props.setSourceMacAddress(mac_address)
        return props

    def getMacSecProps(self, element: ET.Element) -> Optional[MacSecProps]:
        props = None
        if element is not None:
            props = MacSecProps()
            props.setAutoStart(self.getChildElementOptionalBooleanValue(element, "AUTO-START"))
            props.setMacSecKayConfig(self.getMacSecLocalKayProps(cast(ET.Element, self.find(element, "MAC-SEC-KAY-CONFIG"))))
            on_fail_permissive_mode = self.getChildElementOptionalLiteral(element, "ON-FAIL-PERMISSIVE-MODE")
            if on_fail_permissive_mode is not None:
                e = MacSecFailPermissiveModeEnum()
                e.setValue(on_fail_permissive_mode.getValue())
                props.setOnFailPermissiveMode(e)
            props.setOnFailPermissiveModeTimeout(self.getChildElementOptionalTimeValue(element, "ON-FAIL-PERMISSIVE-MODE-TIMEOUT"))
            props.setSakRekeyTimeSpan(self.getChildElementOptionalTimeValue(element, "SAK-REKEY-TIME-SPAN"))
        return props

    def getCouplingPortDetails(self, element: ET.Element, key: str) -> Optional[CouplingPortDetails]:
        details = None
        child_element = self.find(element, key)
        if child_element is not None:
            details = CouplingPortDetails()
            self.readCouplingPortDetailsCouplingPortStructuralElements(child_element, details)
            self.readCouplingPortDetailsEthernetPriorityRegenerations(child_element, details)
            self.readCouplingPortDetailsEthernetTrafficClassAssignments(child_element, details)
            details.setGlobalTimeProps(self.getGlobalTimeProps(child_element, "GLOBAL-TIME-PROPS"))
            details.setLastEgressSchedulerRef(self.getChildElementOptionalRefType(child_element, "LAST-EGRESS-SCHEDULER-REF"))
            self.readCouplingPortDetailsRatePolicys(child_element, details)
        return details

    def getDhcpServerConfiguration(self, element: ET.Element, key: str) -> Optional[DhcpServerConfiguration]:
        config = None
        child_element = self.find(element, key)
        if child_element is not None:
            config = DhcpServerConfiguration()
            config.setIpv4DhcpServerConfiguration(self.getIpv4DhcpServerConfiguration(child_element, "IPV-4-DHCP-SERVER-CONFIGURATION"))
            config.setIpv6DhcpServerConfiguration(self.getIpv6DhcpServerConfiguration(child_element, "IPV-6-DHCP-SERVER-CONFIGURATION"))
        return config

    def getIpv4DhcpServerConfiguration(self, element: ET.Element, key: str) -> Optional[Ipv4DhcpServerConfiguration]:
        config = None
        child_element = self.find(element, key)
        if child_element is not None:
            config = Ipv4DhcpServerConfiguration()
            config.setAddressRangeLowerBound(cast(Optional[Ip4AddressString], self.getChildElementOptionalLiteral(child_element, "ADDRESS-RANGE-LOWER-BOUND")))
            config.setAddressRangeUpperBound(cast(Optional[Ip4AddressString], self.getChildElementOptionalLiteral(child_element, "ADDRESS-RANGE-UPPER-BOUND")))
            config.setDefaultGateway(cast(Optional[Ip4AddressString], self.getChildElementOptionalLiteral(child_element, "DEFAULT-GATEWAY")))
            config.setDefaultLeaseTime(self.getChildElementOptionalTimeValue(child_element, "DEFAULT-LEASE-TIME"))
            for address in self.findall(child_element, "DNS-SERVER-ADDRESSES/DNS-SERVER-ADDRESS"):
                literal = ARLiteral()
                self.readARType(address, literal)
                literal.setValue(address.text)
                config.addDnsServerAddress(cast(Optional[Ip4AddressString], literal))
            config.setNetworkMask(cast(Optional[Ip4AddressString], self.getChildElementOptionalLiteral(child_element, "NETWORK-MASK")))
        return config

    def getPduActivationRoutingGroup(self, element: ET.Element) -> Optional[PduActivationRoutingGroup]:
        group = None
        if element is not None:
            group = PduActivationRoutingGroup(cast(ARObject, None), self.getShortName(element))
            self.readIdentifiable(element, group)
            control_type_literal = self.getChildElementOptionalLiteral(element, "EVENT-GROUP-CONTROL-TYPE")
            if control_type_literal is not None:
                control_type = EventGroupControlTypeEnum()
                control_type.setValue(control_type_literal.getValue())
                group.setEventGroupControlType(control_type)
            for ref in self.getChildElementRefTypeList(element, "I-PDU-IDENTIFIER-TCP-REFS/I-PDU-IDENTIFIER-TCP-REF"):
                group.addIPduIdentifierTcpRef(ref)
            for ref in self.getChildElementRefTypeList(element, "I-PDU-IDENTIFIER-UDP-REFS/I-PDU-IDENTIFIER-UDP-REF"):
                group.addIPduIdentifierUdpRef(ref)
        return group

    def getStaticSocketConnection(self, element: ET.Element) -> Optional[StaticSocketConnection]:
        connection = None
