    def readVlanMembership(self, element: ET.Element, membership: VlanMembership):
        membership.setDefaultPriority(self.getChildElementOptionalPositiveInteger(element, "DEFAULT-PRIORITY"))
        membership.setDhcpAddressAssignment(self.getDhcpServerConfiguration(element, "DHCP-ADDRESS-ASSIGNMENT"))
        membership.setSendActivity(cast(Optional[EthernetSwitchVlanEgressTaggingEnum], self.getChildElementOptionalLiteral(element, "SEND-ACTIVITY")))
        membership.setVlanRef(self.getChildElementOptionalRefType(element, "VLAN-REF"))

    def readCouplingPortVlanMemberships(self, element: ET.Element, port: CouplingPort):
        for child_element in self.findall(element, "VLAN-MEMBERSHIPS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "VLAN-MEMBERSHIP":
                membership = VlanMembership()
                self.readVlanMembership(child_element, membership)
                port.addVlanMembership(membership)
            else:
                self.notImplemented("Unsupported VlanMembership <%s>" % tag_name)

    def readCouplingPort(self, element: ET.Element, port: CouplingPort):
        self.readIdentifiable(element, port)
        connection_negotiation_behavior = self.getChildElementOptionalLiteral(element, "CONNECTION-NEGOTIATION-BEHAVIOR")
        if connection_negotiation_behavior is not None:
            e: ARLiteral = EthernetConnectionNegotiationEnum()
            e.setValue(connection_negotiation_behavior.getValue())
            port.setConnectionNegotiationBehavior(cast(Optional[EthernetConnectionNegotiationEnum], e))
        port.setCouplingPortDetails(self.getCouplingPortDetails(element, "COUPLING-PORT-DETAILS"))
        port.setPlcaProps(self.getPlcaProps(element, "PLCA-PROPS"))
        for child_element in self.findall(element, "MAC-SEC-PROPS"):
            props = self.getMacSecProps(child_element)
            if props is not None:
                port.addMacSecProps(props)
        coupling_port_role = self.getChildElementOptionalLiteral(element, "COUPLING-PORT-ROLE")
        if coupling_port_role is not None:
            e = CouplingPortRoleEnum()
            e.setValue(coupling_port_role.getValue())
            port.setCouplingPortRole(cast(Optional[CouplingPortRoleEnum], e))
        port.setDefaultVlanRef(self.getChildElementOptionalRefType(element, "DEFAULT-VLAN-REF"))
        mac_layer_type = self.getChildElementOptionalLiteral(element, "MAC-LAYER-TYPE")
        if mac_layer_type is not None:
            e = EthernetMacLayerTypeEnum()
            e.setValue(mac_layer_type.getValue())
            port.setMacLayerType(cast(Optional[EthernetMacLayerTypeEnum], e))
        for ref in self.getChildElementRefTypeList(element, "MAC-MULTICAST-ADDRESS-REFS/MAC-MULTICAST-ADDRESS-REF"):
            port.addMacMulticastAddressRef(ref)
        for ref in self.getChildElementRefTypeList(element, "PNC-MAPPING-REFS/PNC-MAPPING-REF"):
            port.addPncMappingRef(ref)
        receive_activity = self.getChildElementOptionalLiteral(element, "RECEIVE-ACTIVITY")
        if receive_activity is not None:
            e = EthernetSwitchVlanIngressTagEnum()
            e.setValue(receive_activity.getValue())
            port.setReceiveActivity(cast(Optional[EthernetSwitchVlanIngressTagEnum], e))
        physical_layer_type = self.getChildElementOptionalLiteral(element, "PHYSICAL-LAYER-TYPE")
        if physical_layer_type is not None:
            e = EthernetPhysicalLayerTypeEnum()
            e.setValue(physical_layer_type.getValue())
            port.setPhysicalLayerType(cast(Optional[EthernetPhysicalLayerTypeEnum], e))
        self.readCouplingPortVlanMemberships(element, port)
        port.setVlanModifierRef(self.getChildElementOptionalRefType(element, "VLAN-MODIFIER-REF"))
        port.setWakeupSleepOnDatalineConfigRef(self.getChildElementOptionalRefType(element, "WAKEUP-SLEEP-ON-DATALINE-CONFIG-REF"))

    def readEthernetCommunicationControllerCouplingPorts(self, element: ET.Element, controller: EthernetCommunicationController):
        for child_element in self.findall(element, "COUPLING-PORTS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "COUPLING-PORT":
                port = controller.createCouplingPort(self.getShortName(child_element))
                self.readCouplingPort(child_element, port)
            else:
                self.notImplemented("Unsupported Coupling Port <%s>" % tag_name)

    def readEthernetCommunicationController(self, element: ET.Element, controller: EthernetCommunicationController):
        self.logger.debug("Read EthernetCommunicationController %s" % controller.getShortName())
        self.readIdentifiable(element, controller)
        child_element = self.find(element, "ETHERNET-COMMUNICATION-CONTROLLER-VARIANTS/ETHERNET-COMMUNICATION-CONTROLLER-CONDITIONAL")
        if child_element is not None:
            self.readCommunicationController(child_element, controller)
            controller.setCanXlConfigRef(self.getChildElementOptionalRefType(child_element, "CAN-XL-CONFIG-REF"))
            self.readEthernetCommunicationControllerCouplingPorts(child_element, controller)
            mac_layer_type = self.getChildElementOptionalLiteral(child_element, "MAC-LAYER-TYPE")
            if mac_layer_type is not None:
                e = EthernetMacLayerTypeEnum()
                e.setValue(mac_layer_type.getValue())
                controller.setMacLayerType(e)
            mac_unicast_literal = self.getChildElementOptionalLiteral(child_element, "MAC-UNICAST-ADDRESS")
            if mac_unicast_literal is not None:
                mac_unicast = MacAddressString()
                mac_unicast.setValue(mac_unicast_literal.getValue())
                controller.setMacUnicastAddress(mac_unicast)
            controller.setMaximumReceiveBufferLength(self.getChildElementOptionalIntegerValue(child_element, "MAXIMUM-RECEIVE-BUFFER-LENGTH"))
            controller.setMaximumTransmitBufferLength(self.getChildElementOptionalIntegerValue(child_element, "MAXIMUM-TRANSMIT-BUFFER-LENGTH"))
            controller.setSlaveActAsPassiveCommunicationSlave(self.getChildElementOptionalBooleanValue(child_element, "SLAVE-ACT-AS-PASSIVE-COMMUNICATION-SLAVE"))

    def readLinCommunicationController(self, element: ET.Element, controller: LinCommunicationController):
        self.readCommunicationController(element, controller)
        controller.setProtocolVersion(cast(Optional[String], self.getChildElementOptionalLiteral(element, "PROTOCOL-VERSION")))

    def readLinMaster(self, element: ET.Element, controller: LinMaster):
        self.logger.debug("Read LinMaster %s" % controller.getShortName())
        self.readIdentifiable(element, controller)
        child_element = self.find(element, "LIN-MASTER-VARIANTS/LIN-MASTER-CONDITIONAL")
        if child_element is not None:
            self.readLinCommunicationController(child_element, controller)
            slaves_wrapper = self.find(child_element, "LIN-SLAVES")
            if slaves_wrapper is not None:
                for slave_element in self.findall(slaves_wrapper, "LIN-SLAVE-CONFIG"):
                    controller.addLinSlave(self.readLinSlaveConfig(slave_element))
            controller.setTimeBase(self.getChildElementOptionalTimeValue(child_element, "TIME-BASE"))
            controller.setTimeBaseJitter(self.getChildElementOptionalTimeValue(child_element, "TIME-BASE-JITTER"))

    def getLinErrorResponse(self, element: ET.Element, key: str) -> Optional[LinErrorResponse]:
        response = None
        child_element = self.find(element, key)
        if child_element is not None:
            response = LinErrorResponse()
            response.setResponseErrorRef(self.getChildElementOptionalRefType(child_element, "RESPONSE-ERROR-REF"))
        return response

    def getLinConfigurableFrame(self, element: ET.Element, key: str) -> Optional[LinConfigurableFrame]:
        frame = None
        child_element = self.find(element, key)
        if child_element is not None:
            frame = LinConfigurableFrame()
            frame.setFrameRef(self.getChildElementOptionalRefType(child_element, "FRAME-REF"))
            frame.setMessageId(self.getChildElementOptionalPositiveInteger(child_element, "MESSAGE-ID"))
        return frame

    def getLinOrderedConfigurableFrame(self, element: ET.Element, key: str) -> Optional[LinOrderedConfigurableFrame]:
        frame = None
        child_element = self.find(element, key)
        if child_element is not None:
            frame = LinOrderedConfigurableFrame()
            frame.setFrameRef(self.getChildElementOptionalRefType(child_element, "FRAME-REF"))
            frame.setIndex(self.getChildElementOptionalIntegerValue(child_element, "INDEX"))
        return frame

    def getLinSlaveConfig(self, element: ET.Element, key: str) -> Optional[LinSlaveConfig]:
        config = None
        child_element = self.find(element, key)
        if child_element is not None:
            config = self.readLinSlaveConfig(child_element)
        return config

    def readLinSlaveConfig(self, child_element: ET.Element) -> LinSlaveConfig:
        config = LinSlaveConfig()
        config.setConfiguredNad(self.getChildElementOptionalIntegerValue(child_element, "CONFIGURED-NAD"))
        config.setFunctionId(self.getChildElementOptionalPositiveInteger(child_element, "FUNCTION-ID"))
        ident_element = self.find(child_element, "IDENT")
        if ident_element is not None:
            ident = LinSlaveConfigIdent(config, self.getShortName(ident_element))
            self.readReferrable(ident_element, ident)
            config.setIdent(ident)
        config.setInitialNad(self.getChildElementOptionalIntegerValue(child_element, "INITIAL-NAD"))
        frames_wrapper = self.find(child_element, "LIN-CONFIGURABLE-FRAMES")
        if frames_wrapper is not None:
            for frame_element in self.findall(frames_wrapper, "LIN-CONFIGURABLE-FRAME"):
                configurable_frame = LinConfigurableFrame()
                configurable_frame.setFrameRef(self.getChildElementOptionalRefType(frame_element, "FRAME-REF"))
                configurable_frame.setMessageId(self.getChildElementOptionalPositiveInteger(frame_element, "MESSAGE-ID"))
                config.addLinConfigurableFrame(configurable_frame)
        config.setLinErrorResponse(self.getLinErrorResponse(child_element, "LIN-ERROR-RESPONSE"))
        ordered_wrapper = self.find(child_element, "LIN-ORDERED-CONFIGURABLE-FRAMES")
        if ordered_wrapper is not None:
            for frame_element in self.findall(ordered_wrapper, "LIN-ORDERED-CONFIGURABLE-FRAME"):
                ordered_frame = LinOrderedConfigurableFrame()
                ordered_frame.setFrameRef(self.getChildElementOptionalRefType(frame_element, "FRAME-REF"))
                ordered_frame.setIndex(self.getChildElementOptionalIntegerValue(frame_element, "INDEX"))
                config.addLinOrderedConfigurableFrame(ordered_frame)
        config.setProtocolVersion(cast(Optional[String], self.getChildElementOptionalLiteral(child_element, "PROTOCOL-VERSION")))
        config.setSupplierId(self.getChildElementOptionalPositiveInteger(child_element, "SUPPLIER-ID"))
        config.setVariantId(self.getChildElementOptionalPositiveInteger(child_element, "VARIANT-ID"))
        return config

    def readEcuInstanceCommControllers(self, element: ET.Element, instance: EcuInstance):
        self.logger.debug("readEcuInstanceCommControllers %s" % instance.getShortName())
        for child_element in self.findall(element, "COMM-CONTROLLERS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "CAN-COMMUNICATION-CONTROLLER":
                controller = instance.createCanCommunicationController(self.getShortName(child_element))
                self.readCanCommunicationController(child_element, controller)
            elif tag_name == "ETHERNET-COMMUNICATION-CONTROLLER":
                self.readEthernetCommunicationController(child_element, instance.createEthernetCommunicationController(self.getShortName(child_element)))
            elif tag_name == "LIN-MASTER":
                self.readLinMaster(child_element, instance.createLinMaster(self.getShortName(child_element)))
            elif tag_name == "FLEXRAY-COMMUNICATION-CONTROLLER":
                self.readFlexrayCommunicationController(child_element, instance.createFlexrayCommunicationController(self.getShortName(child_element)))
            else:
                self.raiseError("Unsupported Communication Controller <%s>" % tag_name)

    def readCommConnectorPort(self, element: ET.Element, port: CommConnectorPort):
        self.readIdentifiable(element, port)
        port.setCommunicationDirection(cast(Optional[CommunicationDirectionType], self.getChildElementOptionalLiteral(element, "COMMUNICATION-DIRECTION")))

    def readFramePort(self, element: ET.Element, port: FramePort):
        self.readCommConnectorPort(element, port)

    def readIPduPort(self, element: ET.Element, port: IPduPort):
        self.readCommConnectorPort(element, port)
        port.setIPduSignalProcessing(cast(Optional[IPduSignalProcessingEnum], self.getChildElementOptionalLiteral(element, "I-PDU-SIGNAL-PROCESSING")))
        port.setRxSecurityVerification(self.getChildElementOptionalBooleanValue(element, "RX-SECURITY-VERIFICATION"))
        port.setTimestampRxAcceptanceWindow(self.getChildElementOptionalTimeValue(element, "TIMESTAMP-RX-ACCEPTANCE-WINDOW"))
        port.setUseAuthDataFreshness(self.getChildElementOptionalBooleanValue(element, "USE-AUTH-DATA-FRESHNESS"))

    def readISignalPort(self, element: ET.Element, port: ISignalPort):
        self.readCommConnectorPort(element, port)
        port.setDataFilter(self.getDataFilter(element, "DATA-FILTER"))
        port.setDdsQosProfileRef(self.getChildElementOptionalRefType(element, "DDS-QOS-PROFILE-REF"))
        port.setFirstTimeout(self.getChildElementOptionalTimeValue(element, "FIRST-TIMEOUT"))
        port.setHandleInvalid(cast(Optional[HandleInvalidEnum], self.getChildElementOptionalLiteral(element, "HANDLE-INVALID")))
        port.setTimeout(self.getChildElementOptionalTimeValue(element, "TIMEOUT"))

    def readCommunicationConnectorEcuCommPortInstances(self, element: ET.Element, connector: CommunicationConnector):
        self.logger.debug("read EcuCommPortInstances of CommunicationConnector %s" % connector.getShortName())
        for child_element in self.findall(element, "ECU-COMM-PORT-INSTANCES/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "FRAME-PORT":
                port = connector.createFramePort(self.getShortName(child_element))
                self.readFramePort(child_element, port)
            elif tag_name == "I-PDU-PORT":
                self.readIPduPort(child_element, connector.createIPduPort(self.getShortName(child_element)))
            elif tag_name == "I-SIGNAL-PORT":
                self.readISignalPort(child_element, connector.createISignalPort(self.getShortName(child_element)))
            else:
                self.raiseError("Unsupported EcuCommPortInstances <%s>" % tag_name)

    def readCommunicationConnector(self, element: ET.Element, connector: CommunicationConnector):
        self.readIdentifiable(element, connector)
        connector.setCommControllerRef(self.getChildElementOptionalRefType(element, "COMM-CONTROLLER-REF"))
        connector.setCreateEcuWakeupSource(self.getChildElementOptionalBooleanValue(element, "CREATE-ECU-WAKEUP-SOURCE"))
        connector.setDynamicPncToChannelMappingEnabled(self.getChildElementOptionalBooleanValue(element, "DYNAMIC-PNC-TO-CHANNEL-MAPPING-ENABLED"))
        self.readCommunicationConnectorEcuCommPortInstances(element, connector)
        for mask in self.findall(element, "PNC-FILTER-ARRAY-MASKS/PNC-FILTER-ARRAY-MASK"):
            if mask.text is not None:
                connector.addPncFilterArrayMask(cast(Optional[PositiveInteger], int(mask.text.strip())))
        connector.setPncGatewayType(cast(Optional[PncGatewayTypeEnum], self.getChildElementOptionalLiteral(element, "PNC-GATEWAY-TYPE")))

    def readCanCommunicationConnector(self, element: ET.Element, connector: CanCommunicationConnector):
        self.readCommunicationConnector(element, connector)
        connector.setPncWakeupCanId(self.getChildElementOptionalPositiveInteger(element, "PNC-WAKEUP-CAN-ID"))
        connector.setPncWakeupCanIdExtended(self.getChildElementOptionalBooleanValue(element, "PNC-WAKEUP-CAN-ID-EXTENDED"))
        connector.setPncWakeupCanIdMask(self.getChildElementOptionalPositiveInteger(element, "PNC-WAKEUP-CAN-ID-MASK"))
        connector.setPncWakeupDataMask(self.getChildElementOptionalPositiveUnlimitedInteger(element, "PNC-WAKEUP-DATA-MASK"))
        connector.setPncWakeupDlc(self.getChildElementOptionalPositiveInteger(element, "PNC-WAKEUP-DLC"))

    def readEthernetCommunicationConnector(self, element: ET.Element, connector: EthernetCommunicationConnector):
        self.readCommunicationConnector(element, connector)
        connector.setEthIpPropsRef(self.getChildElementOptionalRefType(element, "ETH-IP-PROPS-REF"))
        connector.setMaximumTransmissionUnit(self.getChildElementOptionalPositiveInteger(element, "MAXIMUM-TRANSMISSION-UNIT"))
        connector.setNeighborCacheSize(self.getChildElementOptionalPositiveInteger(element, "NEIGHBOR-CACHE-SIZE"))
        connector.setPathMtuEnabled(self.getChildElementOptionalBooleanValue(element, "PATH-MTU-ENABLED"))
        connector.setPathMtuTimeout(self.getChildElementOptionalTimeValue(element, "PATH-MTU-TIMEOUT"))

    def readLinCommunicationConnector(self, element: ET.Element, connector: LinCommunicationConnector):
        self.readCommunicationConnector(element, connector)
        connector.setInitialNad(self.getChildElementOptionalIntegerValue(element, "INITIAL-NAD"))
        frames_wrapper = self.find(element, "LIN-CONFIGURABLE-FRAMES")
        if frames_wrapper is not None:
            for frame_element in self.findall(frames_wrapper, "LIN-CONFIGURABLE-FRAME"):
                configurable_frame = LinConfigurableFrame()
                configurable_frame.setFrameRef(self.getChildElementOptionalRefType(frame_element, "FRAME-REF"))
                configurable_frame.setMessageId(self.getChildElementOptionalPositiveInteger(frame_element, "MESSAGE-ID"))
                connector.addLinConfigurableFrame(configurable_frame)
        ordered_wrapper = self.find(element, "LIN-ORDERED-CONFIGURABLE-FRAMES")
        if ordered_wrapper is not None:
            for frame_element in self.findall(ordered_wrapper, "LIN-ORDERED-CONFIGURABLE-FRAME"):
                ordered_frame = LinOrderedConfigurableFrame()
                ordered_frame.setFrameRef(self.getChildElementOptionalRefType(frame_element, "FRAME-REF"))
                ordered_frame.setIndex(self.getChildElementOptionalIntegerValue(frame_element, "INDEX"))
                connector.addLinOrderedConfigurableFrame(ordered_frame)
        connector.setScheduleChangeNextTimeBase(self.getChildElementOptionalBooleanValue(element, "SCHEDULE-CHANGE-NEXT-TIME-BASE"))

    def readFlexrayCommunicationConnector(self, element: ET.Element, connector: FlexrayCommunicationConnector):
        self.readCommunicationConnector(element, connector)
        connector.setNmReadySleepTime(self.getChildElementOptionalFloatValue(element, "NM-READY-SLEEP-TIME"))
        connector.setWakeUpChannel(self.getChildElementOptionalBooleanValue(element, "WAKE-UP-CHANNEL"))

    def readEcuInstanceConnectors(self, element: ET.Element, instance: EcuInstance):
        self.logger.debug("readEcuInstanceCommControllers %s" % instance.getShortName())
        for child_element in self.findall(element, "CONNECTORS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "CAN-COMMUNICATION-CONNECTOR":
                connector = instance.createCanCommunicationConnector(self.getShortName(child_element))
                self.readCanCommunicationConnector(child_element, connector)
            elif tag_name == "ETHERNET-COMMUNICATION-CONNECTOR":
                self.readEthernetCommunicationConnector(child_element, instance.createEthernetCommunicationConnector(self.getShortName(child_element)))
            elif tag_name == "LIN-COMMUNICATION-CONNECTOR":
                self.readLinCommunicationConnector(child_element, instance.createLinCommunicationConnector(self.getShortName(child_element)))
            elif tag_name == "FLEXRAY-COMMUNICATION-CONNECTOR":
                self.readFlexrayCommunicationConnector(child_element, instance.createFlexrayCommunicationConnector(self.getShortName(child_element)))
            else:
                self.notImplemented("Unsupported Communication Connector <%s>" % tag_name)

    def readEcuInstanceAssociatedComIPduGroupRefs(self, element: ET.Element, instance: EcuInstance):
        for ref in self.getChildElementRefTypeList(element, "ASSOCIATED-COM-I-PDU-GROUP-REFS/ASSOCIATED-COM-I-PDU-GROUP-REF"):
            instance.addAssociatedComIPduGroupRef(ref)

    def readEcuInstanceAssociatedConsumedProvidedServiceInstanceGroupRefs(self, element: ET.Element, instance: EcuInstance):
        for ref in self.getChildElementRefTypeList(element, "ASSOCIATED-CONSUMED-PROVIDED-SERVICE-INSTANCE-GROUPS/CONSUMED-PROVIDED-SERVICE-INSTANCE-GROUP-REF-CONDITIONAL"):
            instance.addAssociatedConsumedProvidedServiceInstanceGroupRef(ref)

    def readEcuInstanceAssociatedPdurIPduGroupRefs(self, element: ET.Element, instance: EcuInstance):
        for ref in self.getChildElementRefTypeList(element, "ASSOCIATED-PDUR-I-PDU-GROUP-REFS/ASSOCIATED-PDUR-I-PDU-GROUP-REF"):
            instance.addAssociatedPdurIPduGroupRef(ref)

    def readEcuInstanceEcuTaskProxyRefs(self, element: ET.Element, instance: EcuInstance):
        for ref in self.getChildElementRefTypeList(element, "ECU-TASK-PROXY-REFS/ECU-TASK-PROXY-REF"):
            instance.addEcuTaskProxyRef(ref)

    def readEcuInstanceFirewallRuleRefs(self, element: ET.Element, instance: EcuInstance):
        for ref in self.getChildElementRefTypeList(element, "FIREWALL-RULE-REFS/FIREWALL-RULE-REF"):
            instance.addFirewallRuleRef(ref)

    def readEcuInstancePartitions(self, element: ET.Element, instance: EcuInstance):
        for child_element in self.findall(element, "PARTITIONS/ECU-PARTITION"):
            partition = instance.createEcuPartition(self.getShortName(child_element))
            self.readEcuPartition(child_element, partition)

    def readEcuPartition(self, element: ET.Element, partition: EcuPartition):
        self.readIdentifiable(element, partition)
        partition.setExecInUserMode(self.getChildElementOptionalBooleanValue(element, "EXEC-IN-USER-MODE"))

    def readPrivacyLevel(self, element: ET.Element, privacy_level: PrivacyLevel):
        privacy_level.setCompuMethodRef(self.getChildElementOptionalRefType(element, "COMPU-METHOD-REF"))
        privacy_level.setPrivacyLevel(self.getChildElementOptionalPositiveInteger(element, "PRIVACY-LEVEL"))

    def readDltArgument(self, element: ET.Element, argument: DltArgument):
        self.readIdentifiable(element, argument)
        for child_element in self.findall(element, "DLT-ARGUMENT-ENTRYS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "DLT-ARGUMENT":
                entry = argument.createDltArgumentEntry(self.getShortName(child_element))
                self.readDltArgument(child_element, entry)
            else:
                self.notImplemented("Unsupported DltArgument Entry <%s>" % tag_name)
        argument.setLength(self.getChildElementOptionalPositiveInteger(element, "LENGTH"))
        argument.setNetworkRepresentation(self.getSwDataDefProps(element, "NETWORK-REPRESENTATION"))
        argument.setOptional(self.getChildElementOptionalBooleanValue(element, "OPTIONAL"))
        argument.setPredefinedText(self.getChildElementOptionalBooleanValue(element, "PREDEFINED-TEXT"))
        argument.setVariableLength(self.getChildElementOptionalBooleanValue(element, "VARIABLE-LENGTH"))

    def readDltMessage(self, element: ET.Element, message: DltMessage):
        self.readIdentifiable(element, message)
        for child_element in self.findall(element, "DLT-ARGUMENTS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "DLT-ARGUMENT":
                argument = message.createDltArgument(self.getShortName(child_element))
                self.readDltArgument(child_element, argument)
            else:
                self.notImplemented("Unsupported DltMessage Argument <%s>" % tag_name)
        message.setMessageId(self.getChildElementOptionalPositiveInteger(element, "MESSAGE-ID"))
        message.setMessageLineNumber(self.getChildElementOptionalPositiveInteger(element, "MESSAGE-LINE-NUMBER"))
        message.setMessageSourceFile(self.getChildElementOptionalString(element, "MESSAGE-SOURCE-FILE"))
        message.setMessageTypeInfo(self.getChildElementOptionalString(element, "MESSAGE-TYPE-INFO"))
        privacy_level_element = self.find(element, "PRIVACY-LEVEL")
        if privacy_level_element is not None:
            privacy_level = PrivacyLevel()
            self.readPrivacyLevel(privacy_level_element, privacy_level)
            message.setPrivacyLevel(privacy_level)

    def readDltContext(self, element: ET.Element, context: DltContext):
        self.readIdentifiable(element, context)
        context.setContextDescription(self.getChildElementOptionalString(element, "CONTEXT-DESCRIPTION"))
        context.setContextId(self.getChildElementOptionalString(element, "CONTEXT-ID"))
        for ref in self.getChildElementRefTypeList(element, "DLT-MESSAGES/DLT-MESSAGE-REF-CONDITIONAL/DLT-MESSAGE-REF"):
            context.addDltMessageRef(ref)

    def readDltApplication(self, element: ET.Element, application: DltApplication):
        self.readIdentifiable(element, application)
        application.setApplicationDescription(self.getChildElementOptionalString(element, "APPLICATION-DESCRIPTION"))
        application.setApplicationId(self.getChildElementOptionalString(element, "APPLICATION-ID"))
        for ref in self.getChildElementRefTypeList(element, "CONTEXTS/DLT-CONTEXT-REF-CONDITIONAL/DLT-CONTEXT-REF"):
            application.addContextRef(ref)

    def readDltEcu(self, element: ET.Element, ecu: DltEcu):
        self.readIdentifiable(element, ecu)
        for child_element in self.findall(element, "APPLICATIONS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "DLT-APPLICATION":
                application = ecu.createApplication(self.getShortName(child_element))
                self.readDltApplication(child_element, application)
            else:
                self.notImplemented("Unsupported DltEcu Application <%s>" % tag_name)
        ecu.setEcuId(self.getChildElementOptionalString(element, "ECU-ID"))

    def readDltLogChannel(self, element: ET.Element, channel: DltLogChannel):
        self.readIdentifiable(element, channel)
        for ref in self.getChildElementRefTypeList(element, "APPLICATION-CONTEXT-REFS/APPLICATION-CONTEXT-REF"):
            channel.addApplicationContextRef(ref)
        default_trace_state_element = self.find(element, "DEFAULT-TRACE-STATE")
        if default_trace_state_element is not None:
            channel.setDefaultTraceState(DltDefaultTraceStateEnum().setValue(default_trace_state_element.text))
        for ref in self.getChildElementRefTypeList(element, "DLT-MESSAGE-REFS/DLT-MESSAGE-REF"):
            channel.addDltMessageRef(ref)
        channel.setLogChannelId(self.getChildElementOptionalString(element, "LOG-CHANNEL-ID"))
        log_trace_default_log_threshold_element = self.find(element, "LOG-TRACE-DEFAULT-LOG-THRESHOLD")
        if log_trace_default_log_threshold_element is not None:
            channel.setLogTraceDefaultLogThreshold(LogTraceDefaultLogLevelEnum().setValue(log_trace_default_log_threshold_element.text))
        channel.setNonVerboseMode(self.getChildElementOptionalBooleanValue(element, "NON-VERBOSE-MODE"))
        channel.setRxPduTriggeringRef(self.getChildElementOptionalRefType(element, "RX-PDU-TRIGGERING-REF"))
        channel.setSegmentationSupported(self.getChildElementOptionalBooleanValue(element, "SEGMENTATION-SUPPORTED"))
        channel.setTxPduTriggeringRef(self.getChildElementOptionalRefType(element, "TX-PDU-TRIGGERING-REF"))

    def readDltConfig(self, element: ET.Element, config: DltConfig):
        config.setDltEcuRef(self.getChildElementOptionalRefType(element, "DLT-ECU-REF"))
        for child_element in self.findall(element, "DLT-LOG-CHANNELS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "DLT-LOG-CHANNEL":
                channel = config.createDltLogChannel(self.getShortName(child_element))
                self.readDltLogChannel(child_element, channel)
            else:
                self.notImplemented("Unsupported DltConfig DltLogChannel <%s>" % tag_name)
        config.setSessionIdSupport(self.getChildElementOptionalBooleanValue(element, "SESSION-ID-SUPPORT"))
        config.setTimestampSupport(self.getChildElementOptionalBooleanValue(element, "TIMESTAMP-SUPPORT"))

    def readClientIdRange(self, element: ET.Element, id_range: ClientIdRange):
        id_range.setLowerLimit(self.getChildLimitElement(element, "LOWER-LIMIT"))
        id_range.setUpperLimit(self.getChildLimitElement(element, "UPPER-LIMIT"))

    def readEcuInstanceClientIdRange(self, element: ET.Element, instance: EcuInstance):
        client_id_range_element = self.find(element, "CLIENT-ID-RANGE")
        if client_id_range_element is not None:
            id_range = ClientIdRange()
            instance.setClientIdRange(id_range)
            self.readClientIdRange(client_id_range_element, id_range)

    def readEcuInstanceDltConfig(self, element: ET.Element, instance: EcuInstance):
        dlt_config_element = self.find(element, "DLT-CONFIG")
        if dlt_config_element is not None:
            config = DltConfig()
            instance.setDltConfig(config)
            self.readDltConfig(dlt_config_element, config)

    def readEcuInstanceDoIpConfig(self, element: ET.Element, instance: EcuInstance):
        do_ip_config_element = self.find(element, "DO-IP-CONFIG")
        if do_ip_config_element is not None:
            config = DoIpConfig()
            instance.setDoIpConfig(config)
            self.readDoIpConfig(do_ip_config_element, config)

    def readEcuInstance(self, element: ET.Element, instance: EcuInstance):
        self.logger.debug("Read EcuInstance <%s>" % instance.getShortName())
        self.readIdentifiable(element, instance)
        self.readEcuInstanceAssociatedComIPduGroupRefs(element, instance)
        self.readEcuInstanceAssociatedConsumedProvidedServiceInstanceGroupRefs(element, instance)
        self.readEcuInstanceAssociatedPdurIPduGroupRefs(element, instance)
        instance.setChannelSynchronousWakeup(self.getChildElementOptionalBooleanValue(element, "CHANNEL-SYNCHRONOUS-WAKEUP"))
        self.readEcuInstanceClientIdRange(element, instance)
        instance.setComConfigurationGwTimeBase(self.getChildElementOptionalTimeValue(element, "COM-CONFIGURATION-GW-TIME-BASE"))
        instance.setComConfigurationRxTimeBase(self.getChildElementOptionalTimeValue(element, "COM-CONFIGURATION-RX-TIME-BASE"))
        instance.setComConfigurationTxTimeBase(self.getChildElementOptionalTimeValue(element, "COM-CONFIGURATION-TX-TIME-BASE"))
        instance.setComEnableMDTForCyclicTransmission(self.getChildElementOptionalBooleanValue(element, "COM-ENABLE-MDT-FOR-CYCLIC-TRANSMISSION"))
        self.readEcuInstanceCommControllers(element, instance)
        self.readEcuInstanceConnectors(element, instance)
        self.readEcuInstanceDltConfig(element, instance)
        self.readEcuInstanceDoIpConfig(element, instance)
        self.readEcuInstanceEcuTaskProxyRefs(element, instance)
        instance.setEthSwitchPortGroupDerivation(self.getChildElementOptionalBooleanValue(element, "ETH-SWITCH-PORT-GROUP-DERIVATION"))
        self.readEcuInstanceFirewallRuleRefs(element, instance)
        self.readEcuInstancePartitions(element, instance)
        instance.setPnResetTime(self.getChildElementOptionalTimeValue(element, "PN-RESET-TIME"))
        instance.setPncNmRequest(self.getChildElementOptionalBooleanValue(element, "PNC-NM-REQUEST"))
        instance.setPncPrepareSleepTimer(self.getChildElementOptionalTimeValue(element, "PNC-PREPARE-SLEEP-TIMER"))
        instance.setPncSynchronousWakeup(self.getChildElementOptionalBooleanValue(element, "PNC-SYNCHRONOUS-WAKEUP"))
        instance.setSleepModeSupported(self.getChildElementOptionalBooleanValue(element, "SLEEP-MODE-SUPPORTED"))
        instance.setTcpIpIcmpPropsRef(self.getChildElementOptionalRefType(element, "TCP-IP-ICMP-PROPS-REF"))
        instance.setTcpIpPropsRef(self.getChildElementOptionalRefType(element, "TCP-IP-PROPS-REF"))
        instance.setV2xSupported(cast(Any, self.getChildElementOptionalLiteral(element, "V-2-X-SUPPORTED")))
        instance.setWakeUpOverBusSupported(self.getChildElementOptionalBooleanValue(element, "WAKE-UP-OVER-BUS-SUPPORTED"))

    def getFrameMappings(self, element: ET.Element) -> List[FrameMapping]:
        mappings = []
        for child_element in self.findall(element, "FRAME-MAPPINGS/FRAME-MAPPING"):
            mapping = FrameMapping()
            self.readFrameMapping(child_element, mapping)
            mappings.append(mapping)
        return mappings

    def readFrameMapping(self, element: ET.Element, mapping: FrameMapping):
        self.readARObject(element, mapping)
        mapping.setIntroduction(self.getDocumentationBlock(element, "INTRODUCTION"))
        mapping.setSourceFrameRef(self.getChildElementOptionalRefType(element, "SOURCE-FRAME-REF"))
        mapping.setTargetFrameRef(self.getChildElementOptionalRefType(element, "TARGET-FRAME-REF"))
        variation_point_element = self.find(element, "VARIATION-POINT")
        if variation_point_element is not None:
            if isinstance(mapping, VariationPointCapable):
                mapping.setVariationPoint(self.readVariationPoint(variation_point_element, VariationPoint()))
            else:
                self.logger.warning("VARIATION-POINT on non-variant element <%s> ignored" % self.getPureTagName(element.tag))

    def getISignalMappings(self, element: ET.Element) -> List[ISignalMapping]:
        mappings = []
        for child_element in self.findall(element, "SIGNAL-MAPPINGS/I-SIGNAL-MAPPING"):
            mapping = ISignalMapping()
            self.readISignalMapping(child_element, mapping)
            mappings.append(mapping)
        return mappings

    def readISignalMapping(self, element: ET.Element, mapping: ISignalMapping):
        self.readARObject(element, mapping)
        mapping.setIntroduction(self.getDocumentationBlock(element, "INTRODUCTION"))
        mapping.setSourceSignalRef(self.getChildElementOptionalRefType(element, "SOURCE-SIGNAL-REF"))
        mapping.setTargetSignalRef(self.getChildElementOptionalRefType(element, "TARGET-SIGNAL-REF"))
        variation_point_element = self.find(element, "VARIATION-POINT")
        if variation_point_element is not None:
            if isinstance(mapping, VariationPointCapable):
                mapping.setVariationPoint(self.readVariationPoint(variation_point_element, VariationPoint()))
            else:
                self.logger.warning("VARIATION-POINT on non-variant element <%s> ignored" % self.getPureTagName(element.tag))

    def getTargetIPduRef(self, element, key: str) -> Optional[TargetIPduRef]:
        i_pdu_ref = None
        child_element = self.find(element, key)
        if child_element is not None:
            i_pdu_ref = TargetIPduRef()
            self.readARObject(child_element, i_pdu_ref)
            default_value_element = self.find(child_element, "DEFAULT-VALUE")
            if default_value_element is not None:
                default_value = PduMappingDefaultValue()
                for element_element in self.findall(default_value_element, "DEFAULT-VALUE-ELEMENTS/DEFAULT-VALUE-ELEMENT"):
                    value = DefaultValueElement()
                    self.readDefaultValueElement(element_element, value)
                    default_value.addDefaultValueElement(value)
                i_pdu_ref.setDefaultValue(default_value)
            i_pdu_ref.setTargetIPduRef(self.getChildElementOptionalRefType(child_element, "TARGET-I-PDU-REF"))
        return i_pdu_ref

    def readDefaultValueElement(self, element: ET.Element, default_value: DefaultValueElement):
        self.readARObject(element, default_value)
        default_value.setElementByteValue(self.getChildElementOptionalIntegerValue(element, "ELEMENT-BYTE-VALUE"))
        default_value.setElementPosition(self.getChildElementOptionalIntegerValue(element, "ELEMENT-POSITION"))

    def getIPduMappings(self, element: ET.Element) -> List[IPduMapping]:
        mappings = []
        for child_element in self.findall(element, "I-PDU-MAPPINGS/I-PDU-MAPPING"):
            mapping = IPduMapping()
            mapping.setIntroduction(self.getDocumentationBlock(child_element, "INTRODUCTION"))
            mapping.setPduMaxLength(self.getChildElementOptionalPositiveInteger(child_element, "PDU-MAX-LENGTH"))
            mapping.setPdurTpChunkSize(self.getChildElementOptionalPositiveInteger(child_element, "PDUR-TP-CHUNK-SIZE"))
            mapping.setSourceIPduRef(self.getChildElementOptionalRefType(child_element, "SOURCE-I-PDU-REF"))
            mapping.setTargetIPdu(self.getTargetIPduRef(child_element, "TARGET-I-PDU"))
            mappings.append(mapping)
        return mappings

    def readGateway(self, element: ET.Element, gateway: Gateway):
        self.logger.debug("Read Gateway <%s>" % gateway.getShortName())
        self.readIdentifiable(element, gateway)
        gateway.setEcuRef(self.getChildElementOptionalRefType(element, "ECU-REF"))
        for frame_mapping in self.getFrameMappings(element):
            gateway.addFrameMapping(frame_mapping)
        for ipdu_mapping in self.getIPduMappings(element):
            gateway.addIPduMapping(ipdu_mapping)
        for signal_mapping in self.getISignalMappings(element):
            gateway.addSignalMapping(signal_mapping)

    def readISignal(self, element: ET.Element, signal: ISignal):
        self.logger.debug("Read ISignal <%s>" % signal.getShortName())
        self.readIdentifiable(element, signal)
        signal.setDataTransformationRef(self.getChildElementOptionalRefType(element, "DATA-TRANSFORMATIONS/DATA-TRANSFORMATION-REF-CONDITIONAL/DATA-TRANSFORMATION-REF"))
        signal.setDataTypePolicy(cast(Optional[DataTypePolicyEnum], self.getChildElementOptionalLiteral(element, "DATA-TYPE-POLICY")))
        signal.setISignalType(cast(Optional[ISignalTypeEnum], self.getChildElementOptionalLiteral(element, "I-SIGNAL-TYPE")))
        signal.setInitValue(self.getInitValue(element))
        signal.setLength(cast(Optional[UnlimitedInteger], self.getChildElementOptionalNumericalValue(element, "LENGTH")))
        signal.setNetworkRepresentationProps(self.getSwDataDefProps(element, "NETWORK-REPRESENTATION-PROPS"))
        signal.setSystemSignalRef(self.getChildElementOptionalRefType(element, "SYSTEM-SIGNAL-REF"))
        signal.setTimeoutSubstitutionValue(self.getChildValueSpecification(element, "TIMEOUT-SUBSTITUTION-VALUE"))
        self.readISignalProps(element, signal)
        self.readISignalTransformationISignalProps(element, signal)

    def readISignalProps(self, element: ET.Element, signal: ISignal):
        props_element = self.find(element, "I-SIGNAL-PROPS")
        if props_element is not None:
            props = ISignalProps()
            props.setHandleOutOfRange(cast(Optional[HandleOutOfRangeEnum], self.getChildElementOptionalLiteral(props_element, "HANDLE-OUT-OF-RANGE")))
            signal.setISignalProps(props)

    def readISignalTransformationISignalProps(self, element: ET.Element, signal: ISignal):
        for child_element in self.findall(element, "TRANSFORMATION-I-SIGNAL-PROPSS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "END-TO-END-TRANSFORMATION-I-SIGNAL-PROPS":
                props: ARObject = EndToEndTransformationISignalProps()
                self.readEndToEndTransformationISignalProps(child_element, cast(EndToEndTransformationISignalProps, props))
                signal.addTransformationISignalProps(cast(Optional[TransformationISignalProps], props))
            elif tag_name == "SOMEIP-TRANSFORMATION-I-SIGNAL-PROPS":
                props = SOMEIPTransformationISignalProps()
                self.readSOMEIPTransformationISignalProps(child_element, props)
                signal.addTransformationISignalProps(props)
            elif tag_name == "USER-DEFINED-TRANSFORMATION-I-SIGNAL-PROPS":
                props = UserDefinedTransformationISignalProps()
                self.readUserDefinedTransformationISignalProps(child_element, props)
                signal.addTransformationISignalProps(props)
            else:
                self.notImplemented("Unsupported TransformationISignalProps %s" % tag_name)

    def readEcucValueCollectionEcucValues(self, element: ET.Element, parent: EcucValueCollection):
        for child_element in self.findall(element, "ECUC-VALUES/ECUC-MODULE-CONFIGURATION-VALUES-REF-CONDITIONAL"):
            ref = self.getChildElementOptionalRefType(child_element, "ECUC-MODULE-CONFIGURATION-VALUES-REF")
            if ref is not None:
                parent.addEcucValueRef(ref)
                self.logger.debug("EcucValue <%s> of EcucValueCollection <%s> has been added", ref.value, parent.getShortName())

    def readEcucValueCollection(self, element: ET.Element, collection: EcucValueCollection):
        self.logger.debug("Read EcucValueCollection <%s>" % collection.getShortName())
        self.readIdentifiable(element, collection)
        collection.setEcuExtractRef(self.getChildElementOptionalRefType(element, "ECU-EXTRACT-REF"))
        self.readEcucValueCollectionEcucValues(element, collection)

    def readParameterValue(self, element: ET.Element, param_value: ParameterValue):
        """Read the R3.2.3 abstract ParameterValue members (DEFINITION-REF; DEST optional in legacy files)."""
        param_value.setDefinitionRef(self.getChildElementOptionalRefType(element, "DEFINITION-REF"))

    def readIntegerValue(self, element: ET.Element, integer_value: IntegerValue):
        """Read an R3.2.3 <INTEGER-VALUE> element (Table 3.34): DEFINITION-REF followed by VALUE."""
        self.readParameterValue(element, integer_value)
        child_element = self.find(element, "VALUE")
        if child_element is not None:
            value = UnlimitedInteger()
            self.readARType(child_element, value)
            value.setValue(child_element.text)
            integer_value.setValue(value)

    def readBooleanValue(self, element: ET.Element, boolean_value: BooleanValue):
        """Read an R3.2.3 <BOOLEAN-VALUE> element (Table 3.33): DEFINITION-REF followed by VALUE."""
        self.readParameterValue(element, boolean_value)
        boolean_value.setValue(self.getChildElementOptionalBooleanValue(element, "VALUE"))

    def readFloatValue(self, element: ET.Element, float_value: FloatValue):
        """Read an R3.2.3 <FLOAT-VALUE> element (Table 3.35): DEFINITION-REF followed by VALUE."""
        self.readParameterValue(element, float_value)
        float_value.setValue(self.getChildElementOptionalFloatValue(element, "VALUE"))

    def readMixedStringText(self, element: ET.Element, obj: AtpMixedString):
        """<<atpMixedString>>: the element text is the value (pure-text shape).
        Whitespace is preserved verbatim."""
        if element.text is not None and obj is not None:
            obj.setMixedString(element.text)

    def readStringValue(self, element: ET.Element, string_value: StringValue):
        """Read an R3.2.3 <STRING-VALUE> element (Table 3.36): DEFINITION-REF followed by VALUE."""
        self.readParameterValue(element, string_value)
        string_value.setValue(self.getChildElementOptionalString(element, "VALUE"))

    def readLinkerSymbolValue(self, element: ET.Element, linker_symbol_value: LinkerSymbolValue):
        """Read an R3.2.3 <LINKER-SYMBOL-VALUE> element (Table 3.37): DEFINITION-REF followed by VALUE."""
        self.readStringValue(element, linker_symbol_value)

    def readFunctionNameValue(self, element: ET.Element, function_name_value: FunctionNameValue):
        """Read an R3.2.3 <FUNCTION-NAME-VALUE> element (Table 3.38): DEFINITION-REF followed by VALUE."""
        self.readStringValue(element, function_name_value)

    def readEnumerationValue(self, element: ET.Element, enumeration_value: EnumerationValue):
        """Read an R3.2.3 <ENUMERATION-VALUE> element (Table 3.39): DEFINITION-REF followed by VALUE."""
        self.readParameterValue(element, enumeration_value)
        enumeration_value.setValue(self.getChildElementOptionalString(element, "VALUE"))

    def readConfigReferenceValue(self, element: ET.Element, config_reference_value: ConfigReferenceValue):
        """Read the R3.2.3 abstract ConfigReferenceValue members (S/T, DEFINITION-REF; DEST optional in legacy files)."""
        self.readARObject(element, config_reference_value)
        config_reference_value.setDefinitionRef(self.getChildElementOptionalRefType(element, "DEFINITION-REF"))

    def readReferenceValue(self, element: ET.Element, reference_value: ReferenceValue):
        """Read an R3.2.3 <REFERENCE-VALUE> element (Table 3.41): DEFINITION-REF followed by VALUE-REF."""
        self.readConfigReferenceValue(element, reference_value)
        reference_value.setValueRef(self.getChildElementOptionalRefType(element, "VALUE-REF"))

    def readInstanceReferenceValue(self, element: ET.Element, instance_reference_value: InstanceReferenceValue):
        """Read an R3.2.3 <INSTANCE-REFERENCE-VALUE> element (Table 3.42): DEFINITION-REF followed by VALUE-IREF (CONTEXT-REF* then VALUE-REF)."""
        self.readConfigReferenceValue(element, instance_reference_value)
        child_element = self.find(element, "VALUE-IREF")
        if child_element is not None:
            iref = AnyInstanceRef()
            for ref in self.getChildElementRefTypeList(child_element, "CONTEXT-REF"):
                iref.addContextElementRef(ref)
            iref.setTargetRef(self.getChildElementOptionalRefType(child_element, "VALUE-REF"))
            instance_reference_value.setValueIRef(iref)

    def readContainer(self, element: ET.Element, container: Container):
        """Read an R3.2.3 <CONTAINER> element (Table 3.31): SHORT-NAME, DEFINITION-REF, PARAMETER-VALUES, REFERENCE-VALUES, SUB-CONTAINERS."""
        self.readIdentifiable(element, container)
        container.setDefinitionRef(self.getChildElementOptionalRefType(element, "DEFINITION-REF"))
        for child_element in self.findall(element, "PARAMETER-VALUES/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "BOOLEAN-VALUE":
                value: ARObject = BooleanValue()
                self.readBooleanValue(child_element, cast(BooleanValue, value))
                container.addParameterValue(cast(ParameterValue, value))
            elif tag_name == "ENUMERATION-VALUE":
                value = EnumerationValue()
                self.readEnumerationValue(child_element, value)
                container.addParameterValue(value)
            elif tag_name == "FLOAT-VALUE":
                value = FloatValue()
                self.readFloatValue(child_element, value)
                container.addParameterValue(value)
            elif tag_name == "FUNCTION-NAME-VALUE":
                value = FunctionNameValue()
                self.readFunctionNameValue(child_element, value)
                container.addParameterValue(value)
            elif tag_name == "INTEGER-VALUE":
                value = IntegerValue()
                self.readIntegerValue(child_element, value)
                container.addParameterValue(value)
            elif tag_name == "LINKER-SYMBOL-VALUE":
                value = LinkerSymbolValue()
                self.readLinkerSymbolValue(child_element, value)
                container.addParameterValue(value)
            elif tag_name == "STRING-VALUE":
                value = StringValue()
                self.readStringValue(child_element, value)
                container.addParameterValue(value)
            else:
                self.notImplemented("Unsupported Container parameter value <%s>" % tag_name)
        for child_element in self.findall(element, "REFERENCE-VALUES/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "REFERENCE-VALUE":
                value = ReferenceValue()
                self.readReferenceValue(child_element, value)
                container.addReferenceValue(value)
            elif tag_name == "INSTANCE-REFERENCE-VALUE":
                value = InstanceReferenceValue()
                self.readInstanceReferenceValue(child_element, value)
                container.addReferenceValue(value)
            else:
                self.notImplemented("Unsupported Container reference value <%s>" % tag_name)
        for child_element in self.findall(element, "SUB-CONTAINERS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "CONTAINER":
                sub_container = container.createSubContainer(self.getShortName(child_element))
                self.readContainer(child_element, sub_container)
            else:
                self.notImplemented("Unsupported Container sub container <%s>" % tag_name)

    def readModuleConfiguration(self, element: ET.Element, module_configuration: ModuleConfiguration):
        """Read an R3.2.3 <MODULE-CONFIGURATION> element (Table 3.30): DEFINITION-REF, IMPLEMENTATION-CONFIG-VARIANT, MODULE-DESCRIPTION-REF, CONTAINERS."""
        self.readIdentifiable(element, module_configuration)
        module_configuration.setDefinitionRef(self.getChildElementOptionalRefType(element, "DEFINITION-REF"))
        module_configuration.setImplementationConfigVariant(cast(Optional[EcucConfigurationVariantEnum], self.getChildElementOptionalLiteral(element, "IMPLEMENTATION-CONFIG-VARIANT")))
        module_configuration.setModuleDescriptionRef(self.getChildElementOptionalRefType(element, "MODULE-DESCRIPTION-REF"))
        for child_element in self.findall(element, "CONTAINERS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "CONTAINER":
                container = module_configuration.createContainer(self.getShortName(child_element))
                self.readContainer(child_element, container)
            else:
                self.notImplemented("Unsupported ModuleConfiguration container <%s>" % tag_name)

    def readEcucIndexableValue(self, element: ET.Element, value: EcucIndexableValue):
        value.setIndex(self.getChildElementOptionalPositiveInteger(element, "INDEX"))

    def readEcucParameterValue(self, element: ET.Element, param_value: EcucParameterValue):
        param_value.setDefinitionRef(self.getChildElementOptionalRefType(element, "DEFINITION-REF"))
        self.readEcucIndexableValue(element, param_value)
        for annotation in self.getAnnotations(element):
            param_value.addAnnotation(annotation)
        param_value.setIsAutoValue(self.getChildElementOptionalBooleanValue(element, "IS-AUTO-VALUE"))

    def readEcucTextualParamValue(self, element: ET.Element, param_value: EcucTextualParamValue):
        self.readEcucParameterValue(element, param_value)
        param_value.setValue(self.getChildElementOptionalVerbatimString(element, "VALUE"))

    def readEcucNumericalParamValue(self, element: ET.Element, param_value: EcucNumericalParamValue):
        self.readEcucParameterValue(element, param_value)
        param_value.setValue(self.getChildElementOptionalNumerical(element, "VALUE"))

    def readEcucAddInfoParamValue(self, element: ET.Element, param_value: EcucAddInfoParamValue):
        self.readEcucParameterValue(element, param_value)
        param_value.setValue(self.getDocumentationBlock(element, "VALUE"))

    def readEcucContainerValueParameterValues(self, element: ET.Element, container_value: EcucContainerValue):
        for child_element in self.findall(element, "PARAMETER-VALUES/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "ECUC-TEXTUAL-PARAM-VALUE":
                param_value: ARObject = EcucTextualParamValue()
                self.readEcucTextualParamValue(child_element, cast(EcucTextualParamValue, param_value))
                container_value.addParameterValue(cast(EcucParameterValue, param_value))
            elif tag_name == "ECUC-NUMERICAL-PARAM-VALUE":
                param_value = EcucNumericalParamValue()
                self.readEcucNumericalParamValue(child_element, param_value)
                container_value.addParameterValue(param_value)
            elif tag_name == "ECUC-ADD-INFO-PARAM-VALUE":
                param_value = EcucAddInfoParamValue()
                self.readEcucAddInfoParamValue(child_element, param_value)
                container_value.addParameterValue(param_value)
            else:
                self.notImplemented("Unsupported EcucParameterValue <%s>" % tag_name)

    def readEcucAbstractReferenceValue(self, element: ET.Element, value: EcucAbstractReferenceValue):
        value.setDefinitionRef(self.getChildElementOptionalRefType(element, "DEFINITION-REF"))
        self.readEcucIndexableValue(element, value)
        for annotation in self.getAnnotations(element):
            value.addAnnotation(annotation)
        value.setIsAutoValue(self.getChildElementOptionalBooleanValue(element, "IS-AUTO-VALUE"))

    def readEcucReferenceValue(self, element: ET.Element, value: EcucReferenceValue):
        self.readEcucAbstractReferenceValue(element, value)
        value.setValueRef(self.getChildElementOptionalRefType(element, "VALUE-REF"))

    def getAnyInstanceRef(self, element: ET.Element, key) -> Optional[AnyInstanceRef]:
        instance_ref = None
        child_element = self.find(element, key)
        if child_element is not None:
            instance_ref = self.getAnyInstanceRefFromElement(child_element)
        return instance_ref

    def getAnyInstanceRefFromElement(self, child_element: ET.Element) -> AnyInstanceRef:
        instance_ref = AnyInstanceRef()
        instance_ref.setBaseRef(self.getChildElementOptionalRefType(child_element, "BASE-REF"))
        for ref in self.getChildElementRefTypeList(child_element, "CONTEXT-ELEMENT-REF"):
            instance_ref.addContextElementRef(ref)
        instance_ref.setTargetRef(self.getChildElementOptionalRefType(child_element, "TARGET-REF"))
        return instance_ref

    def readEcucInstanceReferenceValue(self, element: ET.Element, value: EcucInstanceReferenceValue):
        self.readEcucAbstractReferenceValue(element, value)
        value.setValueIRef(self.getAnyInstanceRef(element, "VALUE-IREF"))

    def readEcucContainerValueReferenceValues(self, element: ET.Element, container_value: EcucContainerValue):
        for child_element in self.findall(element, "REFERENCE-VALUES/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "ECUC-REFERENCE-VALUE":
                value: ARObject = EcucReferenceValue()
                self.readEcucReferenceValue(child_element, cast(EcucReferenceValue, value))
                container_value.addReferenceValue(cast(EcucAbstractReferenceValue, value))
            elif tag_name == "ECUC-INSTANCE-REFERENCE-VALUE":
                value = EcucInstanceReferenceValue()
                self.readEcucInstanceReferenceValue(child_element, value)
                container_value.addReferenceValue(value)
            else:
                self.notImplemented("Unsupported EcucParameterValue <%s>" % tag_name)

    def readEcucContainerValue(self, element: ET.Element, container_value: EcucContainerValue):
        self.readIdentifiable(element, container_value)
        container_value.setDefinitionRef(cast(RefType, self.getChildElementOptionalRefType(element, "DEFINITION-REF")))
        self.readEcucIndexableValue(element, container_value)
        self.readEcucContainerValueParameterValues(element, container_value)
        self.readEcucContainerValueReferenceValues(element, container_value)
        self.readEcucContainerValueSubContainers(element, container_value)

    def readEcucContainerValueEcucContainerValue(self, element: ET.Element, parent: EcucContainerValue):
        short_name = self.getShortName(element)
        self.logger.debug("EcucContainerValue %s" % short_name)
        container_value = parent.createSubContainer(short_name)
        self.readEcucContainerValue(element, container_value)

    def readEcucContainerValueSubContainers(self, element: ET.Element, parent: EcucContainerValue):
        for child_element in self.findall(element, "SUB-CONTAINERS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "ECUC-CONTAINER-VALUE":
                self.readEcucContainerValueEcucContainerValue(child_element, parent)
            else:
                self.notImplemented("Unsupported Sub Container %s" % tag_name)

    def readEcucModuleConfigurationValuesEcucContainerValue(self, element: ET.Element, parent: EcucModuleConfigurationValues):
        short_name = self.getShortName(element)
        self.logger.debug("EcucContainerValue %s" % short_name)
        container_value = parent.createContainer(short_name)
        self.readEcucContainerValue(element, container_value)

    def readEcucModuleConfigurationValuesContainers(self, element: ET.Element, values: EcucModuleConfigurationValues):
        for child_element in self.findall(element, "CONTAINERS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "ECUC-CONTAINER-VALUE":
                self.readEcucModuleConfigurationValuesEcucContainerValue(child_element, values)
            else:
                self.notImplemented("Unsupported Container %s" % tag_name)

    def readEcucModuleConfigurationValues(self, element: ET.Element, values: EcucModuleConfigurationValues):
        self.logger.debug("Read EcucModuleConfigurationValues %s" % values.getShortName())
        self.readIdentifiable(element, values)
        values.setDefinitionRef(cast(RefType, self.getChildElementOptionalRefType(element, "DEFINITION-REF")))
        values.setEcucDefEdition(cast(RevisionLabelString, self.getChildElementOptionalRevisionLabelString(element, "ECUC-DEF-EDITION")))
        values.setImplementationConfigVariant(cast(EcucConfigurationVariantEnum, self.getChildElementOptionalLiteral(element, "IMPLEMENTATION-CONFIG-VARIANT")))
        values.setModuleDescriptionRef(cast(RefType, self.getChildElementOptionalRefType(element, "MODULE-DESCRIPTION-REF")))
        values.setPostBuildVariantUsed(cast(Boolean, self.getChildElementOptionalBooleanValue(element, "POST-BUILD-VARIANT-USED")))
        self.readEcucModuleConfigurationValuesContainers(element, values)

    def readPhysicalDimension(self, element: ET.Element, dimension: PhysicalDimension):
        self.logger.debug("Read PhysicalDimension <%s>" % dimension.getShortName())
        self.readIdentifiable(element, dimension)
        dimension.setLengthExp(self.getChildElementOptionalNumericalValue(element, "LENGTH-EXP"))
        dimension.setLuminousIntensityExp(self.getChildElementOptionalNumericalValue(element, "LUMINOUS-INTENSITY-EXP"))
        dimension.setMassExp(self.getChildElementOptionalNumericalValue(element, "MASS-EXP"))
        dimension.setMolarAmountExp(self.getChildElementOptionalNumericalValue(element, "MOLAR-AMOUNT-EXP"))
        dimension.setTemperatureExp(self.getChildElementOptionalNumericalValue(element, "TEMPERATURE-EXP"))
        dimension.setTimeExp(self.getChildElementOptionalNumericalValue(element, "TIME-EXP"))
        dimension.setCurrentExp(self.getChildElementOptionalNumericalValue(element, "CURRENT-EXP"))

    def readISignalGroupISignalRef(self, element: ET.Element, group: ISignalGroup):
        for ref_type in self.getChildElementRefTypeList(element, "I-SIGNAL-REFS/I-SIGNAL-REF"):
            group.addISignalRef(ref_type)

    def readISignalGroupComBasedSignalGroupTransformation(self, element: ET.Element, group: ISignalGroup):
        ref = self.getChildElementOptionalRefType(element, "COM-BASED-SIGNAL-GROUP-TRANSFORMATIONS/DATA-TRANSFORMATION-REF-CONDITIONAL/DATA-TRANSFORMATION-REF")
        group.setComBasedSignalGroupTransformationRef(ref)

    def readTransformationISignalProps(self, element: ET.Element, props: TransformationISignalProps):
        self.readDescribable(element, props)
        cs_error_reaction = self.getChildElementOptionalLiteral(element, "CS-ERROR-REACTION")
        if cs_error_reaction is not None:
            e = CSTransformerErrorReactionEnum()
            e.setValue(cs_error_reaction.getValue())
            props.setCsErrorReaction(e)
        for child_element in self.findall(element, "DATA-PROTOTYPE-TRANSFORMATION-PROPSS/*"):
            if self.getTagName(child_element) == "DATA-PROTOTYPE-TRANSFORMATION-PROPS":
                dp_props = DataPrototypeTransformationProps()
                self.readDataPrototypeTransformationProps(child_element, dp_props)
                props.addDataPrototypeTransformationProps(dp_props)
            else:
                self.notImplemented("Unsupported DataPrototypeTransformationProps %s" % self.getTagName(child_element))

    def readDataPrototypeInPortInterfaceRef(self, element: ET.Element, ref: DataPrototypeInPortInterfaceRef):
        self.readARObject(element, ref)
        ref.setTagId(self.getChildElementOptionalPositiveInteger(element, "TAG-ID"))
        child_element = self.find(element, "DATA-PROTOTYPE-IN-CLIENT-SERVER-INTERFACE-REF")
        if child_element is not None:
            cs_ref = DataPrototypeInClientServerInterfaceInstanceRef()
            self.readDataPrototypeInClientServerInterfaceInstanceRef(child_element, cs_ref)
            ref.setDataPrototypeInClientServerInterface(cs_ref)

    def readDataPrototypeInSenderReceiverInterfaceInstanceRef(self, element: ET.Element, iref: DataPrototypeInSenderReceiverInterfaceInstanceRef):
        self.readARObject(element, iref)
        iref.setBaseRef(self.getChildElementOptionalRefType(element, "BASE"))
        for ctx in self.findall(element, "CONTEXT-DATA-PROTOTYPE-IN-SR"):
            iref.addContextDataPrototypeInSrRefs(self.getChildElementOptionalRefType(ctx, "CONTEXT-DATA-PROTOTYPE-IN-SR") or self.getChildElementOptionalRefType(ctx, "CONTEXT-DATA-PROTOTYPE"))
        iref.setRootDataPrototypeInSrRef(self.getChildElementOptionalRefType(element, "ROOT-DATA-PROTOTYPE-IN-SR"))
        iref.setTargetDataPrototypeInSrRef(self.getChildElementOptionalRefType(element, "TARGET-DATA-PROTOTYPE-IN-SR"))

    def readDataPrototypeInClientServerInterfaceInstanceRef(self, element: ET.Element, iref: DataPrototypeInClientServerInterfaceInstanceRef):
        self.readARObject(element, iref)
        iref.setBaseRef(self.getChildElementOptionalRefType(element, "BASE"))
        for ctx in self.findall(element, "CONTEXT-DATA-PROTOTYPE-IN-CS"):
            iref.addContextDataPrototypeInCsRefs(self.getChildElementOptionalRefType(ctx, "CONTEXT-DATA-PROTOTYPE-IN-CS") or self.getChildElementOptionalRefType(ctx, "CONTEXT-DATA-PROTOTYPE"))
        iref.setRootDataPrototypeInCsRef(self.getChildElementOptionalRefType(element, "ROOT-DATA-PROTOTYPE-IN-CS"))
        iref.setTargetDataPrototypeInCsRef(self.getChildElementOptionalRefType(element, "TARGET-DATA-PROTOTYPE-IN-CS"))

    def readDataPrototypeTransformationProps(self, element: ET.Element, props: DataPrototypeTransformationProps):
        self.readARObject(element, props)
        child_element = self.find(element, "DATA-PROTOTYPE-IN-PORT-INTERFACE-REF")
        if child_element is not None:
            ref = DataPrototypeInPortInterfaceRef()
            self.readDataPrototypeInPortInterfaceRef(child_element, ref)
            props.setDataPrototypeInPortInterfaceRef(ref)
        props.setNetworkRepresentationProps(self.getSwDataDefProps(element, "NETWORK-REPRESENTATION-PROPS"))
        props.setTransformationPropsRef(self.getChildElementOptionalRefType(element, "TRANSFORMATION-PROPS-REF"))

    def readEndToEndTransformationISignalPropsDataIds(self, element: ET.Element, props: EndToEndTransformationISignalProps):
        child_element = self.find(element, "DATA-IDS")
        if child_element is not None:
            for data_id_element in self.findall(child_element, "DATA-ID"):
                if data_id_element.text is not None:
                    data_id = PositiveInteger()
                    data_id.setValue(data_id_element.text)
                    props.addDataId(data_id)

    def readEndToEndTransformationISignalProps(self, element: ET.Element, props: EndToEndTransformationISignalProps):
        child_element = self.find(element, "END-TO-END-TRANSFORMATION-I-SIGNAL-PROPS-VARIANTS/END-TO-END-TRANSFORMATION-I-SIGNAL-PROPS-CONDITIONAL")
        if child_element is not None:
            self.readTransformationISignalProps(child_element, props)
            props.setTransformerRef(self.getChildElementOptionalRefType(child_element, "TRANSFORMER-REF"))
            self.readEndToEndTransformationISignalPropsDataIds(child_element, props)
            props.setDataLength(self.getChildElementOptionalPositiveInteger(child_element, "DATA-LENGTH"))
            props.setMaxDataLength(self.getChildElementOptionalPositiveInteger(child_element, "MAX-DATA-LENGTH"))
            props.setMinDataLength(self.getChildElementOptionalPositiveInteger(child_element, "MIN-DATA-LENGTH"))
            props.setSourceId(self.getChildElementOptionalPositiveInteger(child_element, "SOURCE-ID"))

    def readSOMEIPTransformationISignalProps(self, element: ET.Element, props: SOMEIPTransformationISignalProps):
        child_element = self.find(element, "SOMEIP-TRANSFORMATION-I-SIGNAL-PROPS-VARIANTS/SOMEIP-TRANSFORMATION-I-SIGNAL-PROPS-CONDITIONAL")
        if child_element is not None:
            self.readTransformationISignalProps(child_element, props)
            props.setTransformerRef(self.getChildElementOptionalRefType(child_element, "TRANSFORMER-REF"))
            props.setImplementsLegacyStringSerialization(self.getChildElementOptionalBooleanValue(child_element, "IMPLEMENTS-LEGACY-STRING-SERIALIZATION"))
            props.setInterfaceVersion(self.getChildElementOptionalPositiveInteger(child_element, "INTERFACE-VERSION"))
            props.setIsDynamicLengthFieldSize(self.getChildElementOptionalBooleanValue(child_element, "IS-DYNAMIC-LENGTH-FIELD-SIZE"))
            message_type = self.getChildElementOptionalLiteral(child_element, "MESSAGE-TYPE")
            if message_type is not None:
                message_type_enum = SOMEIPMessageTypeEnum()
                message_type_enum.setValue(message_type.getValue())
                props.setMessageType(message_type_enum)
            props.setSizeOfArrayLengthFields(self.getChildElementOptionalPositiveInteger(child_element, "SIZE-OF-ARRAY-LENGTH-FIELDS"))
            props.setSizeOfStringLengthFields(self.getChildElementOptionalPositiveInteger(child_element, "SIZE-OF-STRING-LENGTH-FIELDS"))
            props.setSizeOfStructLengthFields(self.getChildElementOptionalPositiveInteger(child_element, "SIZE-OF-STRUCT-LENGTH-FIELDS"))
            props.setSizeOfUnionLengthFields(self.getChildElementOptionalPositiveInteger(child_element, "SIZE-OF-UNION-LENGTH-FIELDS"))
            for ref_type in self.getChildElementRefTypeList(child_element, "TLV-DATA-ID-DEFINITION-REFS/TLV-DATA-ID-DEFINITION-REF"):
                props.addTlvDataIdDefinitionRef(ref_type)

    def readUserDefinedTransformationISignalProps(self, element: ET.Element, props: UserDefinedTransformationISignalProps):
        child_element = self.find(element, "USER-DEFINED-TRANSFORMATION-I-SIGNAL-PROPS-VARIANTS/USER-DEFINED-TRANSFORMATION-I-SIGNAL-PROPS-CONDITIONAL")
        if child_element is not None:
            self.readTransformationISignalProps(child_element, props)
            props.setTransformerRef(self.getChildElementOptionalRefType(child_element, "TRANSFORMER-REF"))

    def readISignalGroupTransformationISignalProps(self, element: ET.Element, group: ISignalGroup):
        for child_element in self.findall(element, "TRANSFORMATION-I-SIGNAL-PROPSS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "END-TO-END-TRANSFORMATION-I-SIGNAL-PROPS":
                props: ARObject = EndToEndTransformationISignalProps()
                self.readEndToEndTransformationISignalProps(child_element, cast(EndToEndTransformationISignalProps, props))
                group.addTransformationISignalProps(cast(TransformationISignalProps, props))
            elif tag_name == "SOMEIP-TRANSFORMATION-I-SIGNAL-PROPS":
                props = SOMEIPTransformationISignalProps()
                self.readSOMEIPTransformationISignalProps(child_element, props)
                group.addTransformationISignalProps(props)
            elif tag_name == "USER-DEFINED-TRANSFORMATION-I-SIGNAL-PROPS":
                props = UserDefinedTransformationISignalProps()
                self.readUserDefinedTransformationISignalProps(child_element, props)
                group.addTransformationISignalProps(props)
            else:
                self.notImplemented("Unsupported TransformationISignalProps %s" % tag_name)

    def readISignalGroup(self, element: ET.Element, group: ISignalGroup):
        self.logger.debug("Read ISignalGroup <%s>" % group.getShortName())
        self.readIdentifiable(element, group)
        self.readISignalGroupComBasedSignalGroupTransformation(element, group)
        self.readISignalGroupISignalRef(element, group)
        group.setSystemSignalGroupRef(self.getChildElementOptionalRefType(element, "SYSTEM-SIGNAL-GROUP-REF"))
        self.readISignalGroupTransformationISignalProps(element, group)

    def readSystemSignal(self, element: ET.Element, signal: SystemSignal):
        self.logger.debug("Read SystemSignal <%s>" % signal.getShortName())
        self.readIdentifiable(element, signal)
        signal.setDynamicLength(self.getChildElementOptionalBooleanValue(element, "DYNAMIC-LENGTH"))
        signal.setPhysicalProps(self.getSwDataDefProps(element, "PHYSICAL-PROPS"))

    def readSystemSignalGroup(self, element: ET.Element, group: SystemSignalGroup):
        self.logger.debug("Read SystemSignalGroup <%s>" % group.getShortName())
        self.readIdentifiable(element, group)
        for ref_type in self.getChildElementRefTypeList(element, "SYSTEM-SIGNAL-REFS/SYSTEM-SIGNAL-REF"):
            group.addSystemSignalRef(ref_type)
        group.setTransformingSystemSignalRef(self.getChildElementOptionalRefType(element, "TRANSFORMING-SYSTEM-SIGNAL-REF"))

    def readSignalServiceTranslationPropsSet(self, element: ET.Element, props_set: SignalServiceTranslationPropsSet):
        self.logger.debug("Read SignalServiceTranslationPropsSet <%s>" % props_set.getShortName())
        self.readIdentifiable(element, props_set)
        for child_element in self.findall(element, "SIGNAL-SERVICE-TRANSLATION-PROPS"):
            props = props_set.createSignalServiceTranslationProps(self.getShortName(child_element))
            self.readSignalServiceTranslationProps(child_element, props)

    def readSignalServiceTranslationProps(self, element: ET.Element, props: SignalServiceTranslationProps):
        self.logger.debug("Read SignalServiceTranslationProps <%s>" % props.getShortName())
        self.readIdentifiable(element, props)
        for ref_type in self.getChildElementRefTypeList(element, "CONTROL-CONSUMED-EVENT-GROUP-REFS/CONTROL-CONSUMED-EVENT-GROUP-REF"):
            props.addControlConsumedEventGroupRef(ref_type)
        for ref_type in self.getChildElementRefTypeList(element, "CONTROL-PNC-REFS/CONTROL-PNC-REF"):
            props.addControlPncRef(ref_type)
        for ref_type in self.getChildElementRefTypeList(element, "CONTROL-PROVIDED-EVENT-GROUP-REFS/CONTROL-PROVIDED-EVENT-GROUP-REF"):
            props.addControlProvidedEventGroupRef(ref_type)
        props.setServiceControl(cast(Optional[SignalServiceTranslationControlEnum], self.getChildElementOptionalLiteral(element, "SERVICE-CONTROL")))
        for child_element in self.findall(element, "SIGNAL-SERVICE-TRANSLATION-EVENT-PROPS"):
            event_props = props.createSignalServiceTranslationEventProps(self.getShortName(child_element))
            self.readSignalServiceTranslationEventProps(child_element, event_props)

    def readSignalServiceTranslationEventProps(self, element: ET.Element, event_props: SignalServiceTranslationEventProps):
        self.logger.debug("Read SignalServiceTranslationEventProps <%s>" % event_props.getShortName())
        self.readIdentifiable(element, event_props)
        for child_element in self.findall(element, "SIGNAL-SERVICE-TRANSLATION-ELEMENT-PROPS"):
            element_props = event_props.createSignalServiceTranslationElementProps(self.getShortName(child_element))
            self.readSignalServiceTranslationElementProps(child_element, element_props)
        event_props.setSafeTranslation(self.getChildElementOptionalBooleanValue(element, "SAFE-TRANSLATION"))
        event_props.setSecureTranslation(self.getChildElementOptionalBooleanValue(element, "SECURE-TRANSLATION"))
        event_props.setTranslationTarget(self.getVariableDataPrototypeInSystemInstanceRef(cast(ET.Element, self.find(element, "TRANSLATION-TARGET"))))

    def readSignalServiceTranslationElementProps(self, element: ET.Element, element_props: SignalServiceTranslationElementProps):
        self.logger.debug("Read SignalServiceTranslationElementProps <%s>" % element_props.getShortName())
        self.readIdentifiable(element, element_props)
        element_props.setFilter(self.getDataFilter(element, "FILTER"))
        element_props.setTransmissionTrigger(self.getChildElementOptionalBooleanValue(element, "TRANSMISSION-TRIGGER"))

    def readISignalToPduMappings(self, element: ET.Element, parent: ISignalIPdu):
        for child_element in self.findall(element, "I-SIGNAL-TO-PDU-MAPPINGS/I-SIGNAL-TO-I-PDU-MAPPING"):
            short_name = self.getShortName(child_element)
            mapping = parent.createISignalToPduMappings(short_name)
            self.readIdentifiable(child_element, mapping)
            mapping.setISignalRef(self.getChildElementOptionalRefType(child_element, "I-SIGNAL-REF"))
            mapping.setISignalGroupRef(self.getChildElementOptionalRefType(child_element, "I-SIGNAL-GROUP-REF"))
            mapping.setPackingByteOrder(cast(Optional[ByteOrderEnum], self.getChildElementOptionalLiteral(child_element, "PACKING-BYTE-ORDER")))
            mapping.setStartPosition(cast(Optional[UnlimitedInteger], self.getChildElementOptionalNumericalValue(child_element, "START-POSITION")))
            mapping.setTransferProperty(cast(Optional[TransferPropertyEnum], self.getChildElementOptionalLiteral(child_element, "TRANSFER-PROPERTY")))
            mapping.setUpdateIndicationBitPosition(cast(Optional[UnlimitedInteger], self.getChildElementOptionalNumericalValue(child_element, "UPDATE-INDICATION-BIT-POSITION")))

    def getDataFilter(self, element: ET.Element, key: str) -> Optional[DataFilter]:
        filter = None
        child_element = self.find(element, key)
        if child_element is not None:
            filter = DataFilter()
            literal = self.getChildElementOptionalLiteral(child_element, "DATA-FILTER-TYPE")
            if literal is not None:
                filter.setDataFilterType(DataFilterTypeEnum().setValue(literal.getText()))
            filter.setMask(self.getChildElementOptionalUnlimitedInteger(child_element, "MASK"))
            filter.setMax(self.getChildElementOptionalUnlimitedInteger(child_element, "MAX"))
            filter.setMin(self.getChildElementOptionalUnlimitedInteger(child_element, "MIN"))
            filter.setOffset(self.getChildElementOptionalPositiveInteger(child_element, "OFFSET"))
            filter.setPeriod(self.getChildElementOptionalPositiveInteger(child_element, "PERIOD"))
            filter.setX(self.getChildElementOptionalUnlimitedInteger(child_element, "X"))

        return filter

    def getTransmissionModeConditions(self, element: ET.Element, key: str) -> List[TransmissionModeCondition]:
        result = []
        child_elements = self.findall(element, key)
        for child_element in child_elements:
            condition = TransmissionModeCondition()
            self.readARObject(child_element, condition)
            condition.setDataFilter(self.getDataFilter(child_element, "DATA-FILTER"))
            condition.setISignalInIPduRef(self.getChildElementOptionalRefType(child_element, "I-SIGNAL-IN-I-PDU-REF"))
            result.append(condition)
        return result

    def getTimeRangeType(self, element: ET.Element, key: str) -> Optional[TimeRangeType]:
        time_range = None
        child_element = self.find(element, key)
        if child_element is not None:
            time_range = TimeRangeType()
            self.readARObject(child_element, time_range)
            tolerance_element = self.find(child_element, "TOLERANCE")
            if tolerance_element is not None:
                absolute_element = self.find(tolerance_element, "ABSOLUTE-TOLERANCE")
                relative_element = self.find(tolerance_element, "RELATIVE-TOLERANCE")
                if absolute_element is not None:
                    abs_tolerance = AbsoluteTolerance()
                    self.readARObject(absolute_element, abs_tolerance)
                    abs_tolerance.setAbsolute(self.getChildElementOptionalTimeValue(absolute_element, "ABSOLUTE"))
                    time_range.setTolerance(abs_tolerance)
                elif relative_element is not None:
                    rel_tolerance = RelativeTolerance()
                    self.readARObject(relative_element, rel_tolerance)
                    rel_tolerance.setRelative(self.getChildElementOptionalIntegerValue(relative_element, "RELATIVE"))
                    time_range.setTolerance(rel_tolerance)
            time_range.setValue(self.getChildElementOptionalTimeValue(child_element, "VALUE"))
        return time_range

    def getCyclicTiming(self, element: ET.Element, key: str) -> Optional[CyclicTiming]:
        timing = None
        child_element = self.find(element, key)
        if child_element is not None:
            timing = CyclicTiming()
            self.readARObject(child_element, timing)
            timing.setTimeOffset(self.getTimeRangeType(child_element, "TIME-OFFSET"))
            timing.setTimePeriod(self.getTimeRangeType(child_element, "TIME-PERIOD"))
        return timing

    def getEventControlledTiming(self, element: ET.Element, key: str) -> Optional[EventControlledTiming]:
        timing = None
        child_element = self.find(element, key)
        if child_element is not None:
            timing = EventControlledTiming()
            self.readARObject(child_element, timing)
            timing.setNumberOfRepetitions(self.getChildElementOptionalIntegerValue(child_element, "NUMBER-OF-REPETITIONS"))
            timing.setRepetitionPeriod(self.getTimeRangeType(child_element, "REPETITION-PERIOD"))
        return timing

    def getTransmissionModeTiming(self, element: ET.Element, key: str) -> Optional[TransmissionModeTiming]:
        timing = None
        child_element = self.find(element, key)
        if child_element is not None:
            # self.logger.debug("Get TransmissionModeTiming of <%s>" % key)
            timing = TransmissionModeTiming()
            self.readARObject(child_element, timing)
            timing.setCyclicTiming(self.getCyclicTiming(child_element, "CYCLIC-TIMING"))
            timing.setEventControlledTiming(self.getEventControlledTiming(child_element, "EVENT-CONTROLLED-TIMING"))
        return timing

    def getTransmissionModeDeclaration(self, element: ET.Element, key: str) -> Optional[TransmissionModeDeclaration]:
        decl = None
        child_element = self.find(element, key)
        if child_element is not None:
            decl = TransmissionModeDeclaration()
            self.readARObject(child_element, decl)
            for condition_element in self.findall(child_element, "MODE-DRIVEN-FALSE-CONDITIONS/MODE-DRIVEN-TRANSMISSION-MODE-CONDITION"):
                condition = ModeDrivenTransmissionModeCondition()
                self.readModeDrivenTransmissionModeCondition(condition_element, condition)
                decl.addModeDrivenFalseCondition(condition)
            for condition_element in self.findall(child_element, "MODE-DRIVEN-TRUE-CONDITIONS/MODE-DRIVEN-TRANSMISSION-MODE-CONDITION"):
                condition = ModeDrivenTransmissionModeCondition()
                self.readModeDrivenTransmissionModeCondition(condition_element, condition)
                decl.addModeDrivenTrueCondition(condition)
            for tm_condition in self.getTransmissionModeConditions(child_element, "TRANSMISSION-MODE-CONDITIONS/TRANSMISSION-MODE-CONDITION"):
                decl.addTransmissionModeCondition(tm_condition)
            decl.setTransmissionModeFalseTiming(self.getTransmissionModeTiming(child_element, "TRANSMISSION-MODE-FALSE-TIMING"))
            decl.setTransmissionModeTrueTiming(self.getTransmissionModeTiming(child_element, "TRANSMISSION-MODE-TRUE-TIMING"))
        return decl

    def getISignalIPduIPduTimingSpecification(self, element: ET.Element) -> Optional[IPduTiming]:
        timing = None
        child_element = self.find(element, "I-PDU-TIMING-SPECIFICATIONS/I-PDU-TIMING")
        if child_element is not None:
            timing = IPduTiming()
            timing.setMinimumDelay(self.getChildElementOptionalTimeValue(child_element, "MINIMUM-DELAY"))
            timing.setTransmissionModeDeclaration(self.getTransmissionModeDeclaration(child_element, "TRANSMISSION-MODE-DECLARATION"))
        return timing

    def readDoIpConfig(self, element: ET.Element, config: DoIpConfig):
        for child_element in self.findall(element, "DOIP-INTERFACES/DO-IP-INTERFACE"):
            interface = config.createDoIpInterface(self.getShortName(child_element))
            self.readDoIpInterface(child_element, interface)
        logic_address_element = self.find(element, "LOGIC-ADDRESS")
        if logic_address_element is not None:
            address = config.createLogicAddress(self.getShortName(logic_address_element))
            self.readDoIpLogicAddress(logic_address_element, address)

    def readDoIpInterface(self, element: ET.Element, interface: DoIpInterface):
        self.logger.debug("Read DoIpInterface <%s>" % interface.getShortName())
        self.readIdentifiable(element, interface)
        interface.setAliveCheckResponseTimeout(self.getChildElementOptionalTimeValue(element, "ALIVE-CHECK-RESPONSE-TIMEOUT"))
        for child_element in self.findall(element, "DO-IP-ROUTING-ACTIVATIONS/DO-IP-ROUTING-ACTIVATION"):
            activation = interface.createDoIpRoutingActivation(self.getShortName(child_element))
            self.readDoIpRoutingActivation(child_element, activation)
        interface.setDoipChannelCollectionRef(self.getChildElementOptionalRefType(element, "DOIP-CHANNEL-COLLECTION-REF"))
        for ref in self.getChildElementRefTypeList(element, "DOIP-CONNECTION-REFS/DOIP-CONNECTION-REF"):
            interface.addDoipConnectionRef(ref)
        interface.setGeneralInactivityTime(self.getChildElementOptionalTimeValue(element, "GENERAL-INACTIVITY-TIME"))
        interface.setInitialInactivityTime(self.getChildElementOptionalTimeValue(element, "INITIAL-INACTIVITY-TIME"))
        interface.setInitialVehicleAnnouncementTime(self.getChildElementOptionalTimeValue(element, "INITIAL-VEHICLE-ANNOUNCEMENT-TIME"))
        interface.setIsActivationLineDependent(self.getChildElementOptionalBooleanValue(element, "IS-ACTIVATION-LINE-DEPENDENT"))
        interface.setMaxTesterConnections(self.getChildElementOptionalPositiveInteger(element, "MAX-TESTER-CONNECTIONS"))
        for ref in self.getChildElementRefTypeList(element, "SOCKET-CONNECTION-REFS/SOCKET-CONNECTION-REF"):
            interface.addSocketConnectionRef(ref)
        interface.setUseMacAddressForIdentification(self.getChildElementOptionalBooleanValue(element, "USE-MAC-ADDRESS-FOR-IDENTIFICATION"))
        interface.setUseVehicleIdentificationSyncStatus(self.getChildElementOptionalBooleanValue(element, "USE-VEHICLE-IDENTIFICATION-SYNC-STATUS"))
        interface.setVehicleAnnouncementCount(self.getChildElementOptionalPositiveInteger(element, "VEHICLE-ANNOUNCEMENT-COUNT"))
        interface.setVehicleAnnouncementInterval(self.getChildElementOptionalTimeValue(element, "VEHICLE-ANNOUNCEMENT-INTERVAL"))

    def readDoIpRoutingActivation(self, element: ET.Element, activation: DoIpRoutingActivation):
        self.logger.debug("Read DoIpRoutingActivation <%s>" % activation.getShortName())
        self.readIdentifiable(element, activation)
        for ref in self.getChildElementRefTypeList(element, "DO-IP-TARGET-ADDRESS-REFS/DO-IP-TARGET-ADDRESS-REF"):
            activation.addDoIpTargetAddressRef(ref)

    def readISignalIPdu(self, element: ET.Element, ipdu: ISignalIPdu):
        self.logger.debug("Read ISignalIPdu <%s>" % ipdu.getShortName())
        self.readIdentifiable(element, ipdu)
        ipdu.setLength(cast(Optional[UnlimitedInteger], self.getChildElementOptionalNumericalValue(element, "LENGTH")))
        ipdu.setIPduTimingSpecification(self.getISignalIPduIPduTimingSpecification(element))
        self.readISignalToPduMappings(element, ipdu)
        ipdu.setUnusedBitPattern(self.getChildElementOptionalIntegerValue(element, "UNUSED-BIT-PATTERN"))

    def getISignalIPduRefs(self, element: ET.Element) -> Optional[List[RefType]]:
        ref_types = []
        for child_element in self.findall(element, "I-SIGNAL-I-PDUS/I-SIGNAL-I-PDU-REF-CONDITIONAL"):
            ref_types.append(cast(RefType, self.getChildElementOptionalRefType(child_element, "I-SIGNAL-I-PDU-REF")))
        return ref_types

    def readISignalIPduGroup(self, element: ET.Element, group: ISignalIPduGroup):
        self.logger.debug("Read ISignalIPduGroup <%s>" % group.getShortName())
        self.readIdentifiable(element, group)
        group.setCommunicationDirection(cast(Optional[CommunicationDirectionType], self.getChildElementOptionalLiteral(element, "COMMUNICATION-DIRECTION")))
        group.setCommunicationMode(cast(Optional[String], self.getChildElementOptionalLiteral(element, "COMMUNICATION-MODE")))
        for ref_type in self.getChildElementRefTypeList(element, "CONTAINED-I-SIGNAL-I-PDU-GROUP-REFS/CONTAINED-I-SIGNAL-I-PDU-GROUP-REF"):
            group.addContainedISignalIPduGroupRef(ref_type)
        isignal_ipdu_refs = self.getISignalIPduRefs(element)
        if isignal_ipdu_refs is not None:
            for ref_type in isignal_ipdu_refs:
                group.addISignalIPduRef(ref_type)
        for ref_type in self.getChildElementRefTypeList(element, "NM-PDUS/NM-PDU-REF-CONDITIONAL/NM-PDU-REF"):
            group.addNmPduRef(ref_type)

    def readPdurIPduGroup(self, element: ET.Element, group: PdurIPduGroup):
        self.logger.debug("Read PdurIPduGroup <%s>" % group.getShortName())
        self.readIdentifiable(element, group)
        group.setCommunicationMode(self.getChildElementOptionalString(element, "COMMUNICATION-MODE"))
        for child_element in self.findall(element, "I-PDUS/PDU-TRIGGERING-REF-CONDITIONAL"):
            group.addIPduRef(self.getChildElementOptionalRefType(child_element, "PDU-TRIGGERING-REF"))

    def readDataMapping(self, element: ET.Element, mapping: DataMapping):
        self.readARObject(element, mapping)
        mapping.setCommunicationDirection(cast(Optional[CommunicationDirectionType], self.getChildElementOptionalLiteral(element, "COMMUNICATION-DIRECTION")))
        for ref in self.getChildElementRefTypeList(element, "EVENT-GROUP-REFS/EVENT-GROUP-REF"):
            mapping.addEventGroupRef(ref)
        for ref in self.getChildElementRefTypeList(element, "EVENT-HANDLER-REFS/EVENT-HANDLER-REF"):
            mapping.addEventHandlerRef(ref)
        mapping.setIntroduction(self.getDocumentationBlock(element, "INTRODUCTION"))
        for ref in self.getChildElementRefTypeList(element, "SERVICE-INSTANCE-REFS/SERVICE-INSTANCE-REF"):
            mapping.addServiceInstanceRef(ref)
        variation_point_element = self.find(element, "VARIATION-POINT")
        if variation_point_element is not None:
            if isinstance(mapping, VariationPointCapable):
                mapping.setVariationPoint(self.readVariationPoint(variation_point_element, VariationPoint()))
            else:
                self.logger.warning("VARIATION-POINT on non-variant element <%s> ignored" % self.getPureTagName(element.tag))

    def readSenderReceiverToSignalMapping(self, element: ET.Element, mapping: SenderReceiverToSignalMapping):
        self.readDataMapping(element, mapping)
        mapping.setDataElementIRef(self.getVariableDataPrototypeInSystemInstanceRef(cast(ET.Element, self.find(element, "DATA-ELEMENT-IREF"))))
        sender_to_signal_element = self.find(element, "SENDER-TO-SIGNAL-TEXT-TABLE-MAPPING")
        if sender_to_signal_element is not None:
            mapping.setSenderToSignalTextTableMapping(self.getTextTableMapping(sender_to_signal_element))
        signal_to_receiver_element = self.find(element, "SIGNAL-TO-RECEIVER-TEXT-TABLE-MAPPING")
        if signal_to_receiver_element is not None:
            mapping.setSignalToReceiverTextTableMapping(self.getTextTableMapping(signal_to_receiver_element))
        mapping.setSystemSignalRef(self.getChildElementOptionalRefType(element, "SYSTEM-SIGNAL-REF"))

    def readSenderRecCompositeTypeMapping(self, element: ET.Element, mapping: SenderRecCompositeTypeMapping):
        self.readARObject(element, mapping)

    def readSenderRecRecordElementMapping(self, element: ET.Element, mapping: SenderRecRecordElementMapping):
        self.readARObject(element, mapping)
        mapping.setApplicationRecordElementRef(self.getChildElementOptionalRefType(element, "APPLICATION-RECORD-ELEMENT-REF"))
        complex_element = self.find(element, "COMPLEX-TYPE-MAPPING")
        if complex_element is not None:
            type_mapping_element = self.find(complex_element, "*")
            if type_mapping_element is not None:
                tag_name = self.getTagName(type_mapping_element)
                if tag_name == "SENDER-REC-ARRAY-TYPE-MAPPING":
                    type_mapping: ARObject = SenderRecArrayTypeMapping()
                    self.readSenderRecArrayTypeMapping(type_mapping_element, cast(SenderRecArrayTypeMapping, type_mapping))
                    mapping.setComplexTypeMapping(cast(Optional[SenderRecCompositeTypeMapping], type_mapping))
                elif tag_name == "SENDER-REC-RECORD-TYPE-MAPPING":
                    type_mapping = SenderRecRecordTypeMapping()
                    self.readSenderRecRecordTypeMapping(type_mapping_element, type_mapping)
                    mapping.setComplexTypeMapping(type_mapping)
                else:
                    self.notImplemented("Unsupported ComplexTypeMapping %s" % tag_name)
        mapping.setImplementationRecordElementRef(self.getChildElementOptionalRefType(element, "IMPLEMENTATION-RECORD-ELEMENT-REF"))
        sender_to_signal_element = self.find(element, "SENDER-TO-SIGNAL-TEXT-TABLE-MAPPING")
        if sender_to_signal_element is not None:
            mapping.setSenderToSignalTextTableMapping(self.getTextTableMapping(sender_to_signal_element))
        signal_to_receiver_element = self.find(element, "SIGNAL-TO-RECEIVER-TEXT-TABLE-MAPPING")
        if signal_to_receiver_element is not None:
            mapping.setSignalToReceiverTextTableMapping(self.getTextTableMapping(signal_to_receiver_element))
        mapping.setSystemSignalRef(self.getChildElementOptionalRefType(element, "SYSTEM-SIGNAL-REF"))

    def readIndexedArrayElement(self, element: ET.Element, indexed: IndexedArrayElement):
        self.readARObject(element, indexed)
        indexed.setApplicationArrayElementRef(self.getChildElementOptionalRefType(element, "APPLICATION-ARRAY-ELEMENT-REF"))
        indexed.setImplementationArrayElementRef(self.getChildElementOptionalRefType(element, "IMPLEMENTATION-ARRAY-ELEMENT-REF"))
        indexed.setIndex(self.getChildElementOptionalIntegerValue(element, "INDEX"))

    def readSenderRecArrayElementMapping(self, element: ET.Element, mapping: SenderRecArrayElementMapping):
        self.readARObject(element, mapping)
        complex_element = self.find(element, "COMPLEX-TYPE-MAPPING")
        if complex_element is not None:
            type_mapping_element = self.find(complex_element, "*")
            if type_mapping_element is not None:
                tag_name = self.getTagName(type_mapping_element)
                if tag_name == "SENDER-REC-ARRAY-TYPE-MAPPING":
                    type_mapping: ARObject = SenderRecArrayTypeMapping()
                    self.readSenderRecArrayTypeMapping(type_mapping_element, cast(SenderRecArrayTypeMapping, type_mapping))
                    mapping.setComplexTypeMapping(type_mapping)
                elif tag_name == "SENDER-REC-RECORD-TYPE-MAPPING":
                    type_mapping = SenderRecRecordTypeMapping()
                    self.readSenderRecRecordTypeMapping(type_mapping_element, type_mapping)
                    mapping.setComplexTypeMapping(type_mapping)
                else:
                    self.notImplemented("Unsupported ComplexTypeMapping %s" % tag_name)
        indexed_element = self.find(element, "INDEXED-ARRAY-ELEMENT")
        if indexed_element is not None:
            indexed = IndexedArrayElement()
            self.readIndexedArrayElement(indexed_element, indexed)
            mapping.setIndexedArrayElement(indexed)
        mapping.setSystemSignalRef(self.getChildElementOptionalRefType(element, "SYSTEM-SIGNAL-REF"))

    def readSenderRecArrayTypeMapping(self, element: ET.Element, mapping: SenderRecArrayTypeMapping):
        self.readSenderRecCompositeTypeMapping(element, mapping)
        for child_element in self.findall(element, "ARRAY-ELEMENT-MAPPINGS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "SENDER-REC-ARRAY-ELEMENT-MAPPING":
                array_element_mapping = SenderRecArrayElementMapping()
                self.readSenderRecArrayElementMapping(child_element, array_element_mapping)
                mapping.addArrayElementMapping(array_element_mapping)
            else:
                self.notImplemented("Unsupported ArrayElementMapping %s" % tag_name)
        sender_to_signal_element = self.find(element, "SENDER-TO-SIGNAL-TEXT-TABLE-MAPPING")
        if sender_to_signal_element is not None:
            mapping.setSenderToSignalTextTableMapping(self.getTextTableMapping(sender_to_signal_element))
        signal_to_receiver_element = self.find(element, "SIGNAL-TO-RECEIVER-TEXT-TABLE-MAPPING")
        if signal_to_receiver_element is not None:
            mapping.setSignalToReceiverTextTableMapping(self.getTextTableMapping(signal_to_receiver_element))

    def readSenderRecArrayTypeMappingRecordElementMapping(self, element: ET.Element, mapping: SenderRecRecordTypeMapping):
        for child_element in self.findall(element, "RECORD-ELEMENT-MAPPINGS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "SENDER-REC-RECORD-ELEMENT-MAPPING":
                record_element_mapping = SenderRecRecordElementMapping()
                self.readSenderRecRecordElementMapping(child_element, record_element_mapping)
                mapping.addRecordElementMapping(record_element_mapping)
            else:
                self.notImplemented("Unsupported RecordElementMapping %s" % tag_name)

    def readSenderRecRecordTypeMapping(self, element: ET.Element, mapping: SenderRecRecordTypeMapping):
        self.readSenderRecCompositeTypeMapping(element, mapping)
        self.readSenderRecArrayTypeMappingRecordElementMapping(element, mapping)

    def readSenderReceiverToSignalGroupMappingTypeMapping(self, element: ET.Element, mapping: SenderReceiverToSignalGroupMapping):
        child_element = self.find(element, "TYPE-MAPPING/*")
        if child_element is not None:
            tag_name = self.getTagName(child_element)
            if tag_name == "SENDER-REC-RECORD-TYPE-MAPPING":
                type_mapping: ARObject = SenderRecRecordTypeMapping()
                self.readSenderRecRecordTypeMapping(child_element, cast(SenderRecRecordTypeMapping, type_mapping))
                mapping.setTypeMapping(cast(Optional[SenderRecCompositeTypeMapping], type_mapping))
            elif tag_name == "SENDER-REC-ARRAY-TYPE-MAPPING":
                type_mapping = SenderRecArrayTypeMapping()
                self.readSenderRecArrayTypeMapping(child_element, type_mapping)
                mapping.setTypeMapping(type_mapping)
            else:
                self.notImplemented("Unsupported Type Mapping %s" % tag_name)

    def readSenderReceiverToSignalGroupMapping(self, element: ET.Element, mapping: SenderReceiverToSignalGroupMapping):
        self.readDataMapping(element, mapping)
        mapping.setDataElementIRef(self.getVariableDataPrototypeInSystemInstanceRef(cast(ET.Element, self.find(element, "DATA-ELEMENT-IREF"))))
        mapping.setSignalGroupRef(self.getChildElementOptionalRefType(element, "SIGNAL-GROUP-REF"))
        self.readSenderReceiverToSignalGroupMappingTypeMapping(element, mapping)

    def readSystemMappingDataMappings(self, element: ET.Element, mapping: SystemMapping):
        for child_element in self.findall(element, "DATA-MAPPINGS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "SENDER-RECEIVER-TO-SIGNAL-MAPPING":
                signal_mapping = SenderReceiverToSignalMapping()
                self.readSenderReceiverToSignalMapping(child_element, signal_mapping)
                mapping.addDataMapping(signal_mapping)
            elif tag_name == "SENDER-RECEIVER-TO-SIGNAL-GROUP-MAPPING":
                signal_group_mapping = SenderReceiverToSignalGroupMapping()
                self.readSenderReceiverToSignalGroupMapping(child_element, signal_group_mapping)
                mapping.addDataMapping(signal_group_mapping)
            else:
                self.notImplemented("Unsupported Data Mapping %s" % tag_name)

