    def readComManagementMapping(self, element: ET.Element, mapping: ComManagementMapping):
        self.readIdentifiable(element, mapping)
        for ref in self.getChildElementRefTypeList(element, "COM-MANAGEMENT-GROUP-REFS/COM-MANAGEMENT-GROUP-REF"):
            mapping.addComManagementGroupRef(ref)
        for iref_element in self.findall(element, "COM-MANAGEMENT-PORT-GROUP-IREFS/COM-MANAGEMENT-PORT-GROUP-IREF"):
            mapping.addComManagementPortGroupIRef(self.getPortGroupInSystemInstanceRef(iref_element))
        for ref in self.getChildElementRefTypeList(element, "PHYSICAL-CHANNEL-REFS/PHYSICAL-CHANNEL-REF"):
            mapping.addPhysicalChannelRef(ref)

    def readSystemMappingComManagementMappings(self, element: ET.Element, mapping: SystemMapping):
        for child_element in self.findall(element, "COM-MANAGEMENT-MAPPINGS/COM-MANAGEMENT-MAPPING"):
            com_mapping = mapping.createComManagementMapping(self.getShortName(child_element))
            self.readComManagementMapping(child_element, com_mapping)

    def readSystemMappingCryptoServiceMappings(self, element: ET.Element, mapping: SystemMapping):
        for child_element in self.findall(element, "CRYPTO-SERVICE-MAPPINGS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "SEC-OC-CRYPTO-SERVICE-MAPPING":
                crypto_mapping = mapping.createSecOcCryptoServiceMapping(self.getShortName(child_element))
                self.readSecOcCryptoServiceMapping(child_element, crypto_mapping)
            elif tag_name == "TLS-CRYPTO-SERVICE-MAPPING":
                self.readTlsCryptoServiceMapping(child_element, mapping.createTlsCryptoServiceMapping(self.getShortName(child_element)))
            else:
                self.notImplemented("Unsupported CryptoServiceMapping %s" % tag_name)

    def readCryptoEllipticCurveProps(self, element: ET.Element, props: CryptoEllipticCurveProps):
        self.logger.debug("Read CryptoEllipticCurveProps <%s>" % props.getShortName())
        self.readIdentifiable(element, props)
        props.setNamedCurveId(self.getChildElementOptionalPositiveInteger(element, "NAMED-CURVE-ID"))

    def readCryptoSignatureScheme(self, element: ET.Element, scheme: CryptoSignatureScheme):
        self.logger.debug("Read CryptoSignatureScheme <%s>" % scheme.getShortName())
        self.readIdentifiable(element, scheme)
        scheme.setSignatureSchemeId(self.getChildElementOptionalPositiveInteger(element, "SIGNATURE-SCHEME-ID"))

    def readIPSecRule(self, element: ET.Element, rule: IPSecRule):
        self.logger.debug("Read IPSecRule <%s>" % rule.getShortName())
        self.readIdentifiable(element, rule)
        literal = self.getChildElementOptionalLiteral(element, "DIRECTION")
        if literal is not None:
            e: ARLiteral = CommunicationDirectionType()
            e.setValue(literal.getValue())
            rule.setDirection(cast(Optional[CommunicationDirectionType], e))
        literal = self.getChildElementOptionalLiteral(element, "HEADER-TYPE")
        if literal is not None:
            e = IPsecHeaderTypeEnum()
            e.setValue(literal.getValue())
            rule.setHeaderType(cast(Optional[IPsecHeaderTypeEnum], e))
        literal = self.getChildElementOptionalLiteral(element, "IP-PROTOCOL")
        if literal is not None:
            e = IPsecIpProtocolEnum()
            e.setValue(literal.getValue())
            rule.setIpProtocol(cast(Optional[IPsecIpProtocolEnum], e))
        for ref in self.getChildElementRefTypeList(element, "LOCAL-CERTIFICATE-REFS/LOCAL-CERTIFICATE-REF"):
            rule.addLocalCertificateRef(ref)
        rule.setLocalId(self.getChildElementOptionalString(element, "LOCAL-ID"))
        rule.setLocalPortRangeEnd(self.getChildElementOptionalPositiveInteger(element, "LOCAL-PORT-RANGE-END"))
        rule.setLocalPortRangeStart(self.getChildElementOptionalPositiveInteger(element, "LOCAL-PORT-RANGE-START"))
        literal = self.getChildElementOptionalLiteral(element, "MODE")
        if literal is not None:
            e = IPsecModeEnum()
            e.setValue(literal.getValue())
            rule.setMode(cast(Optional[IPsecModeEnum], e))
        literal = self.getChildElementOptionalLiteral(element, "POLICY")
        if literal is not None:
            e = IPsecPolicyEnum()
            e.setValue(literal.getValue())
            rule.setPolicy(cast(Optional[IPsecPolicyEnum], e))
        rule.setPreSharedKeyRef(self.getChildElementOptionalRefType(element, "PRE-SHARED-KEY-REF"))
        rule.setPriority(self.getChildElementOptionalPositiveInteger(element, "PRIORITY"))
        for ref in self.getChildElementRefTypeList(element, "REMOTE-CERTIFICATE-REFS/REMOTE-CERTIFICATE-REF"):
            rule.addRemoteCertificateRef(ref)
        rule.setRemoteId(self.getChildElementOptionalString(element, "REMOTE-ID"))
        for ref in self.getChildElementRefTypeList(element, "REMOTE-IP-ADDRESS-REFS/REMOTE-IP-ADDRESS-REF"):
            rule.addRemoteIpAddressRef(ref)
        rule.setRemotePortRangeEnd(self.getChildElementOptionalPositiveInteger(element, "REMOTE-PORT-RANGE-END"))
        rule.setRemotePortRangeStart(self.getChildElementOptionalPositiveInteger(element, "REMOTE-PORT-RANGE-START"))

    def readIPSecConfigProps(self, element: ET.Element, props: IPSecConfigProps):
        self.logger.debug("Read IPSecConfigProps <%s>" % props.getShortName())
        self.readIdentifiable(element, props)
        wrapper = self.find(element, "AH-CIPHER-SUITE-NAMES")
        if wrapper is not None:
            for child_element in self.findall(wrapper, "AH-CIPHER-SUITE-NAME"):
                if child_element.text is not None:
                    value = String()
                    value.setValue(child_element.text)
                    props.addAhCipherSuiteName(value)
        literal = self.getChildElementOptionalLiteral(element, "DPD-ACTION")
        if literal is not None:
            e = IPsecDpdActionEnum()
            e.setValue(literal.getValue())
            props.setDpdAction(e)
        props.setDpdDelay(self.getChildElementOptionalTimeValue(element, "DPD-DELAY"))
        wrapper = self.find(element, "ESP-CIPHER-SUITE-NAMES")
        if wrapper is not None:
            for child_element in self.findall(wrapper, "ESP-CIPHER-SUITE-NAME"):
                if child_element.text is not None:
                    value = String()
                    value.setValue(child_element.text)
                    props.addEspCipherSuiteName(value)
        props.setIkeCipherSuiteName(self.getChildElementOptionalString(element, "IKE-CIPHER-SUITE-NAME"))
        props.setIkeOverTime(self.getChildElementOptionalTimeValue(element, "IKE-OVER-TIME"))
        props.setIkeRandTime(self.getChildElementOptionalPositiveInteger(element, "IKE-RAND-TIME"))
        props.setIkeReauthTime(self.getChildElementOptionalTimeValue(element, "IKE-REAUTH-TIME"))
        props.setIkeRekeyTime(self.getChildElementOptionalTimeValue(element, "IKE-REKEY-TIME"))
        props.setSaOverTime(self.getChildElementOptionalPositiveInteger(element, "SA-OVER-TIME"))
        props.setSaRandTime(self.getChildElementOptionalTimeValue(element, "SA-RAND-TIME"))
        props.setSaRekeyTime(self.getChildElementOptionalTimeValue(element, "SA-REKEY-TIME"))

    def readIPSecConfig(self, element: ET.Element, config: IPSecConfig):
        self.logger.debug("Read IPSecConfig")
        config.setIpSecConfigPropsRef(self.getChildElementOptionalRefType(element, "IP-SEC-CONFIG-PROPS-REF"))
        wrapper = self.find(element, "IP-SEC-RULES")
        if wrapper is not None:
            for child_element in self.findall(wrapper, "IP-SEC-RULE"):
                rule = config.createIPSecRule(self.getShortName(child_element))
                self.readIPSecRule(child_element, rule)

    def readCryptoServiceCertificate(self, element: ET.Element, certificate: CryptoServiceCertificate):
        self.logger.debug("Read CryptoServiceCertificate <%s>" % certificate.getShortName())
        self.readIdentifiable(element, certificate)
        family = self.getChildElementOptionalLiteral(element, "ALGORITHM-FAMILY")
        if family is not None:
            e: ARLiteral = CryptoCertificateAlgorithmFamilyEnum()
            e.setValue(family.getValue())
            certificate.setAlgorithmFamily(cast(Optional[CryptoCertificateAlgorithmFamilyEnum], e))
        fmt = self.getChildElementOptionalLiteral(element, "FORMAT")
        if fmt is not None:
            e = CryptoCertificateFormatEnum()
            e.setValue(fmt.getValue())
            certificate.setFormat(cast(Optional[CryptoCertificateFormatEnum], e))
        certificate.setMaximumLength(self.getChildElementOptionalPositiveInteger(element, "MAXIMUM-LENGTH"))
        certificate.setNextHigherCertificateRef(self.getChildElementOptionalRefType(element, "NEXT-HIGHER-CERTIFICATE-REF"))
        certificate.setServerNameIdentification(self.getChildElementOptionalString(element, "SERVER-NAME-IDENTIFICATION"))

    def readCryptoServicePrimitive(self, element: ET.Element, primitive: CryptoServicePrimitive):
        self.logger.debug("Read CryptoServicePrimitive <%s>" % primitive.getShortName())
        self.readIdentifiable(element, primitive)
        primitive.setAlgorithmFamily(self.getChildElementOptionalString(element, "ALGORITHM-FAMILY"))
        primitive.setAlgorithmMode(self.getChildElementOptionalString(element, "ALGORITHM-MODE"))
        primitive.setAlgorithmSecondaryFamily(self.getChildElementOptionalString(element, "ALGORITHM-SECONDARY-FAMILY"))

    def readSecOcCryptoServiceMapping(self, element: ET.Element, mapping: SecOcCryptoServiceMapping):
        self.readIdentifiable(element, mapping)
        ref = self.getChildElementOptionalRefType(element, "AUTHENTICATION-REF")
        if ref is not None:
            mapping.setAuthenticationRef(ref)
        ref = self.getChildElementOptionalRefType(element, "CRYPTO-SERVICE-KEY-REF")
        if ref is not None:
            mapping.setCryptoServiceKeyRef(ref)
        ref = self.getChildElementOptionalRefType(element, "CRYPTO-SERVICE-QUEUE-REF")
        if ref is not None:
            mapping.setCryptoServiceQueueRef(ref)

    def readTlsCryptoServiceMapping(self, element: ET.Element, mapping: TlsCryptoServiceMapping):
        self.readIdentifiable(element, mapping)
        for ref in self.getChildElementRefTypeList(element, "KEY-EXCHANGE-REFS/KEY-EXCHANGE-REF"):
            mapping.addKeyExchangeRef(ref)
        for suite_element in self.findall(element, "TLS-CIPHER-SUITES/TLS-CRYPTO-CIPHER-SUITE"):
            cipher_suite = TlsCryptoCipherSuite(mapping, self.getShortName(suite_element))
            mapping.addTlsCipherSuite(cipher_suite)
            self.readTlsCryptoCipherSuite(suite_element, cipher_suite)
        mapping.setUseClientAuthenticationRequest(self.getChildElementOptionalBooleanValue(element, "USE-CLIENT-AUTHENTICATION-REQUEST"))
        mapping.setUseSecurityExtensionRecordSizeLimit(self.getChildElementOptionalBooleanValue(element, "USE-SECURITY-EXTENSION-RECORD-SIZE-LIMIT"))

    def readTlsCryptoCipherSuite(self, element: ET.Element, cipher_suite: TlsCryptoCipherSuite):
        self.logger.debug("Read TlsCryptoCipherSuite <%s>" % cipher_suite.getShortName())
        self.readIdentifiable(element, cipher_suite)
        cipher_suite.setAuthenticationRef(self.getChildElementOptionalRefType(element, "AUTHENTICATION-REF"))
        cipher_suite.setCertificateRef(self.getChildElementOptionalRefType(element, "CERTIFICATE-REF"))
        cipher_suite.setCipherSuiteId(self.getChildElementOptionalPositiveInteger(element, "CIPHER-SUITE-ID"))
        cipher_suite.setCipherSuiteShortLabel(self.getChildElementOptionalString(element, "CIPHER-SUITE-SHORT-LABEL"))
        for ref in self.getChildElementRefTypeList(element, "ELLIPTIC-CURVE-REFS/ELLIPTIC-CURVE-REF"):
            cipher_suite.addEllipticCurveRef(ref)
        cipher_suite.setEncryptionRef(self.getChildElementOptionalRefType(element, "ENCRYPTION-REF"))
        for ref in self.getChildElementRefTypeList(element, "KEY-EXCHANGE-AUTHENTICATION-REFS/KEY-EXCHANGE-AUTHENTICATION-REF"):
            cipher_suite.addKeyExchangeAuthenticationRef(ref)
        for ref in self.getChildElementRefTypeList(element, "KEY-EXCHANGE-REFS/KEY-EXCHANGE-REF"):
            cipher_suite.addKeyExchangeRef(ref)
        cipher_suite.setPriority(self.getChildElementOptionalPositiveInteger(element, "PRIORITY"))
        props_element = self.find(element, "PROPS")
        if props_element is not None:
            props = TlsCryptoCipherSuiteProps(cipher_suite, self.getShortName(props_element))
            self.readTlsCryptoCipherSuiteProps(props_element, props)
            cipher_suite.setProps(props)
        psk_element = self.find(element, "PSK-IDENTITY")
        if psk_element is not None:
            psk_identity = TlsPskIdentity()
            self.readTlsPskIdentity(psk_element, psk_identity)
            cipher_suite.setPskIdentity(psk_identity)
        cipher_suite.setRemoteCertificateRef(self.getChildElementOptionalRefType(element, "REMOTE-CERTIFICATE-REF"))
        for ref in self.getChildElementRefTypeList(element, "SIGNATURE-SCHEME-REFS/SIGNATURE-SCHEME-REF"):
            cipher_suite.addSignatureSchemeRef(ref)
        literal = self.getChildElementOptionalLiteral(element, "VERSION")
        if literal is not None:
            e = TlsVersionEnum()
            e.setValue(literal.getValue())
            cipher_suite.setVersion(e)

    def readTlsPskIdentity(self, element: ET.Element, psk_identity: TlsPskIdentity):
        ref = self.getChildElementOptionalRefType(element, "PRE-SHARED-KEY-REF")
        if ref is not None:
            psk_identity.setPreSharedKeyRef(ref)
        psk_identity.setPskIdentity(self.getChildElementOptionalString(element, "PSK-IDENTITY"))
        psk_identity.setPskIdentityHint(self.getChildElementOptionalString(element, "PSK-IDENTITY-HINT"))

    def readTlsCryptoCipherSuiteProps(self, element: ET.Element, cipher_suite_props: TlsCryptoCipherSuiteProps):
        self.readIdentifiable(element, cipher_suite_props)
        cipher_suite_props.setTcpIpTlsUseSecurityExtensionForceEncryptThenMac(self.getChildElementOptionalBooleanValue(element, "TCP-IP-TLS-USE-SECURITY-EXTENSION-FORCE-ENCRYPT-THEN-MAC"))

    def readTlvDataIdDefinition(self, element: ET.Element, tlv_data_id_definition: TlvDataIdDefinition):
        tlv_data_id_definition.setId(self.getChildElementOptionalPositiveInteger(element, "ID"))
        tlv_data_id_definition.setTlvArgumentRef(self.getChildElementOptionalRefType(element, "TLV-ARGUMENT-REF"))
        tlv_data_id_definition.setTlvImplementationDataTypeElementRef(self.getChildElementOptionalRefType(element, "TLV-IMPLEMENTATION-DATA-TYPE-ELEMENT-REF"))
        tlv_data_id_definition.setTlvRecordElementRef(self.getChildElementOptionalRefType(element, "TLV-RECORD-ELEMENT-REF"))

    def readTlvDataIdDefinitionSetTlvDataIdDefinitions(self, element: ET.Element, tlv_data_id_definition_set: TlvDataIdDefinitionSet):
        for child_element in self.findall(element, "TLV-DATA-ID-DEFINITIONS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "TLV-DATA-ID-DEFINITION":
                tlv_data_id_definition = TlvDataIdDefinition()
                self.readTlvDataIdDefinition(child_element, tlv_data_id_definition)
                tlv_data_id_definition_set.addTlvDataIdDefinition(tlv_data_id_definition)
            else:
                self.notImplemented("Unsupported TlvDataIdDefinition <%s>" % tag_name)

    def readTlvDataIdDefinitionSet(self, element: ET.Element, tlv_data_id_definition_set: TlvDataIdDefinitionSet):
        self.logger.debug("Read TlvDataIdDefinitionSet <%s>" % tlv_data_id_definition_set.getShortName())
        self.readARElement(element, tlv_data_id_definition_set)
        self.readTlvDataIdDefinitionSetTlvDataIdDefinitions(element, tlv_data_id_definition_set)

    def readSystemMapping(self, element: ET.Element, mapping: SystemMapping):
        # self.logger.debug("Read SystemMapping <%s>" % mapping.getShortName())
        self.readIdentifiable(element, mapping)
        self.readSystemMappingAppOsTaskProxyToEcuTaskProxyMappings(element, mapping)
        self.readSystemMappingApplicationPartitionToEcuPartitionMappings(element, mapping)
        self.readSystemMappingComManagementMappings(element, mapping)
        self.readSystemMappingCryptoServiceMappings(element, mapping)
        self.readSystemMappingDataMappings(element, mapping)
        self.readSystemMappingEcuResourceMappings(element, mapping)
        self.readSystemMappingSwImplMappings(element, mapping)
        self.readSystemMappingSwMappings(element, mapping)

    def readSystemMappings(self, element: ET.Element, system: System):
        for child_element in self.findall(element, "MAPPINGS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "SYSTEM-MAPPING":
                mapping = system.createSystemMapping(self.getShortName(child_element))
                self.readSystemMapping(child_element, mapping)
            else:
                self.notImplemented("Unsupported Mapping %s" % tag_name)

    def readRootSwCompositionPrototype(self, element: ET.Element, system: System):
        child_element = self.find(element, "ROOT-SOFTWARE-COMPOSITIONS/ROOT-SW-COMPOSITION-PROTOTYPE")
        if child_element is not None:
            short_name = self.getShortName(child_element)
            self.logger.debug("Read RootSwCompositionPrototype %s" % short_name)
            prototype = system.createRootSoftwareComposition(short_name)
            self.readIdentifiable(child_element, prototype)
            for ref in self.getChildElementRefTypeList(child_element, "CALIBRATION-PARAMETER-VALUE-SET-REFS/CALIBRATION-PARAMETER-VALUE-SET-REF"):
                prototype.addCalibrationParameterValueSetRef(ref)
            prototype.setFlatMapRef(self.getChildElementOptionalRefType(child_element, "FLAT-MAP-REF"))
            prototype.setSoftwareCompositionTRef(cast(Optional[TRefType], self.getChildElementOptionalRefType(child_element, "SOFTWARE-COMPOSITION-TREF")))
            try:
                document = AUTOSAR.getInstance()
                document.setRootSwCompositionPrototype(prototype)
            except ValueError as e:
                self.raiseWarning("%s" % e)

    def readSystemFibexElementRefs(self, element: ET.Element, system: System):
        for ref in self.getChildElementRefTypeList(element, "FIBEX-ELEMENTS/FIBEX-ELEMENT-REF-CONDITIONAL/FIBEX-ELEMENT-REF"):
            system.addFibexElementRef(ref)

    def readSystemDocumentations(self, element: ET.Element, system: System):
        for chapter_element in self.findall(element, "SYSTEM-DOCUMENTATIONS/CHAPTER"):
            chapter = system.createSystemDocumentation(self.getShortName(chapter_element))
            self.readChapterBody(chapter_element, chapter)

    def readSystemClientIdDefinitionSetRefs(self, element: ET.Element, system: System):
        for ref in self.getChildElementRefTypeList(element, "CLIENT-ID-DEFINITION-SET-REFS/CLIENT-ID-DEFINITION-SET-REF"):
            system.addClientIdDefinitionSetRef(ref)

    def readClientIdDefinition(self, element: ET.Element, id_definition: ClientIdDefinition):
        self.readIdentifiable(element, id_definition)
        id_definition.setClientId(self.getChildElementOptionalNumerical(element, "CLIENT-ID"))
        id_definition.setClientServerOperationIRef(self.getOperationInSystemInstanceRef(cast(ET.Element, self.find(element, "CLIENT-SERVER-OPERATION-IREF"))))

    def readClientIdDefinitionSet(self, element: ET.Element, id_definition_set: ClientIdDefinitionSet):
        self.logger.debug("Read ClientIdDefinitionSet <%s>" % id_definition_set.getShortName())
        self.readARElement(element, id_definition_set)
        wrapper_element = self.find(element, "CLIENT-ID-DEFINITIONS")
        if wrapper_element is not None:
            for child_element in self.findall(wrapper_element, "CLIENT-ID-DEFINITION"):
                id_definition = id_definition_set.createClientIdDefinition(self.getShortName(child_element))
                self.readClientIdDefinition(child_element, id_definition)

    def readInterpolationRoutine(self, element: ET.Element, interpolation_routine: InterpolationRoutine):
        self.logger.debug("Read InterpolationRoutine")
        interpolation_routine.setShortLabel(cast(Optional[Identifier], self.getChildElementOptionalLiteral(element, "SHORT-LABEL")))
        interpolation_routine.setIsDefault(self.getChildElementOptionalBooleanValue(element, "IS-DEFAULT"))
        interpolation_routine.setInterpolationRoutineRef(self.getChildElementOptionalRefType(element, "INTERPOLATION-ROUTINE-REF"))

    def readInterpolationRoutineMapping(self, element: ET.Element, mapping: InterpolationRoutineMapping):
        self.logger.debug("Read InterpolationRoutineMapping")
        wrapper_element = self.find(element, "INTERPOLATION-ROUTINES")
        if wrapper_element is not None:
            for child_element in self.findall(wrapper_element, "INTERPOLATION-ROUTINE"):
                routine = mapping.createInterpolationRoutine()
                self.readInterpolationRoutine(child_element, routine)
        mapping.setSwRecordLayoutRef(self.getChildElementOptionalRefType(element, "SW-RECORD-LAYOUT-REF"))

    def readInterpolationRoutineMappingSet(self, element: ET.Element, mapping_set: InterpolationRoutineMappingSet):
        self.logger.debug("Read InterpolationRoutineMappingSet <%s>" % mapping_set.getShortName())
        self.readARElement(element, mapping_set)
        wrapper_element = self.find(element, "INTERPOLATION-ROUTINE-MAPPINGS")
        if wrapper_element is not None:
            for child_element in self.findall(wrapper_element, "INTERPOLATION-ROUTINE-MAPPING"):
                mapping = mapping_set.createInterpolationRoutineMapping()
                self.readInterpolationRoutineMapping(child_element, mapping)

    def readSwComponentPrototypeAssignment(self, element: ET.Element, assignment: SwComponentPrototypeAssignment):
        self.readARObject(element, assignment)
        assignment.setSwComponentIRef(self.getComponentInSystemInstanceRef(cast(ET.Element, self.find(element, "SW-COMPONENT-IREF"))))
        variation_point_element = self.find(element, "VARIATION-POINT")
        if variation_point_element is not None:
            if isinstance(assignment, VariationPointCapable):
                assignment.setVariationPoint(self.readVariationPoint(variation_point_element, VariationPoint()))
            else:
                self.logger.warning("VARIATION-POINT on non-variant element <%s> ignored" % self.getPureTagName(element.tag))

    def readCpSoftwareCluster(self, element: ET.Element, cluster: CpSoftwareCluster):
        self.readARElement(element, cluster)
        cluster.setSoftwareClusterId(self.getChildElementOptionalPositiveInteger(element, "SOFTWARE-CLUSTER-ID"))
        for child_element in self.findall(element, "SW-COMPONENT-ASSIGNMENTS/SW-COMPONENT-PROTOTYPE-ASSIGNMENT"):
            assignment = cluster.createSwComponentAssignment()
            self.readSwComponentPrototypeAssignment(child_element, assignment)
        for ref in self.getChildElementRefTypeList(element, "SW-COMPOSITIONS/COMPOSITION-SW-COMPONENT-TYPE-REF-CONDITIONAL/COMPOSITION-SW-COMPONENT-TYPE-REF"):
            cluster.addSwCompositionRef(ref)

    def readSystemInterpolationRoutineMappingSetRefs(self, element: ET.Element, system: System):
        for ref in self.getChildElementRefTypeList(element, "INTERPOLATION-ROUTINE-MAPPING-SET-REFS/INTERPOLATION-ROUTINE-MAPPING-SET-REF"):
            system.addInterpolationRoutineMappingSetRef(ref)

    def readJ1939SharedAddressCluster(self, element: ET.Element, cluster: J1939SharedAddressCluster):
        self.readIdentifiable(element, cluster)
        for ref in self.getChildElementRefTypeList(element, "PARTICIPATING-J-1939-CLUSTER-REFS/PARTICIPATING-J-1939-CLUSTER-REF"):
            cluster.addParticipatingJ1939ClusterRef(ref)

    def readSystemJ1939SharedAddressClusters(self, element: ET.Element, system: System):
        for child_element in self.findall(element, "J-1939-SHARED-ADDRESS-CLUSTERS/J-1939-SHARED-ADDRESS-CLUSTER"):
            cluster = system.createJ1939SharedAddressCluster(self.getShortName(child_element))
            self.readJ1939SharedAddressCluster(child_element, cluster)

    def readSystemSwClusterRefs(self, element: ET.Element, system: System):
        for ref in self.getChildElementRefTypeList(element, "SW-CLUSTERS/CP-SOFTWARE-CLUSTER-REF-CONDITIONAL/CP-SOFTWARE-CLUSTER-REF"):
            system.addSwClusterRef(ref)

    def readSystem(self, element: ET.Element, system: System):
        self.logger.debug("Read System <%s>" % system.getShortName())
        self.readIdentifiable(element, system)
        self.readSystemDocumentations(element, system)
        self.readSystemClientIdDefinitionSetRefs(element, system)
        system.setContainerIPduHeaderByteOrder(cast(Optional[ByteOrderEnum], self.getChildElementOptionalLiteral(element, "CONTAINER-I-PDU-HEADER-BYTE-ORDER")))
        system.setEcuExtractVersion(self.getChildElementOptionalRevisionLabelString(element, "ECU-EXTRACT-VERSION"))
        self.readSystemFibexElementRefs(element, system)
        self.readSystemInterpolationRoutineMappingSetRefs(element, system)
        self.readSystemJ1939SharedAddressClusters(element, system)
        self.readSystemMappings(element, system)
        system.setPncVectorLength(self.getChildElementOptionalPositiveInteger(element, "PNC-VECTOR-LENGTH"))
        system.setPncVectorOffset(self.getChildElementOptionalPositiveInteger(element, "PNC-VECTOR-OFFSET"))
        self.readRootSwCompositionPrototype(element, system)
        self.readSystemSwClusterRefs(element, system)
        system.setSystemVersion(self.getChildElementOptionalRevisionLabelString(element, "SYSTEM-VERSION"))
        document = AUTOSAR.getInstance()
        document.addSystem(system)

    def readGenericEthernetFrame(self, element: ET.Element, frame: GenericEthernetFrame):
        self.logger.debug("Read GenericEthernetFrame <%s>" % frame.getShortName())
        self.readFrame(element, frame)

    def getLifeCyclePeriod(self, element: ET.Element, key: str) -> Optional[LifeCyclePeriod]:
        child_element = self.find(element, key)
        period = None
        if child_element is not None:
            period = LifeCyclePeriod()
            period.setDate(self.getChildElementOptionalDateTime(child_element, "DATE"))
            period.setArReleaseVersion(self.getChildElementOptionalRevisionLabelString(child_element, "AR-RELEASE-VERSION"))
            period.setProductRelease(self.getChildElementOptionalRevisionLabelString(child_element, "PRODUCT-RELEASE"))
        return period

    def readLifeCycleInfoUseInsteadRefs(self, element: ET.Element, info: LifeCycleInfo):
        for ref in self.getChildElementRefTypeList(element, "USE-INSTEAD-REFS/USE-INSTEAD-REF"):
            info.addUseInsteadRef(ref)

    def readLifeCycleInfo(self, element: ET.Element, info: LifeCycleInfo):
        self.readARObject(element, info)
        info.setLcObjectRef(self.getChildElementOptionalRefType(element, "LC-OBJECT-REF"))
        info.setLcStateRef(self.getChildElementOptionalRefType(element, "LC-STATE-REF"))
        info.setPeriodBegin(self.getLifeCyclePeriod(element, "PERIOD-BEGIN"))
        info.setPeriodEnd(self.getLifeCyclePeriod(element, "PERIOD-END"))
        info.setRemark(self.getDocumentationBlock(element, "REMARK"))
        self.readLifeCycleInfoUseInsteadRefs(element, info)

    def readLifeCycleInfoSetLifeCycleInfos(self, element: ET.Element, info_set: LifeCycleInfoSet):
        for child_element in self.findall(element, "LIFE-CYCLE-INFOS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "LIFE-CYCLE-INFO":
                info = LifeCycleInfo()
                self.readLifeCycleInfo(child_element, info)
                info_set.addLifeCycleInfo(info)
            else:
                self.notImplemented("Unsupported Life Cycle Info <%s>" % tag_name)

    def readLifeCycleInfoSet(self, element: ET.Element, info_set: LifeCycleInfoSet):
        self.logger.debug("Read LifeCycleInfoSet <%s>" % info_set.getShortName())
        self.readIdentifiable(element, info_set)
        info_set.setDefaultLcStateRef(self.getChildElementOptionalRefType(element, "DEFAULT-LC-STATE-REF"))
        info_set.setDefaultPeriodBegin(self.getLifeCyclePeriod(element, "DEFAULT-PERIOD-BEGIN"))
        info_set.setDefaultPeriodEnd(self.getLifeCyclePeriod(element, "DEFAULT-PERIOD-END"))
        self.readLifeCycleInfoSetLifeCycleInfos(element, info_set)
        info_set.setUsedLifeCycleStateDefinitionGroupRef(self.getChildElementOptionalRefType(element, "USED-LIFE-CYCLE-STATE-DEFINITION-GROUP-REF"))

    def readFlatInstanceDescriptor(self, element: ET.Element, desc: FlatInstanceDescriptor):
        self.logger.debug("Read FlatInstanceDescriptor %s" % desc.getShortName())
        self.readIdentifiable(element, desc)
        desc.setRole(self.getChildElementOptionalIdentifier(element, "ROLE"))
        rte_plugin_props_element = self.find(element, "RTE-PLUGIN-PROPS")
        if rte_plugin_props_element is not None:
            rte_plugin_props = RtePluginProps()
            self.readRtePluginProps(rte_plugin_props_element, rte_plugin_props)
            desc.setRtePluginProps(rte_plugin_props)
        desc.setSwDataDefProps(self.getSwDataDefProps(element, "SW-DATA-DEF-PROPS"))
        desc.setUpstreamReferenceIRef(self.getAnyInstanceRef(element, "UPSTREAM-REFERENCE-IREF"))
        desc.setEcuExtractReferenceIRef(self.getAnyInstanceRef(element, "ECU-EXTRACT-REFERENCE-IREF"))

    def readRtePluginProps(self, element: ET.Element, props: RtePluginProps):
        self.logger.debug("Read RtePluginProps")
        props.setAssociatedCrossSwClusterComRtePluginRef(self.getChildElementOptionalRefType(element, "ASSOCIATED-CROSS-SW-CLUSTER-COM-RTE-PLUGIN-REF"))
        props.setAssociatedRtePluginRef(self.getChildElementOptionalRefType(element, "ASSOCIATED-RTE-PLUGIN-REF"))

    def readFlatMapInstances(self, element: ET.Element, map: FlatMap):
        for child_element in self.findall(element, "INSTANCES/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "FLAT-INSTANCE-DESCRIPTOR":
                desc = map.createFlatInstanceDescriptor(self.getShortName(child_element))
                self.readFlatInstanceDescriptor(child_element, desc)
            else:
                self.notImplemented("Unsupported Flat Map Instances <%s>" % tag_name)

    def readFlatMap(self, element: ET.Element, map: FlatMap):
        self.logger.debug("Read FlatMap <%s>" % map.getShortName())
        self.readIdentifiable(element, map)
        self.readFlatMapInstances(element, map)

    def getDataPrototypeMappings(self, element: ET.Element, key: str) -> List[DataPrototypeMapping]:
        mappings = []
        for child_element in self.findall(element, "%s/DATA-PROTOTYPE-MAPPING" % key):
            mapping = DataPrototypeMapping()
            mapping.setFirstDataPrototypeRef(self.getChildElementOptionalRefType(child_element, "FIRST-DATA-PROTOTYPE-REF"))
            mapping.setFirstToSecondDataTransformationRef(self.getChildElementOptionalRefType(child_element, "FIRST-TO-SECOND-DATA-TRANSFORMATION-REF"))
            mapping.setSecondDataPrototypeRef(self.getChildElementOptionalRefType(child_element, "SECOND-DATA-PROTOTYPE-REF"))
            mapping.setSecondToFirstDataTransformationRef(self.getChildElementOptionalRefType(child_element, "SECOND-TO-FIRST-DATA-TRANSFORMATION-REF"))
            for sub_element in self.findall(child_element, "SUB-ELEMENT-MAPPINGS/SUB-ELEMENT-MAPPING"):
                mapping.addSubElementMapping(self.getSubElementMapping(sub_element))
            for text_table in self.findall(child_element, "TEXT-TABLE-MAPPINGS/TEXT-TABLE-MAPPING"):
                mapping.addTextTableMapping(self.getTextTableMapping(text_table))
            mappings.append(mapping)
        return mappings

    def getImplementationDataTypeSubElementRef(self, element: ET.Element) -> ImplementationDataTypeSubElementRef:
        sub_element_ref = ImplementationDataTypeSubElementRef()
        for impl_element in self.findall(element, "IMPLEMENTATION-DATA-TYPE-ELEMENT"):
            iref = ArVariableInImplementationDataInstanceRef()
            iref.setPortPrototypeRef(self.getChildElementOptionalRefType(impl_element, "PORT-PROTOTYPE-REF"))
            iref.setRootVariableDataPrototypeRef(self.getChildElementOptionalRefType(impl_element, "ROOT-VARIABLE-DATA-PROTOTYPE-REF"))
            for ref in self.getChildElementRefTypeList(impl_element, "CONTEXT-DATA-PROTOTYPE-REFS/CONTEXT-DATA-PROTOTYPE-REF"):
                iref.addContextDataPrototypeRef(ref)
            iref.setTargetDataPrototypeRef(self.getChildElementOptionalRefType(impl_element, "TARGET-DATA-PROTOTYPE-REF"))
            sub_element_ref.setImplementationDataTypeElement(iref)
        for param_element in self.findall(element, "PARAMETER-IMPLEMENTATION-DATA-TYPE-ELEMENT"):
            param_iref = ArParameterInImplementationDataInstanceRef()
            param_iref.setPortPrototypeRef(self.getChildElementOptionalRefType(param_element, "PORT-PROTOTYPE-REF"))
            param_iref.setRootParameterDataPrototypeRef(self.getChildElementOptionalRefType(param_element, "ROOT-PARAMETER-DATA-PROTOTYPE-REF"))
            for ref in self.getChildElementRefTypeList(param_element, "CONTEXT-DATA-PROTOTYPE-REFS/CONTEXT-DATA-PROTOTYPE-REF"):
                param_iref.addContextDataPrototypeRef(ref)
            param_iref.setTargetDataPrototypeRef(self.getChildElementOptionalRefType(param_element, "TARGET-DATA-PROTOTYPE-REF"))
            sub_element_ref.setParameterImplementationDataTypeElement(param_iref)
        return sub_element_ref

    def getSubElementMapping(self, element: ET.Element) -> SubElementMapping:
        mapping = SubElementMapping()
        for ref_element in self.findall(element, "FIRST-ELEMENTS/*"):
            if self.getTagName(ref_element) == "APPLICATION-COMPOSITE-DATA-TYPE-SUB-ELEMENT-REF":
                mapping.setFirstElement(self.getApplicationCompositeDataTypeSubElementRef(ref_element))
            elif self.getTagName(ref_element) == "IMPLEMENTATION-DATA-TYPE-SUB-ELEMENT-REF":
                mapping.setFirstElement(self.getImplementationDataTypeSubElementRef(ref_element))
            else:
                self.notImplemented("Unsupported firstElement SubElementRef <%s>" % self.getTagName(ref_element))
        for ref_element in self.findall(element, "SECOND-ELEMENTS/*"):
            if self.getTagName(ref_element) == "APPLICATION-COMPOSITE-DATA-TYPE-SUB-ELEMENT-REF":
                mapping.setSecondElement(self.getApplicationCompositeDataTypeSubElementRef(ref_element))
            elif self.getTagName(ref_element) == "IMPLEMENTATION-DATA-TYPE-SUB-ELEMENT-REF":
                mapping.setSecondElement(self.getImplementationDataTypeSubElementRef(ref_element))
            else:
                self.notImplemented("Unsupported secondElement SubElementRef <%s>" % self.getTagName(ref_element))
        for text_table in self.findall(element, "TEXT-TABLE-MAPPINGS/TEXT-TABLE-MAPPING"):
            mapping.addTextTableMapping(self.getTextTableMapping(text_table))
        return mapping

    def getApplicationCompositeDataTypeSubElementRef(self, element: ET.Element) -> ApplicationCompositeDataTypeSubElementRef:
        sub_element_ref = ApplicationCompositeDataTypeSubElementRef()
        sub_element_ref.setApplicationCompositeElementIRef(self.getApplicationCompositeElementInPortInterfaceInstanceRef(element, "APPLICATION-COMPOSITE-ELEMENT-IREF"))
        return sub_element_ref

    def getTextTableMapping(self, element: ET.Element) -> TextTableMapping:
        mapping = TextTableMapping()
        mapping.setBitfieldTextTableMaskFirst(self.getChildElementOptionalPositiveInteger(element, "BITFIELD-TEXT-TABLE-MASK-FIRST"))
        mapping.setBitfieldTextTableMaskSecond(self.getChildElementOptionalPositiveInteger(element, "BITFIELD-TEXT-TABLE-MASK-SECOND"))
        mapping.setIdenticalMapping(self.getChildElementOptionalBooleanValue(element, "IDENTICAL-MAPPING"))
        mapping.setMappingDirection(cast(Optional[MappingDirectionEnum], self.getChildElementOptionalLiteral(element, "MAPPING-DIRECTION")))
        for pair_element in self.findall(element, "VALUE-PAIRS/TEXT-TABLE-VALUE-PAIR"):
            mapping.addValuePair(self.getTextTableValuePair(pair_element))
        return mapping

    def getTextTableValuePair(self, element: ET.Element) -> TextTableValuePair:
        value_pair = TextTableValuePair()
        value_pair.setFirstValue(self.getChildElementOptionalNumerical(element, "FIRST-VALUE"))
        value_pair.setSecondValue(self.getChildElementOptionalNumerical(element, "SECOND-VALUE"))
        return value_pair

    def readVariableAndParameterInterfaceMapping(self, element: ET.Element, mapping: VariableAndParameterInterfaceMapping):
        # self.logger.debug("Read VariableAndParameterInterfaceMapping %s" % mapping.getShortName())
        self.readIdentifiable(element, mapping)
        for item in self.getDataPrototypeMappings(element, "DATA-MAPPINGS"):
            mapping.addDataMapping(item)

    def readClientServerOperationMapping(self, element: ET.Element, mapping: ClientServerOperationMapping):
        for item in self.getDataPrototypeMappings(element, "ARGUMENT-MAPPINGS"):
            mapping.addArgumentMapping(item)
        mapping.setFirstOperationRef(self.getChildElementOptionalRefType(element, "FIRST-OPERATION-REF"))
        mapping.setFirstToSecondDataTransformationRef(self.getChildElementOptionalRefType(element, "FIRST-TO-SECOND-DATA-TRANSFORMATION-REF"))
        mapping.setSecondOperationRef(self.getChildElementOptionalRefType(element, "SECOND-OPERATION-REF"))

    def readClientServerApplicationErrorMapping(self, element: ET.Element, mapping: ClientServerApplicationErrorMapping):
        mapping.setFirstApplicationErrorRef(self.getChildElementOptionalRefType(element, "FIRST-APPLICATION-ERROR-REF"))
        mapping.setSecondApplicationErrorRef(self.getChildElementOptionalRefType(element, "SECOND-APPLICATION-ERROR-REF"))

    def readClientServerInterfaceMappingErrorMappings(self, element: ET.Element, mapping: ClientServerInterfaceMapping):
        for child_element in self.findall(element, "ERROR-MAPPINGS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "CLIENT-SERVER-APPLICATION-ERROR-MAPPING":
                error_mapping = ClientServerApplicationErrorMapping()
                self.readClientServerApplicationErrorMapping(child_element, error_mapping)
                mapping.addErrorMapping(error_mapping)
            else:
                self.notImplemented("Unsupported Error Mapping <%s>" % tag_name)

    def readClientServerInterfaceMappingOperationMappings(self, element: ET.Element, mapping: ClientServerInterfaceMapping):
        for child_element in self.findall(element, "OPERATION-MAPPINGS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "CLIENT-SERVER-OPERATION-MAPPING":
                operation_mapping = ClientServerOperationMapping()
                self.readClientServerOperationMapping(child_element, operation_mapping)
                mapping.addOperationMapping(operation_mapping)
            else:
                self.notImplemented("Unsupported Operation Mapping <%s>" % tag_name)

    def readClientServerInterfaceMapping(self, element: ET.Element, mapping: ClientServerInterfaceMapping):
        # self.logger.debug("Read ClientServerInterfaceMapping %s" % mapping.getShortName())
        self.readIdentifiable(element, mapping)
        self.readClientServerInterfaceMappingErrorMappings(element, mapping)
        self.readClientServerInterfaceMappingOperationMappings(element, mapping)

    def readModeInterfaceMappingModeMapping(self, element: ET.Element, mapping: ModeInterfaceMapping):
        child_element = self.find(element, "MODE-MAPPING")
        if child_element is not None:
            mode_mapping = ModeDeclarationGroupPrototypeMapping()
            mode_mapping.setFirstModeGroupRef(self.getChildElementOptionalRefType(child_element, "FIRST-MODE-GROUP-REF"))
            mode_mapping.setModeDeclarationMappingSetRef(self.getChildElementOptionalRefType(child_element, "MODE-DECLARATION-MAPPING-SET-REF"))
            mode_mapping.setSecondModeGroupRef(self.getChildElementOptionalRefType(child_element, "SECOND-MODE-GROUP-REF"))
            mapping.setModeMapping(mode_mapping)

    def readModeInterfaceMapping(self, element: ET.Element, mapping: ModeInterfaceMapping):
        # self.logger.debug("Read ModeInterfaceMapping %s" % mapping.getShortName())
        self.readIdentifiable(element, mapping)
        self.readModeInterfaceMappingModeMapping(element, mapping)

    def readField(self, element: ET.Element, field: Field):
        self.readIdentifiable(element, field)
        field.setHasGetter(self.getChildElementOptionalBooleanValue(element, "HAS-GETTER"))
        field.setHasNotifier(self.getChildElementOptionalBooleanValue(element, "HAS-NOTIFIER"))
        field.setHasSetter(self.getChildElementOptionalBooleanValue(element, "HAS-SETTER"))

    def readTriggerMapping(self, element: ET.Element, trigger_mapping: TriggerMapping):
        trigger_mapping.setFirstTriggerRef(self.getChildElementOptionalRefType(element, "FIRST-TRIGGER-REF"))
        trigger_mapping.setSecondTriggerRef(self.getChildElementOptionalRefType(element, "SECOND-TRIGGER-REF"))

    def readTriggerInterfaceMappingTriggerMappings(self, element: ET.Element, mapping: TriggerInterfaceMapping):
        for child_element in self.findall(element, "TRIGGER-MAPPINGS/TRIGGER-MAPPING"):
            trigger_mapping = TriggerMapping()
            self.readTriggerMapping(child_element, trigger_mapping)
            mapping.addTriggerMapping(trigger_mapping)

    def readTriggerInterfaceMapping(self, element: ET.Element, mapping: TriggerInterfaceMapping):
        # self.logger.debug("Read TriggerInterfaceMapping %s" % mapping.getShortName())
        self.readIdentifiable(element, mapping)
        self.readTriggerInterfaceMappingTriggerMappings(element, mapping)

    def readPortInterfaceMappings(self, element: ET.Element, mapping_set: PortInterfaceMappingSet):
        for child_element in self.findall(element, "PORT-INTERFACE-MAPPINGS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "VARIABLE-AND-PARAMETER-INTERFACE-MAPPING":
                mapping = mapping_set.createVariableAndParameterInterfaceMapping(self.getShortName(child_element))
                self.readVariableAndParameterInterfaceMapping(child_element, mapping)
            elif tag_name == "CLIENT-SERVER-INTERFACE-MAPPING":
                self.readClientServerInterfaceMapping(child_element, mapping_set.createClientServerInterfaceMapping(self.getShortName(child_element)))
            elif tag_name == "MODE-INTERFACE-MAPPING":
                self.readModeInterfaceMapping(child_element, mapping_set.createModeInterfaceMapping(self.getShortName(child_element)))
            elif tag_name == "TRIGGER-INTERFACE-MAPPING":
                self.readTriggerInterfaceMapping(child_element, mapping_set.createTriggerInterfaceMapping(self.getShortName(child_element)))
            else:
                self.notImplemented("Unsupported PortInterfaceMapping <%s>" % tag_name)

    def readPortInterfaceMappingSet(self, element: ET.Element, mapping_set: PortInterfaceMappingSet):
        self.logger.debug("Read PortInterfaceMappingSet %s" % mapping_set.getShortName())
        self.readIdentifiable(element, mapping_set)
        self.readPortInterfaceMappings(element, mapping_set)

    def readApplicationInterface(self, element: ET.Element, interface: ApplicationInterface):
        self.readIdentifiable(element, interface)
        fields = []
        for child_element in self.findall(element, "ATTRIBUTES/FIELD"):
            field = Field(interface, self.getShortName(child_element))
            self.readField(child_element, field)
            fields.append(field)
        if len(fields) > 0:
            interface.setAttributes(fields)
        operations = []
        for child_element in self.findall(element, "COMMANDS/CLIENT-SERVER-OPERATION"):
            operation = ClientServerOperation(interface, self.getShortName(child_element))
            self.readClientServerOperation(child_element, operation)
            operations.append(operation)
        if len(operations) > 0:
            interface.setCommands(operations)
        indications = []
        for child_element in self.findall(element, "INDICATIONS/VARIABLE-DATA-PROTOTYPE"):
            indication = VariableDataPrototype(interface, self.getShortName(child_element))
            self.readVariableDataPrototype(child_element, indication)
            indications.append(indication)
        if len(indications) > 0:
            interface.setIndications(indications)

    def readAliasNameAssignment(self, element: ET.Element, assignment: AliasNameAssignment):
        assignment.setShortLabel(self.getChildElementOptionalString(element, "SHORT-LABEL"))
        assignment.setLabel(self.getMultilanguageLongName(element, "LABEL"))
        assignment.setIdentifiableRef(self.getChildElementOptionalRefType(element, "IDENTIFIABLE-REF"))
        assignment.setFlatInstanceRef(self.getChildElementOptionalRefType(element, "FLAT-INSTANCE-REF"))

    def readAliasNameSet(self, element: ET.Element, alias_set: AliasNameSet):
        self.readIdentifiable(element, alias_set)
        for child_element in self.findall(element, "ALIAS-NAME-ASSIGNMENT"):
            assignment = AliasNameAssignment()
            alias_set.addAliasName(assignment)
            self.readAliasNameAssignment(child_element, assignment)

