    def readDataLinkLayerRule(self, element: ET.Element, rule: DataLinkLayerRule):
        self.readARObject(element, rule)
        destination_mac = self.getChildElementOptionalLiteral(element, "DESTINATION-MAC-ADDRESS")
        if destination_mac is not None:
            mac_address = MacAddressString()
            mac_address.setValue(destination_mac.getValue())
            rule.setDestinationMacAddress(mac_address)
        destination_mac_mask = self.getChildElementOptionalLiteral(element, "DESTINATION-MAC-ADDRESS-MASK")
        if destination_mac_mask is not None:
            mac_address = MacAddressString()
            mac_address.setValue(destination_mac_mask.getValue())
            rule.setDestinationMacAddressMask(mac_address)
        rule.setEtherType(self.getChildElementOptionalPositiveInteger(element, "ETHER-TYPE"))
        source_mac = self.getChildElementOptionalLiteral(element, "SOURCE-MAC-ADDRESS")
        if source_mac is not None:
            mac_address = MacAddressString()
            mac_address.setValue(source_mac.getValue())
            rule.setSourceMacAddress(mac_address)
        source_mac_mask = self.getChildElementOptionalLiteral(element, "SOURCE-MAC-ADDRESS-MASK")
        if source_mac_mask is not None:
            mac_address = MacAddressString()
            mac_address.setValue(source_mac_mask.getValue())
            rule.setSourceMacAddressMask(mac_address)
        rule.setVlanId(self.getChildElementOptionalPositiveInteger(element, "VLAN-ID"))
        rule.setVlanPriority(self.getChildElementOptionalPositiveInteger(element, "VLAN-PRIORITY"))

    def readPayloadBytePatternRule(self, element: ET.Element, payload_rule: PayloadBytePatternRule):
        self.readARObject(element, payload_rule)
        parts = self.find(element, "PAYLOAD-BYTE-PATTERN-RULE-PARTS")
        if parts is not None:
            for child in self.findall(parts, "PAYLOAD-BYTE-PATTERN-RULE-PART"):
                part = PayloadBytePatternRulePart()
                self.readPayloadBytePatternRulePart(child, part)
                payload_rule.addPayloadBytePatternRulePart(part)

    def readPayloadBytePatternRulePart(self, element: ET.Element, part: PayloadBytePatternRulePart):
        self.readARObject(element, part)
        part.setOffset(self.getChildElementOptionalPositiveInteger(element, "OFFSET"))
        part.setValue(self.getChildElementOptionalPositiveInteger(element, "VALUE"))

    def readSomeipProtocolRule(self, element: ET.Element, rule: SomeipProtocolRule):
        self.readARObject(element, rule)
        rule.setClientId(self.getChildElementOptionalPositiveInteger(element, "CLIENT-ID"))
        rule.setLengthVerification(self.getChildElementOptionalBooleanValue(element, "LENGTH-VERIFICATION"))
        rule.setMajorVersion(self.getChildElementOptionalPositiveInteger(element, "MAJOR-VERSION"))
        rule.setMessageType(self.getChildElementOptionalPositiveInteger(element, "MESSAGE-TYPE"))
        rule.setMethodId(self.getChildElementOptionalPositiveInteger(element, "METHOD-ID"))
        rule.setProtocolVersion(self.getChildElementOptionalPositiveInteger(element, "PROTOCOL-VERSION"))
        rule.setReturnCode(self.getChildElementOptionalPositiveInteger(element, "RETURN-CODE"))
        rule.setServiceInterfaceId(self.getChildElementOptionalPositiveInteger(element, "SERVICE-INTERFACE-ID"))

    def readSomeipSdRule(self, element: ET.Element, rule: SomeipSdRule):
        self.readARObject(element, rule)
        rule.setEntryType(self.getChildElementOptionalPositiveInteger(element, "ENTRY-TYPE"))
        rule.setEventGroupId(self.getChildElementOptionalPositiveInteger(element, "EVENT-GROUP-ID"))
        rule.setMaxMajorVersion(self.getChildElementOptionalPositiveInteger(element, "MAX-MAJOR-VERSION"))
        rule.setMaxMinorVersion(self.getChildElementOptionalPositiveInteger(element, "MAX-MINOR-VERSION"))
        rule.setMinMajorVersion(self.getChildElementOptionalPositiveInteger(element, "MIN-MAJOR-VERSION"))
        rule.setMinMinorVersion(self.getChildElementOptionalPositiveInteger(element, "MIN-MINOR-VERSION"))
        rule.setServiceInstanceId(self.getChildElementOptionalPositiveInteger(element, "SERVICE-INSTANCE-ID"))
        rule.setServiceInterfaceId(self.getChildElementOptionalPositiveInteger(element, "SERVICE-INTERFACE-ID"))

    def readDoIpRule(self, element: ET.Element, rule: DoIpRule):
        rule.setDestinationMaxAddress(self.getChildElementOptionalPositiveInteger(element, "DESTINATION-MAX-ADDRESS"))
        rule.setDestinationMinAddress(self.getChildElementOptionalPositiveInteger(element, "DESTINATION-MIN-ADDRESS"))
        rule.setInverseProtocolVersion(self.getChildElementOptionalPositiveInteger(element, "INVERSE-PROTOCOL-VERSION"))
        rule.setPayloadLength(self.getChildElementOptionalPositiveInteger(element, "PAYLOAD-LENGTH"))
        rule.setPayloadType(self.getChildElementOptionalPositiveInteger(element, "PAYLOAD-TYPE"))
        rule.setProtocolVersion(self.getChildElementOptionalPositiveInteger(element, "PROTOCOL-VERSION"))
        rule.setSourceMaxAddress(self.getChildElementOptionalPositiveInteger(element, "SOURCE-MAX-ADDRESS"))
        rule.setSourceMinAddress(self.getChildElementOptionalPositiveInteger(element, "SOURCE-MIN-ADDRESS"))
        rule.setUdsService(self.getChildElementOptionalPositiveInteger(element, "UDS-SERVICE"))

    def readTransportLayerRule(self, element: ET.Element, rule: TransportLayerRule):
        self.readARObject(element, rule)
        rule.setChecksumVerification(self.getChildElementOptionalBooleanValue(element, "CHECKSUM-VERIFICATION"))
        rule.setMaxDestinationPortNumber(self.getChildElementOptionalPositiveInteger(element, "MAX-DESTINATION-PORT-NUMBER"))
        rule.setMaxSourcePortNumber(self.getChildElementOptionalPositiveInteger(element, "MAX-SOURCE-PORT-NUMBER"))
        rule.setMinDestinationPortNumber(self.getChildElementOptionalPositiveInteger(element, "MIN-DESTINATION-PORT-NUMBER"))
        rule.setMinSourcePortNumber(self.getChildElementOptionalPositiveInteger(element, "MIN-SOURCE-PORT-NUMBER"))

    def readTcpRule(self, element: ET.Element, rule: TcpRule):
        self.readTransportLayerRule(element, rule)
        rule.setNumberOfParallelTcpSessions(self.getChildElementOptionalPositiveInteger(element, "NUMBER-OF-PARALLEL-TCP-SESSIONS"))
        rule.setStateManagementBasedOnTcpFlags(self.getChildElementOptionalBooleanValue(element, "STATE-MANAGEMENT-BASED-ON-TCP-FLAGS"))
        rule.setTimeoutCheck(self.getChildElementOptionalPositiveInteger(element, "TIMEOUT-CHECK"))

    def readUdpRule(self, element: ET.Element, rule: UdpRule):
        self.readTransportLayerRule(element, rule)

    def readIcmpRule(self, element: ET.Element, rule: IcmpRule):
        self.readARObject(element, rule)
        rule.setChecksumVerification(self.getChildElementOptionalBooleanValue(element, "CHECKSUM-VERIFICATION"))
        rule.setCode(self.getChildElementOptionalPositiveInteger(element, "CODE"))
        rule.setType(self.getChildElementOptionalPositiveInteger(element, "TYPE"))

    def readIpv4Rule(self, element: ET.Element, rule: Ipv4Rule):
        self.readARObject(element, rule)
        rule.setChecksumVerification(self.getChildElementOptionalBooleanValue(element, "CHECKSUM-VERIFICATION"))
        destination_ip_address = self.getChildElementOptionalLiteral(element, "DESTINATION-IP-ADDRESS")
        if destination_ip_address is not None:
            ip4_address = Ip4AddressString()
            ip4_address.setValue(destination_ip_address.getValue())
            rule.setDestinationIpAddress(ip4_address)
        destination_network_mask = self.getChildElementOptionalLiteral(element, "DESTINATION-NETWORK-MASK")
        if destination_network_mask is not None:
            ip4_address = Ip4AddressString()
            ip4_address.setValue(destination_network_mask.getValue())
            rule.setDestinationNetworkMask(ip4_address)
        rule.setDifferentiatedServiceCodePoint(self.getChildElementOptionalPositiveInteger(element, "DIFFERENTIATED-SERVICE-CODE-POINT"))
        rule.setDoNotFragment(self.getChildElementOptionalBooleanValue(element, "DO-NOT-FRAGMENT"))
        rule.setExplicitCongestionNotification(self.getChildElementOptionalPositiveInteger(element, "EXPLICIT-CONGESTION-NOTIFICATION"))
        child = self.find(element, "ICMP-RULE")
        if child is not None:
            icmp_rule = IcmpRule()
            self.readIcmpRule(child, icmp_rule)
            rule.setIcmpRule(icmp_rule)
        rule.setInternetHeaderLength(self.getChildElementOptionalPositiveInteger(element, "INTERNET-HEADER-LENGTH"))
        rule.setMoreFragments(self.getChildElementOptionalBooleanValue(element, "MORE-FRAGMENTS"))
        rule.setProtocol(self.getChildElementOptionalPositiveInteger(element, "PROTOCOL"))
        source_ip_address = self.getChildElementOptionalLiteral(element, "SOURCE-IP-ADDRESS")
        if source_ip_address is not None:
            ip4_address = Ip4AddressString()
            ip4_address.setValue(source_ip_address.getValue())
            rule.setSourceIpAddress(ip4_address)
        source_network_mask = self.getChildElementOptionalLiteral(element, "SOURCE-NETWORK-MASK")
        if source_network_mask is not None:
            ip4_address = Ip4AddressString()
            ip4_address.setValue(source_network_mask.getValue())
            rule.setSourceNetworkMask(ip4_address)
        rule.setTtlMax(self.getChildElementOptionalPositiveInteger(element, "TTL-MAX"))
        rule.setTtlMin(self.getChildElementOptionalPositiveInteger(element, "TTL-MIN"))

    def readIpv6Rule(self, element: ET.Element, rule: Ipv6Rule):
        self.readARObject(element, rule)
        destination_ip_address = self.getChildElementOptionalLiteral(element, "DESTINATION-IP-ADDRESS")
        if destination_ip_address is not None:
            ip6_address = Ip6AddressString()
            ip6_address.setValue(destination_ip_address.getValue())
            rule.setDestinationIpAddress(ip6_address)
        destination_network_mask = self.getChildElementOptionalLiteral(element, "DESTINATION-NETWORK-MASK")
        if destination_network_mask is not None:
            ip6_address = Ip6AddressString()
            ip6_address.setValue(destination_network_mask.getValue())
            rule.setDestinationNetworkMask(ip6_address)
        rule.setFlowLabel(self.getChildElementOptionalPositiveInteger(element, "FLOW-LABEL"))
        rule.setHopLimit(self.getChildElementOptionalPositiveInteger(element, "HOP-LIMIT"))
        child = self.find(element, "ICMP-RULE")
        if child is not None:
            icmp_rule = IcmpRule()
            self.readIcmpRule(child, icmp_rule)
            rule.setIcmpRule(icmp_rule)
        rule.setNextHeader(self.getChildElementOptionalPositiveInteger(element, "NEXT-HEADER"))
        source_ip_address = self.getChildElementOptionalLiteral(element, "SOURCE-IP-ADDRESS")
        if source_ip_address is not None:
            ip6_address = Ip6AddressString()
            ip6_address.setValue(source_ip_address.getValue())
            rule.setSourceIpAddress(ip6_address)
        source_network_mask = self.getChildElementOptionalLiteral(element, "SOURCE-NETWORK-MASK")
        if source_network_mask is not None:
            ip6_address = Ip6AddressString()
            ip6_address.setValue(source_network_mask.getValue())
            rule.setSourceNetworkMask(ip6_address)
        rule.setTrafficClass(self.getChildElementOptionalPositiveInteger(element, "TRAFFIC-CLASS"))

    def readFirewallRule(self, element: ET.Element, rule: FirewallRule):
        self.readIdentifiable(element, rule)
        rule.setBucketSize(self.getChildElementOptionalPositiveInteger(element, "BUCKET-SIZE"))
        child = self.find(element, "DATA-LINK-LAYER-RULE")
        if child is not None:
            data_link_layer_rule = DataLinkLayerRule()
            self.readDataLinkLayerRule(child, data_link_layer_rule)
            rule.setDataLinkLayerRule(data_link_layer_rule)
        child = self.find(element, "DDS-RULE")
        if child is not None:
            rule.setDdsRule(DdsRule())
        child = self.find(element, "DO-IP-RULE")
        if child is not None:
            do_ip_rule = DoIpRule()
            self.readDoIpRule(child, do_ip_rule)
            rule.setDoIpRule(do_ip_rule)
        child = self.find(element, "NETWORK-LAYER-RULE")
        if child is not None:
            ipv4_rule = self.find(child, "IPV-4-RULE")
            if ipv4_rule is not None:
                rule_obj: ARObject = Ipv4Rule()
                self.readIpv4Rule(ipv4_rule, cast(Ipv4Rule, rule_obj))
                rule.setNetworkLayerRule(cast(Optional[NetworkLayerRule], rule_obj))
            elif self.find(child, "IPV-6-RULE") is not None:
                rule_obj = Ipv6Rule()
                self.readIpv6Rule(cast(ET.Element, self.find(child, "IPV-6-RULE")), rule_obj)
                rule.setNetworkLayerRule(rule_obj)
            else:
                network_rule = NetworkLayerRule()
                self.readARObject(child, network_rule)
                rule.setNetworkLayerRule(network_rule)
        payload_rules = self.find(element, "PAYLOAD-BYTE-PATTERN-RULES")
        if payload_rules is not None:
            for child in self.findall(payload_rules, "PAYLOAD-BYTE-PATTERN-RULE"):
                payload_rule = PayloadBytePatternRule()
                self.readPayloadBytePatternRule(child, payload_rule)
                rule.addPayloadBytePatternRule(payload_rule)
        rule.setRefillAmount(self.getChildElementOptionalPositiveInteger(element, "REFILL-AMOUNT"))
        child = self.find(element, "SOMEIP-RULE")
        if child is not None:
            someip_rule = SomeipProtocolRule()
            self.readSomeipProtocolRule(child, someip_rule)
            rule.setSomeipRule(someip_rule)
        child = self.find(element, "SOMEIP-SD-RULE")
        if child is not None:
            someip_sd_rule = SomeipSdRule()
            self.readSomeipSdRule(child, someip_sd_rule)
            rule.setSomeipSdRule(someip_sd_rule)
        child = self.find(element, "TRANSPORT-LAYER-RULE")
        if child is not None:
            tcp_rule = self.find(child, "TCP-RULE")
            if tcp_rule is not None:
                rule_obj = TcpRule()
                self.readTcpRule(tcp_rule, rule_obj)
                rule.setTransportLayerRule(rule_obj)
            elif self.find(child, "UDP-RULE") is not None:
                udp_rule = UdpRule()
                self.readUdpRule(cast(ET.Element, self.find(child, "UDP-RULE")), udp_rule)
                rule.setTransportLayerRule(udp_rule)
            else:
                transport_rule = TransportLayerRule()
                self.readTransportLayerRule(child, transport_rule)
                rule.setTransportLayerRule(transport_rule)

    def readBlueprintMappingSet(self, element: ET.Element, blueprint_mapping_set: BlueprintMappingSet):
        self.readIdentifiable(element, blueprint_mapping_set)
        maps_parent = self.find(element, "BLUEPRINT-MAPS")
        if maps_parent is not None:
            for map_element in list(maps_parent):
                tag_name = self.getTagName(map_element)
                if tag_name == "BLUEPRINT-MAPPING":
                    blueprint_map: ARObject = BlueprintMapping()
                    self.readBlueprintMapping(map_element, cast(BlueprintMapping, blueprint_map))
                    blueprint_mapping_set.addBlueprintMap(cast(Optional[AtpBlueprintMapping], blueprint_map))
                elif tag_name == "PORT-INTERFACE-BLUEPRINT-MAPPING":
                    blueprint_map = PortInterfaceBlueprintMapping()
                    self.readPortInterfaceBlueprintMapping(map_element, blueprint_map)
                    blueprint_mapping_set.addBlueprintMap(blueprint_map)
                elif tag_name == "PORT-PROTOTYPE-BLUEPRINT-MAPPING":
                    blueprint_map = PortPrototypeBlueprintMapping()
                    self.readPortPrototypeBlueprintMapping(map_element, blueprint_map)
                    blueprint_mapping_set.addBlueprintMap(blueprint_map)

    def readConstantSpecificationMappingSet(self, element: ET.Element, constant_specification_mapping_set: ConstantSpecificationMappingSet):
        self.readIdentifiable(element, constant_specification_mapping_set)
        mappings_parent = self.find(element, "MAPPINGS")
        if mappings_parent is not None:
            for map_element in self.findall(mappings_parent, "CONSTANT-SPECIFICATION-MAPPING"):
                mapping = self.getConstantSpecificationMapping(map_element)
                constant_specification_mapping_set.addMapping(mapping)

    def readAtpBlueprintMapping(self, element: ET.Element, blueprint_map: AtpBlueprintMapping):
        self.readARObject(element, blueprint_map)

    def readBlueprintMapping(self, element: ET.Element, blueprint_map: BlueprintMapping):
        self.readAtpBlueprintMapping(element, blueprint_map)
        blueprint_map.setBlueprintRef(self.getChildElementOptionalRefType(element, "BLUEPRINT-REF"))
        blueprint_map.setDerivedObjectRef(self.getChildElementOptionalRefType(element, "DERIVED-OBJECT-REF"))

    def readPortInterfaceBlueprintMapping(self, element: ET.Element, blueprint_map: PortInterfaceBlueprintMapping):
        self.readAtpBlueprintMapping(element, blueprint_map)
        blueprint_map.setPortInterfaceBlueprintRef(self.getChildElementOptionalRefType(element, "PORT-INTERFACE-BLUEPRINT-REF"))
        blueprint_map.setDerivedPortInterfaceRef(self.getChildElementOptionalRefType(element, "DERIVED-PORT-INTERFACE-REF"))

    def readPortPrototypeBlueprintMapping(self, element: ET.Element, blueprint_map: PortPrototypeBlueprintMapping):
        self.readAtpBlueprintMapping(element, blueprint_map)
        blueprint_map.setPortPrototypeBlueprintRef(self.getChildElementOptionalRefType(element, "PORT-PROTOTYPE-BLUEPRINT-REF"))
        blueprint_map.setDerivedPortPrototypeRef(self.getChildElementOptionalRefType(element, "DERIVED-PORT-PROTOTYPE-REF"))

    def readStateDependentFirewall(self, element: ET.Element, firewall: StateDependentFirewall):
        self.readIdentifiable(element, firewall)
        default_action = self.getChildElementOptionalLiteral(element, "DEFAULT-ACTION")
        if default_action is not None:
            firewall.setDefaultAction(FirewallActionEnum().setValue(default_action.getValue()))
        props_parent = self.find(element, "FIREWALL-RULE-PROPSS")
        if props_parent is not None:
            for props_element in self.findall(props_parent, "FIREWALL-RULE-PROPS"):
                props = FirewallRuleProps()
                self.readFirewallRuleProps(props_element, props)
                firewall.addFirewallRuleProps(props)
        refs_parent = self.find(element, "FIREWALL-STATE-MODE-DECLARATION-REFS")
        if refs_parent is not None:
            for ref in self.getChildElementRefTypeList(refs_parent, "FIREWALL-STATE-MODE-DECLARATION-REF"):
                firewall.addFirewallStateModeDeclarationRef(ref)

    def readFirewallRuleProps(self, element: ET.Element, props: FirewallRuleProps):
        action = self.getChildElementOptionalLiteral(element, "ACTION")
        if action is not None:
            props.setAction(FirewallActionEnum().setValue(action.getValue()))
        egress_refs_parent = self.find(element, "MATCHING-EGRESS-RULE-REFS")
        if egress_refs_parent is not None:
            for ref in self.getChildElementRefTypeList(egress_refs_parent, "MATCHING-EGRESS-RULE-REF"):
                props.addMatchingEgressRuleRef(ref)
        ingress_refs_parent = self.find(element, "MATCHING-INGRESS-RULE-REFS")
        if ingress_refs_parent is not None:
            for ref in self.getChildElementRefTypeList(ingress_refs_parent, "MATCHING-INGRESS-RULE-REF"):
                props.addMatchingIngressRuleRef(ref)

    def readIdsPlatformInstantiation(self, element: ET.Element, ar_element: IdsPlatformInstantiation):
        self.readIdentifiable(element, ar_element)
        refs_parent = self.find(element, "NETWORK-INTERFACE-REFS")
        if refs_parent is not None:
            for ref in self.getChildElementRefTypeList(refs_parent, "NETWORK-INTERFACE-REF"):
                ar_element.addNetworkInterfaceRef(ref)
        time_bases_element = self.find(element, "TIME-BASES")
        if time_bases_element is not None:
            conditional_element = self.find(time_bases_element, "TIME-BASE-RESOURCE-REF-CONDITIONAL")
            if conditional_element is not None:
                ar_element.setTimeBaseRef(self.getChildElementOptionalRefType(conditional_element, "TIME-BASE-RESOURCE-REF"))

    def readIdsmModuleInstantiation(self, element: ET.Element, instantiation: IdsmModuleInstantiation):
        self.readIdsPlatformInstantiation(element, instantiation)

    def readPlatformModuleEthernetEndpointConfiguration(self, element: ET.Element, configuration: PlatformModuleEthernetEndpointConfiguration):
        self.readIdentifiable(element, configuration)
        configuration.setCommunicationConnectorRef(self.getChildElementOptionalRefType(element, "COMMUNICATION-CONNECTOR-REF"))
        ipv4_address = self.getChildElementOptionalLiteral(element, "IPV-4-MULTICAST-IP-ADDRESS")
        if ipv4_address is not None:
            configuration.setIpv4MulticastIpAddress(Ip4AddressString().setValue(ipv4_address.getValue()))
        ipv6_address = self.getChildElementOptionalLiteral(element, "IPV-6-MULTICAST-IP-ADDRESS")
        if ipv6_address is not None:
            configuration.setIpv6MulticastIpAddress(Ip6AddressString().setValue(ipv6_address.getValue()))

    def readMcFunction(self, element: ET.Element, func: McFunction):
        self.readIdentifiable(element, func)
        def_calprm_set_element = self.find(element, "DEF-CALPRM-SET")
        if def_calprm_set_element is not None:
            def_calprm_set = McFunctionDataRefSet()
            self.readMcFunctionDataRefSet(def_calprm_set_element, def_calprm_set)
            func.setDefCalprmSet(def_calprm_set)
        ref_calprm_set_element = self.find(element, "REF-CALPRM-SET")
        if ref_calprm_set_element is not None:
            ref_calprm_set = McFunctionDataRefSet()
            self.readMcFunctionDataRefSet(ref_calprm_set_element, ref_calprm_set)
            func.setRefCalprmSet(ref_calprm_set)
        in_measurement_set_element = self.find(element, "IN-MEASUREMENT-SET")
        if in_measurement_set_element is not None:
            in_measurement_set = McFunctionDataRefSet()
            self.readMcFunctionDataRefSet(in_measurement_set_element, in_measurement_set)
            func.setInMeasurementSet(in_measurement_set)
        loc_measurement_set_element = self.find(element, "LOC-MEASUREMENT-SET")
        if loc_measurement_set_element is not None:
            loc_measurement_set = McFunctionDataRefSet()
            self.readMcFunctionDataRefSet(loc_measurement_set_element, loc_measurement_set)
            func.setLocMeasurementSet(loc_measurement_set)
        out_measurement_set_element = self.find(element, "OUT-MEASUREMENT-SET")
        if out_measurement_set_element is not None:
            out_measurement_set = McFunctionDataRefSet()
            self.readMcFunctionDataRefSet(out_measurement_set_element, out_measurement_set)
            func.setOutMeasurementSet(out_measurement_set)
        for ref in self.getChildElementRefTypeList(element, "SUB-FUNCTION-REFS/SUB-FUNCTION-REF"):
            func.addSubFunctionRef(ref)

    def readMcFunctionDataRefSet(self, element: ET.Element, data_ref_set: McFunctionDataRefSet):
        conditional_element = self.find(element, "MC-FUNCTION-DATA-REF-SET-VARIANTS/MC-FUNCTION-DATA-REF-SET-CONDITIONAL")
        if conditional_element is None:
            return
        for ref in self.getChildElementRefTypeList(conditional_element, "FLAT-MAP-ENTRY-REFS/FLAT-MAP-ENTRY-REF"):
            data_ref_set.addFlatMapEntryRef(ref)
        for ref in self.getChildElementRefTypeList(conditional_element, "MC-DATA-INSTANCE-REFS/MC-DATA-INSTANCE-REF"):
            data_ref_set.addMcDataInstanceRef(ref)

    def readMcGroup(self, element: ET.Element, group: McGroup):
        self.readIdentifiable(element, group)
        for ref in self.getChildElementRefTypeList(element, "SUB-GROUP-REFS/SUB-GROUP-REF"):
            group.addSubGroupRef(ref)
        ref_calprm_set_element = self.find(element, "REF-CALPRM-SET")
        if ref_calprm_set_element is not None:
            ref_calprm_set = McGroupDataRefSet()
            self.readMcGroupDataRefSet(ref_calprm_set_element, ref_calprm_set)
            group.setRefCalprmSet(ref_calprm_set)
        ref_measurement_set_element = self.find(element, "REF-MEASUREMENT-SET")
        if ref_measurement_set_element is not None:
            ref_measurement_set = McGroupDataRefSet()
            self.readMcGroupDataRefSet(ref_measurement_set_element, ref_measurement_set)
            group.setRefMeasurementSet(ref_measurement_set)
        for ref in self.getChildElementRefTypeList(element, "MC-FUNCTION-REFS/MC-FUNCTION-REF"):
            group.addMcFunctionRef(ref)

    def readMcGroupDataRefSet(self, element: ET.Element, data_ref_set: McGroupDataRefSet):
        conditional_element = self.find(element, "MC-GROUP-DATA-REF-SET-VARIANTS/MC-GROUP-DATA-REF-SET-CONDITIONAL")
        if conditional_element is None:
            return
        for ref in self.getChildElementRefTypeList(conditional_element, "FLAT-MAP-ENTRY-REFS/FLAT-MAP-ENTRY-REF"):
            data_ref_set.addFlatMapEntryRef(ref)
        for ref in self.getChildElementRefTypeList(conditional_element, "MC-DATA-INSTANCE-REFS/MC-DATA-INSTANCE-REF"):
            data_ref_set.addMcDataInstanceRef(ref)

    def readReferenceBases(self, element: ET.Element, parent: ARPackage):
        for child_element in self.findall(element, "REFERENCE-BASES/REFERENCE-BASE"):
            base = ReferenceBase()
            base.setShortLabel(cast(Optional[Identifier], self.getChildElementOptionalLiteral(child_element, "SHORT-LABEL")))
            base.setIsDefault(self.getChildElementOptionalBooleanValue(child_element, "IS-DEFAULT"))
            base.setIsGlobal(self.getChildElementOptionalBooleanValue(child_element, "IS-GLOBAL"))
            base.setBaseIsThisPackage(self.getChildElementOptionalBooleanValue(child_element, "BASE-IS-THIS-PACKAGE"))
            for global_in_package_ref in self.getChildElementRefTypeList(child_element, "GLOBAL-IN-PACKAGE-REFS/GLOBAL-IN-PACKAGE-REF"):
                base.addGlobalInPackageRef(global_in_package_ref)
            for global_element in self.findall(child_element, "GLOBAL-ELEMENTS/GLOBAL-ELEMENT"):
                literal = ReferrableSubtypesEnum()
                literal.setValue(global_element.text)
                base.addGlobalElement(literal)
            base.setPackageRef(self.getChildElementOptionalRefType(child_element, "PACKAGE-REF"))
            parent.addReferenceBase(base)

    def readAclPermission(self, element: ET.Element, acl_permission: AclPermission) -> AclPermission:
        self.logger.debug("Read AclPermission <%s>" % acl_permission.getShortName())
        self.readIdentifiable(element, acl_permission)
        for child_element in self.findall(element, "ACL-CONTEXTS/ACL-CONTEXT"):
            acl_permission.addAclContext(NameToken().setValue(child_element.text))
        for object_ref in self.getChildElementRefTypeList(element, "ACL-OBJECT-REFS/ACL-OBJECT-REF"):
            acl_permission.addAclObjectRef(object_ref)
        for operation_ref in self.getChildElementRefTypeList(element, "ACL-OPERATION-REFS/ACL-OPERATION-REF"):
            acl_permission.addAclOperationRef(operation_ref)
        for role_ref in self.getChildElementRefTypeList(element, "ACL-ROLE-REFS/ACL-ROLE-REF"):
            acl_permission.addAclRoleRef(role_ref)
        acl_scope = self.find(element, "ACL-SCOPE")
        if acl_scope is not None:
            literal = None
            for literal_name, token in ACL_SCOPE_XML_MAP.items():
                if token == acl_scope.text:
                    literal = literal_name
                    break
            if literal is not None:
                acl_permission.setAclScope(AclScopeEnum().setValue(literal))
            else:
                self.notImplemented("Unsupported ACL-SCOPE <%s>" % acl_scope.text)
        return acl_permission

    def readAclObjectSet(self, element: ET.Element, acl_object_set: AclObjectSet) -> AclObjectSet:
        self.logger.debug("Read AclObjectSet <%s>" % acl_object_set.getShortName())
        self.readIdentifiable(element, acl_object_set)
        for child_element in self.findall(element, "ACL-OBJECT-CLASSS/ACL-OBJECT-CLASS"):
            literal: ARLiteral = ReferrableSubtypesEnum()
            literal.setValue(child_element.text)
            acl_object_set.addAclObjectClass(cast(Optional[ReferrableSubtypesEnum], literal))
        acl_scope = self.find(element, "ACL-SCOPE")
        if acl_scope is not None:
            acl_literal: Optional[str] = None
            for literal_name, token in ACL_SCOPE_XML_MAP.items():
                if token == acl_scope.text:
                    acl_literal = literal_name
                    break
            if acl_literal is not None:
                acl_object_set.setAclScope(AclScopeEnum().setValue(acl_literal))
            else:
                self.notImplemented("Unsupported ACL-SCOPE <%s>" % acl_scope.text)
        acl_object_set.setCollectionRef(self.getChildElementOptionalRefType(element, "COLLECTION-REF"))
        for blueprint_ref in self.getChildElementRefTypeList(element, "DERIVED-FROM-BLUEPRINT-REFS/DERIVED-FROM-BLUEPRINT-REF"):
            acl_object_set.addDerivedFromBlueprintRef(blueprint_ref)
        for child_element in self.findall(element, "ENGINEERING-OBJECTS/AUTOSAR-ENGINEERING-OBJECT"):
            acl_object_set.addEngineeringObject(self.getAutosarEngineeringObject(child_element))
        for object_definition_ref in self.getChildElementRefTypeList(element, "OBJECT-DEFINITION-REFS/OBJECT-DEFINITION-REF"):
            acl_object_set.addObjectDefinitionRef(object_definition_ref)
        for object_ref in self.getChildElementRefTypeList(element, "OBJECT-REFS/OBJECT-REF"):
            acl_object_set.addObjectRef(object_ref)
        return acl_object_set

    def readAclOperation(self, element: ET.Element, acl_operation: AclOperation) -> AclOperation:
        self.logger.debug("Read AclOperation <%s>" % acl_operation.getShortName())
        self.readIdentifiable(element, acl_operation)
        for implied_operation_ref in self.getChildElementRefTypeList(element, "IMPLIED-OPERATION-REFS/IMPLIED-OPERATION-REF"):
            acl_operation.addImpliedOperationRef(implied_operation_ref)
        return acl_operation

    def readAclRole(self, element: ET.Element, acl_role: AclRole) -> AclRole:
        self.logger.debug("Read AclRole <%s>" % acl_role.getShortName())
        self.readIdentifiable(element, acl_role)
        acl_role.setLdapUrl(self.getChildElementOptionalUriString(element, "LDAP-URL"))
        return acl_role

    def readLifeCycleState(self, element: ET.Element, lc_state: LifeCycleState) -> LifeCycleState:
        self.logger.debug("Read LifeCycleState <%s>" % lc_state.getShortName())
        self.readIdentifiable(element, lc_state)
        return lc_state

    def readLifeCycleStateDefinitionGroupLcStates(self, element: ET.Element, group: LifeCycleStateDefinitionGroup):
        for child_element in self.findall(element, "LC-STATES/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "LIFE-CYCLE-STATE":
                lc_state = group.createLcState(self.getShortName(child_element))
                self.readLifeCycleState(child_element, lc_state)
            else:
                self.notImplemented("Unsupported LifeCycleState <%s>" % tag_name)

    def readLifeCycleStateDefinitionGroup(self, element: ET.Element, group: LifeCycleStateDefinitionGroup) -> LifeCycleStateDefinitionGroup:
        self.logger.debug("Read LifeCycleStateDefinitionGroup <%s>" % group.getShortName())
        self.readIdentifiable(element, group)
        self.readLifeCycleStateDefinitionGroupLcStates(element, group)
        return group

    def readViewMap(self, element: ET.Element, view_map: ViewMap) -> ViewMap:
        self.logger.debug("Read ViewMap <%s>" % view_map.getShortName())
        self.readIdentifiable(element, view_map)
        view_map.setRole(self.getChildElementOptionalIdentifier(element, "ROLE"))
        for first_element_ref in self.getChildElementRefTypeList(element, "FIRST-ELEMENT-REFS/FIRST-ELEMENT-REF"):
            view_map.addFirstElementRef(first_element_ref)
        for second_element_ref in self.getChildElementRefTypeList(element, "SECOND-ELEMENT-REFS/SECOND-ELEMENT-REF"):
            view_map.addSecondElementRef(second_element_ref)
        for child_element in self.findall(element, "FIRST-ELEMENT-INSTANCE-IREFS/FIRST-ELEMENT-INSTANCE-IREF"):
            view_map.addFirstElementIRef(self.getAnyInstanceRefFromElement(child_element))
        for child_element in self.findall(element, "SECOND-ELEMENT-INSTANCE-IREFS/SECOND-ELEMENT-INSTANCE-IREF"):
            view_map.addSecondElementIRef(self.getAnyInstanceRefFromElement(child_element))
        return view_map

    def readViewMapSetViewMaps(self, element: ET.Element, view_map_set: ViewMapSet):
        for child_element in self.findall(element, "VIEW-MAPS/*"):
            tag_name = self.getTagName(child_element)
            if tag_name == "VIEW-MAP":
                view_map = view_map_set.createViewMap(self.getShortName(child_element))
                self.readViewMap(child_element, view_map)
            else:
                self.notImplemented("Unsupported ViewMap <%s>" % tag_name)

    def readViewMapSet(self, element: ET.Element, view_map_set: ViewMapSet) -> ViewMapSet:
        self.logger.debug("Read ViewMapSet <%s>" % view_map_set.getShortName())
        self.readIdentifiable(element, view_map_set)
        self.readViewMapSetViewMaps(element, view_map_set)
        return view_map_set

    def readCollection(self, element: ET.Element, collection: Collection) -> Collection:
        self.logger.debug("Read Collection <%s>" % collection.getShortName())
        self.readIdentifiable(element, collection)
        auto_collect = self.find(element, "AUTO-COLLECT")
        if auto_collect is not None:
            literal = None
            for literal_name, token in AUTO_COLLECT_XML_MAP.items():
                if token == auto_collect.text:
                    literal = literal_name
                    break
            if literal is not None:
                collection.setAutoCollect(AutoCollectEnum().setValue(literal))
            else:
                self.notImplemented("Unsupported AUTO-COLLECT <%s>" % auto_collect.text)
        collection_semantics = self.find(element, "COLLECTION-SEMANTICS")
        if collection_semantics is not None:
            collection.setCollectionSemantics(NameToken().setValue(collection_semantics.text))
        collection.setElementRole(self.getChildElementOptionalIdentifier(element, "ELEMENT-ROLE"))
        for element_ref in self.getChildElementRefTypeList(element, "ELEMENT-REFS/ELEMENT-REF"):
            collection.addElementRef(element_ref)
        for source_element_ref in self.getChildElementRefTypeList(element, "SOURCE-ELEMENT-REFS/SOURCE-ELEMENT-REF"):
            collection.addSourceElementRef(source_element_ref)
        for child_element in self.findall(element, "COLLECTED-INSTANCE-IREFS/COLLECTED-INSTANCE-IREF"):
            collection.addCollectedInstanceIRef(self.getAnyInstanceRefFromElement(child_element))
        for child_element in self.findall(element, "SOURCE-INSTANCE-IREFS/SOURCE-INSTANCE-IREF"):
            collection.addSourceInstanceIRef(self.getAnyInstanceRefFromElement(child_element))
        return collection

    def readARPackage(self, element: ET.Element, ar_package: ARPackage):
        self.logger.debug("Read ARPackages <%s>" % ar_package.getFullName())

        self.readIdentifiable(element, ar_package)
        self.readARPackages(element, ar_package)
        self.readARPackageElements(element, ar_package)
        self.readReferenceBases(element, ar_package)

    def readARPackages(self, element: ET.Element, parent: ARPackage):
        child_elements = self.findall(element, "AR-PACKAGES/*")
        if len(child_elements) == 0:
            # Legacy R3.x releases: TOP-LEVEL-PACKAGES at document root, SUB-PACKAGES
            # inside an AR-PACKAGE (autosar/R3.2.3/xsd/AUTOSAR.xsd L315/L270).
            if isinstance(parent, AUTOSAR):
                child_elements = self.findall(element, "TOP-LEVEL-PACKAGES/*")
            else:
                child_elements = self.findall(element, "SUB-PACKAGES/*")
        for child_element in child_elements:
            tag_name = self.getTagName(child_element)
            if tag_name == "AR-PACKAGE":
                ar_package = parent.createARPackage(self.getShortName(child_element))
                self.readARPackage(child_element, ar_package)
            else:
                self.notImplemented("Unsupported ARPackage <%s>" % tag_name)

    def _validateARXML(self, filename):
        if self.options["validate"] is False:
            return
        with open(filename, "rb") as f:
            data = f.read()
        validator = ARXMLValidator.for_document(data)
        if validator is None:
            self.logger.warning("No XSD schema found for <%s>; validation skipped" % filename)
            return
        errors = validator.validate_bytes(data)
        if not errors:
            return
        if self.options["warning"] is True:
            for error in errors:
                self.logger.warning("Schema error in <%s> line %s, col %s: %s" % (filename, error.line, error.column, error.message))
            return
        for error in errors:
            self.logger.error("Schema error in <%s> line %s, col %s: %s" % (filename, error.line, error.column, error.message))
        first = errors[0]
        raise ValueError("ARXML file <%s> failed schema validation with %d error(s) (first: line %s, col %s: %s)" % (filename, len(errors), first.line, first.column, first.message))

    def load(self, filename, document: AUTOSAR):
        self.logger.info("Loading %s ..." % os.path.realpath(filename))

        self._validateARXML(filename)

        tree = ET.parse(filename)
        root = tree.getroot()
        if self.getPureTagName(root.tag) != "AUTOSAR":
            self.raiseError("Invalid ARXML file <%s>" % filename)

        self.detectNamespace(root)
        self.getAUTOSARInfo(root, document)
        document.setAdminData(self.getAdminData(root, "ADMIN-DATA"))
        document.setFileInfoComment(self.getFileInfoComment(root, "FILE-INFO-COMMENT"))
        document.setIntroduction(self.getDocumentationBlock(root, "INTRODUCTION"))
        self.readARPackages(root, cast(ARPackage, document))

        document.reload()
